import React, { useEffect, useState } from "react";
import { Toaster } from "react-hot-toast";
import AuthService from "./Auth/auth";
import { useDispatch } from "react-redux";
import { setUser, logout, setLoading } from "./redux/userSlice";
import { fetchProfilePicThunk } from "./redux/userSlice";
import Body from "./componets/Body";
import { LoaderPinwheel } from "lucide-react";

const App = () => {
  const dispatch = useDispatch();
  const [isAuthenticated, setIsAuthenticated] = useState(null);

  useEffect(() => {
    const checkAuth = async () => {
      try {
        const authResponse = await AuthService.getCurrentUser();
        setIsAuthenticated(authResponse.authStatus);
        if (authResponse.authStatus) {
          dispatch(setUser(authResponse.data.user));
          dispatch(setLoading(true));
          dispatch(fetchProfilePicThunk());
          dispatch(setLoading(false));
        } else {
          dispatch(logout());
        }
      } catch (error) {
        console.error("Error checking authentication:", error);
        setIsAuthenticated(false);
      }
    };

    checkAuth();
  }, [dispatch]);

  if (isAuthenticated === null) {
    return (
      <div className="flex flex-col items-center justify-center w-full ui-page-height ui-gradient   text-slate-900">
        <LoaderPinwheel size={60} className="animate-spin text-blue-700" />
        <p className="mt-4 text-xl text-blue-700 font-medium">
          Checking authentication...
        </p>
      </div>
    );
  }

  return (
    <div>
      <Body />
      <Toaster
        toastOptions={{
          style: {
            background: "var(--surface)",
            color: "var(--text)",
            border: "1px solid var(--border)",
            borderRadius: "8px",
            fontFamily: "Inter, sans-serif",
            fontSize: "14px",
          },
        }}
      />
    </div>
  );
};

export default App;

import React, { useCallback, useEffect, useState } from "react";
import { useSelector } from "react-redux";
import { useNavigate } from "react-router-dom";
import axiosInstance from "../../utils/axiosInstance";
import toast from "react-hot-toast";
import { BeatLoader } from "react-spinners";

const Admin = () => {
  const user = useSelector((store) => store?.app?.user);
  const navigate = useNavigate();

  const [pendingUsers, setPendingUsers] = useState([]);
  const [currentPage, setCurrentPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [loading, setLoading] = useState(false);
  const [actionLoading, setActionLoading] = useState(false);

  const PAGE_SIZE = 10;

  // Only admin allowed
  useEffect(() => {
    if (user?.role !== "admin") navigate("/");
  }, [user, navigate]);

  // Fetch users with pagination
  const fetchUsers = async (page = 1) => {
    setLoading(true);
    try {
      const response = await axiosInstance.get(
        `/admin/get-pending-users?page=${page}`
      );
      if (response?.data?.success) {
        setPendingUsers(Array.isArray(response?.data?.data) ? response.data.data : []);
        setTotalPages(response?.data?.totalPages || 0);
      } else {
        setPendingUsers([]);
        setTotalPages(0);
      }
    } catch (error) {
      console.error("Error fetching data:", error);
      toast.error("An error occurred while fetching data.");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchUsers(currentPage);
  }, [currentPage]);

  // Accept a single user
  const handleAcceptUser = async (userId) => {
    setActionLoading(userId);
    try {
      const response = await axiosInstance.post(`/admin/accept-request`, {
        userId,
      });
      if (response?.data?.success) {
        toast.success("User accepted successfully.");
        setPendingUsers((prev) => prev?.filter((user) => user?._id !== userId));
      } else {
        toast.error("Failed to accept user.");
      }
    } catch (error) {
      toast.error("An error occurred while accepting user.");
    } finally {
      setActionLoading(false);
    }
  };

  // Decline a single user
  const handleDeclineUser = async (userId) => {
    setActionLoading(userId);
    try {
      const response = await axiosInstance.post(`/admin/decline-request`, {
        userId,
      });
      if (response?.data?.success) {
        toast.success("User declined successfully.");
        setPendingUsers((prev) => prev?.filter((user) => user?._id !== userId));
      } else {
        toast.error("Failed to decline user.");
      }
    } catch (error) {
      toast.error("An error occurred while declining user.");
    } finally {
      setActionLoading(false);
    }
  };

  // Accept all pending users
  const handleAcceptAll = async () => {
    setActionLoading(true);
    try {
      const response = await axiosInstance.post(`/admin/accept-all-requests`);
      if (response?.data?.success) {
        toast.success(response?.data?.message);
        setPendingUsers([]);
        fetchUsers(currentPage);
      } else {
        toast.error("Failed to accept all users.");
      }
    } catch (error) {
      toast.error("An error occurred while accepting all users.");
    } finally {
      setActionLoading(false);
    }
  };

  // Decline all pending users
  const handleDeclineAll = async () => {
    setActionLoading(true);
    try {
      const response = await axiosInstance.post(`/admin/decline-all-requests`);
      if (response?.data?.success) {
        toast.success(response?.data?.message);
        setPendingUsers([]);
        fetchUsers(currentPage);
      } else {
        toast.error("Failed to decline all users.");
      }
    } catch (error) {
      toast.error("An error occurred while declining all users.");
    } finally {
      setActionLoading(false);
    }
  };

  return (
    <>
      <div className="ui-page text-slate-900 ui-page-height overflow-hidden">
        <div className="flex flex-col sm:flex-row sm:justify-between sm:items-center gap-4 sm:gap-0 mb-4 p-6 ui-page-top">
          <h1 className="text-2xl font-bold">Pending User Requests</h1>
          <div className="flex flex-col sm:flex-row gap-2">
            <button
              onClick={handleAcceptAll}
              disabled={pendingUsers?.length === 0}
              className="bg-green-600 text-slate-900 py-2 px-4 rounded-lg hover:bg-green-700 transition disabled:opacity-50"
            >
              {actionLoading ? (
                <BeatLoader size={10} color="#fff" />
              ) : (
                "Accept All"
              )}
            </button>
            <button
              onClick={handleDeclineAll}
              disabled={pendingUsers?.length === 0}
              className="bg-red-600 text-slate-900 py-2 px-4 rounded-lg hover:bg-red-50 transition disabled:opacity-50"
            >
              {actionLoading ? (
                <BeatLoader size={10} color="#fff" />
              ) : (
                "Decline All"
              )}
            </button>
          </div>
        </div>

        <div className="p-4 flex flex-wrap gap-3">
          <button
            className="bg-blue-500 hover:bg-blue-600 text-slate-900 font-bold py-2 px-4 rounded-lg shadow-md focus:outline-none focus:ring-2 focus:ring-blue-300 transition"
            onClick={() => navigate("/registerFaculty")}
          >
            Register Faculty
          </button>
          <button
            className="bg-red-500 hover:bg-red-600 text-slate-900 font-bold py-2 px-4 rounded-lg shadow-md focus:outline-none focus:ring-2 focus:ring-blue-300 transition"
            onClick={() => navigate("/studentinformation")}
          >
            Student Information
          </button>
          <button
            className="bg-purple-600 hover:bg-purple-700 text-slate-900 font-bold py-2 px-4 rounded-lg shadow-md focus:outline-none focus:ring-2 focus:ring-purple-300 transition flex items-center gap-2"
            onClick={() => navigate("/session-management")}
          >
            Session Management
          </button>
        </div>

        {loading ? (
          <div className="flex justify-center items-center h-64">
            <BeatLoader size={15} color="#4A90E2" />
          </div>
        ) : (
          <div className="p-4 overflow-x-auto">
            <table className="min-w-full text-sm sm:text-lg text-left text-slate-600">
              <thead className="ui-page text-slate-600">
                <tr>
                  <th className="py-3 px-6">#</th>
                  <th className="py-3 px-6">Email</th>
                  <th className="py-3 px-6">Name</th>
                  <th className="py-3 px-6">Subject</th>
                  <th className="py-3 px-6">Actions</th>
                </tr>
              </thead>
              <tbody>
                {pendingUsers?.length > 0 ? (
                  pendingUsers?.map((user, index) => (
                    <tr
                      key={user?._id}
                      className={`${
                        index % 2 === 0 ? "ui-page" : "ui-surface"
                      }`}
                    >
                      <td className="py-3 px-6">
                        {(currentPage - 1) * PAGE_SIZE + index + 1}
                      </td>
                      <td className="py-3 px-6 text-slate-600">{user?.email}</td>
                      <td className="capitalize py-3 px-6">{user?.username}</td>
                     
                      <td className="py-3 px-6">{user?.subject}</td>
                      <td className="py-3 px-6 flex gap-2">
                        <button
                          onClick={() => handleAcceptUser(user?._id)}
                          disabled={actionLoading === user?._id}
                          className="bg-green-600 text-slate-900 py-1 px-3 rounded-lg hover:bg-green-700 transition disabled:opacity-50"
                        >
                          {actionLoading === user?._id ? (
                            <BeatLoader size={10} color="#fff" />
                          ) : (
                            "Accept"
                          )}
                        </button>
                        <button
                          onClick={() => handleDeclineUser(user?._id)}
                          disabled={actionLoading === user?._id}
                          className="bg-red-600 text-slate-900 py-1 px-3 rounded-lg hover:bg-red-50 transition disabled:opacity-50"
                        >
                          {actionLoading === user?._id ? (
                            <BeatLoader size={10} color="#fff" />
                          ) : (
                            "Decline"
                          )}
                        </button>
                      </td>
                    </tr>
                  ))
                ) : (
                  <tr>
                    <td
                      colSpan="9"
                      className="py-3 px-6 text-center text-slate-600"
                    >
                      No pending users found.
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        )}

        <div className="flex justify-center mt-4">
          <button
            onClick={() => setCurrentPage((prev) => Math.max(prev - 1, 1))}
            disabled={currentPage === 1}
            className="cursor-pointer ui-surface text-slate-900 py-2 px-4 rounded-lg hover:ui-surface transition disabled:opacity-50"
          >
            Previous
          </button>
          <span className="mx-4 mt-1 text-slate-900">{`Page ${currentPage} of ${totalPages}`}</span>
          <button
            onClick={() =>
              setCurrentPage((prev) => Math?.min(prev + 1, totalPages))
            }
            disabled={currentPage === totalPages}
            className="cursor-pointer ui-surface text-slate-900 py-2 px-4 rounded-lg hover:ui-surface transition disabled:opacity-50"
          >
            Next
          </button>
        </div>
      </div>
    </>
  );
};

export default Admin;

import React from "react";
import Admin from "./Admin";

function AdminPage() {
  return (
    <>
      <section>
        <Admin />
      </section>
    </>
  );
}

export default AdminPage;

import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import axiosInstance from "../../utils/axiosInstance";
import { useSelector } from "react-redux";
import toast from "react-hot-toast";
import { BeatLoader } from "react-spinners";

const AdminRegister = () => {
  const user = useSelector((store) => store.app.user);
  const [facultys, setFacultys] = useState([]);
  const [loading, setLoading] = useState(true);
  const [terminatingId, setTerminatingId] = useState(null);
  const [error, setError] = useState("");
  const [facultyPage, setFacultyPage] = useState(1);
  const [totalFacultyPages, setTotalFacultyPages] = useState(0);
  const [totalFaculty, setTotalFaculty] = useState(0);

  const itemsPerPage = 8;
  const navigate = useNavigate();

  const fetchFacultys = async (page) => {
    try {
      setLoading(true);
      const response = await axiosInstance.post("/admin/get-faculty-by-admin", {
        page,
        limit: itemsPerPage,
      });

      if (response.data.success) {
        // console.log(response.data);
        setFacultys(response.data.facultys);
        setTotalFacultyPages(response.data.totalPages);
        setTotalFaculty(response.data.totalStudents);
      } else {
        setError(response.data.message || "Failed to fetch faculty.");
      }
    } catch (err) {
      setError("An error occurred while fetching faculty.");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchFacultys(facultyPage);
  }, [facultyPage]);

  const handleFacultyClick = (facultyId) => {
    navigate(`/students/${facultyId}`);
  };

  const handleTerminateSession = async (e, facultyId, facultyName) => {
    e.stopPropagation();
    setTerminatingId(facultyId);
    try {
      const res = await axiosInstance.post("/admin/terminate-session", {
        userId: facultyId,
      });
      if (res.data.success) {
        toast.success(
          res.data.message || `Session terminated for ${facultyName}`
        );
        setFacultys((prev) =>
          prev.map((f) => (f._id === facultyId ? { ...f, sessionId: null } : f))
        );
      } else {
        toast.error(res.data.message || "Failed to terminate session");
      }
    } catch (err) {
      console.error("Error terminating session:", err);
      toast.error(
        err?.response?.data?.message || "Failed to terminate session"
      );
    } finally {
      setTerminatingId(null);
    }
  };

  const formatDate = (dateString) => {
    const date = new Date(dateString);
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, "0");
    const day = String(date.getDate()).padStart(2, "0");
    const hours = String(date.getHours()).padStart(2, "0");
    const minutes = String(date.getMinutes()).padStart(2, "0");
    return `${day}-${month}-${year} ${hours}:${minutes}`;
  };

  return (
    <div className="relative ui-page-height ui-page text-slate-900">
      <div className="flex justify-center ui-page-top">
        <h1 className="text-2xl font-bold mb-4">Faculty Register</h1>
      </div>

      <button
        className="py-2 px-6 ml-6 ui-gradient mb-4   text-slate-900 font-semibold rounded-lg shadow-md   active:scale-95 transition transform duration-200"
        onClick={() => navigate(-1)}
      >
        Back
      </button>

      <div className="flex items-center ml-4 text-slate-900 py-2 px-4 rounded-full  text-lg font-semibold">
        <span>Total Number of Faculty Register:</span>
        <span className="ml-2 text-xl font-bold">{totalFaculty}</span>
      </div>

      <div>
        {loading ? (
          <div className="flex justify-center items-center h-64">
            <div className="flex flex-col items-center">
              <div className="animate-spin rounded-full h-16 w-16 border-t-4 border-blue-500 border-opacity-75"></div>
              <p className="mt-4 text-blue-700 text-lg font-medium">
                Loading, please wait...
              </p>
            </div>
          </div>
        ) : (
          <div className="p-4 overflow-x-auto">
            <table className="min-w-full text-lg text-left text-slate-600">
              <thead className="ui-page text-slate-600">
                <tr>
                  <th className="py-3 px-6">#</th>
                  <th className="py-3 px-6">Username</th>
                  <th className="py-3 px-6">Email</th>
                  <th className="py-3 px-6">Branch</th>
                  <th className="py-3 px-6">Subject</th>
                  <th className="py-3 px-6">Session</th>
                  <th className="py-3 px-6">Create Date</th>
                  <th className="py-3 px-6 text-center">Action</th>
                </tr>
              </thead>
              <tbody>
                {facultys.length === 0 ? (
                  <tr>
                    <td
                      colSpan="8"
                      className="py-3 px-6 text-center text-slate-600"
                    >
                      Data not available
                    </td>
                  </tr>
                ) : (
                  facultys.map((faculty, index) => (
                    <tr
                      key={faculty._id}
                      onClick={() => handleFacultyClick(faculty._id)}
                      className={`cursor-pointer ${
                        index % 2 === 0 ? "ui-page" : "ui-surface"
                      } hover:ui-surface transition`}
                    >
                      <td className="py-3 px-6">{index + 1}</td>
                      <td className="py-3 px-6 text-slate-900 font-medium">
                        {faculty.username}
                      </td>
                      <td className="py-3 px-6">{faculty.email}</td>
                      <td className="py-3 px-6">
                        {faculty?.branch?.toUpperCase()}
                      </td>
                      <td className="py-3 px-6">{faculty.subject}</td>
                      <td className="py-3 px-6">
                        {faculty.sessionId ? (
                          <span className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-xs font-semibold bg-emerald-500/10 text-emerald-700 border border-emerald-500/30">
                            <span className="w-1.5 h-1.5 rounded-full bg-emerald-400 animate-pulse"></span>
                            Active
                          </span>
                        ) : (
                          <span className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-xs font-medium ui-surface text-slate-600 border border-slate-200">
                            <span className="w-1.5 h-1.5 rounded-full ui-subtle"></span>
                            Inactive
                          </span>
                        )}
                      </td>
                      <td className="py-3 px-6 text-sm">
                        {formatDate(faculty.createdAt)}
                      </td>
                      <td className="py-3 px-6 text-center">
                        <button
                          onClick={(e) =>
                            handleTerminateSession(
                              e,
                              faculty._id,
                              faculty.username
                            )
                          }
                          disabled={
                            !faculty.sessionId ||
                            terminatingId === faculty._id
                          }
                          className={`px-3 py-1.5 rounded-lg text-xs font-semibold transition ${
                            faculty.sessionId
                              ? "bg-red-600 hover:bg-red-50 text-slate-900 shadow"
                              : "ui-surface text-slate-600 cursor-not-allowed border border-slate-200"
                          }`}
                        >
                          {terminatingId === faculty._id ? (
                            <BeatLoader size={6} color="#fff" />
                          ) : (
                            "Terminate Session"
                          )}
                        </button>
                      </td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          </div>
        )}
      </div>
    </div>
  );
};

export default AdminRegister;

import React, { useEffect, useState, useCallback } from "react";
import { useNavigate } from "react-router-dom";
import { useSelector } from "react-redux";
import axiosInstance from "../../utils/axiosInstance";
import toast from "react-hot-toast";
import { BeatLoader } from "react-spinners";
import { Search, ShieldAlert, UserX, RefreshCw } from "lucide-react";

const SessionManagement = () => {
  const user = useSelector((store) => store.app.user);
  const navigate = useNavigate();

  const [users, setUsers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [terminatingId, setTerminatingId] = useState(null);
  const [search, setSearch] = useState("");
  const [roleFilter, setRoleFilter] = useState("all");
  const [statusFilter, setStatusFilter] = useState("all");
  const [currentPage, setCurrentPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [totalUsers, setTotalUsers] = useState(0);
  const [activeSessionsCount, setActiveSessionsCount] = useState(0);

  const PAGE_SIZE = 10;

  // Only admin allowed
  useEffect(() => {
    if (user?.role !== "admin") {
      navigate("/");
    }
  }, [user, navigate]);

  const fetchUsers = useCallback(
    async (page = 1) => {
      setLoading(true);
      try {
        const queryParams = new URLSearchParams({
          page: page.toString(),
          limit: PAGE_SIZE.toString(),
          search: search.trim(),
          role: roleFilter,
          status: statusFilter,
        });

        const res = await axiosInstance.get(
          `/admin/users-sessions?${queryParams.toString()}`
        );

        if (res.data.success) {
          setUsers(res.data.users || []);
          setTotalPages(res.data.totalPages || 1);
          setTotalUsers(res.data.totalUsers || 0);
          setActiveSessionsCount(res.data.activeSessionsCount || 0);
        } else {
          toast.error(res.data.message || "Failed to fetch user sessions.");
        }
      } catch (error) {
        console.error("Error fetching user sessions:", error);
        toast.error("Failed to load user sessions.");
      } finally {
        setLoading(false);
      }
    },
    [search, roleFilter, statusFilter]
  );

  useEffect(() => {
    fetchUsers(currentPage);
  }, [currentPage, fetchUsers]);

  const handleSearchSubmit = (e) => {
    e.preventDefault();
    setCurrentPage(1);
    fetchUsers(1);
  };

  const handleTerminateSession = async (targetUser) => {
    setTerminatingId(targetUser._id);
    try {
      const res = await axiosInstance.post("/admin/terminate-session", {
        userId: targetUser._id,
      });

      if (res.data.success) {
        toast.success(
          res.data.message ||
            `Session terminated for ${targetUser.username || targetUser.id}.`
        );
        // Update local state instantly
        setUsers((prev) =>
          prev.map((u) =>
            u._id === targetUser._id ? { ...u, hasActiveSession: false } : u
          )
        );
        setActiveSessionsCount((prev) => Math.max(0, prev - 1));
      } else {
        toast.error(res.data.message || "Failed to terminate session.");
      }
    } catch (error) {
      console.error("Error terminating session:", error);
      toast.error(
        error?.response?.data?.message || "An error occurred while terminating session."
      );
    } finally {
      setTerminatingId(null);
    }
  };

  const formatDate = (dateString) => {
    if (!dateString) return "Never";
    const date = new Date(dateString);
    if (isNaN(date.getTime())) return "Never";
    return date.toLocaleString();
  };

  return (
    <div className="ui-page-height ui-page text-slate-900 ui-page-top px-4 sm:px-8 pb-12">
      <div className="max-w-7xl mx-auto">
        {/* Header and Back Button */}
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 mb-6">
          <div>
            <h1 className="text-3xl font-bold flex items-center gap-3">
              <ShieldAlert className="text-blue-700" size={32} />
              Session Management
            </h1>
            <p className="text-slate-600 text-sm mt-1">
              Terminate active sessions for locked-out students (e.g., closed incognito tabs). Admin and faculty accounts support multi-device sessions.
            </p>
          </div>
          <div className="flex gap-3">
            <button
              onClick={() => fetchUsers(currentPage)}
              disabled={loading}
              className="flex items-center gap-2 py-2 px-4 ui-surface hover:ui-surface text-slate-900 rounded-lg border border-slate-200 transition"
              title="Refresh"
            >
              <RefreshCw size={16} className={loading ? "animate-spin" : ""} />
              Refresh
            </button>
            <button
              onClick={() => navigate("/pending-requests")}
              className="py-2 px-6 ui-gradient   text-slate-900 font-semibold rounded-lg shadow-md   transition active:scale-95"
            >
              Back to Admin
            </button>
          </div>
        </div>

        {/* Stats Summary Cards */}
        <div className="grid grid-cols-1 sm:grid-cols-3 gap-4 mb-6">
          <div className="ui-surface border border-slate-200 p-4 rounded-lg flex items-center justify-between">
            <div>
              <p className="text-xs uppercase font-medium text-slate-600">Total Users</p>
              <p className="text-2xl font-bold text-slate-900 mt-1">{totalUsers}</p>
            </div>
            <div className="w-10 h-10 rounded-full bg-blue-500/10 text-blue-700 flex items-center justify-center font-bold">
              {totalUsers}
            </div>
          </div>
          <div className="ui-surface border border-slate-200 p-4 rounded-lg flex items-center justify-between">
            <div>
              <p className="text-xs uppercase font-medium text-green-700">Active Sessions</p>
              <p className="text-2xl font-bold text-green-700 mt-1">{activeSessionsCount}</p>
            </div>
            <div className="w-10 h-10 rounded-full bg-green-500/10 text-green-700 flex items-center justify-center font-bold">
