                  <input
                    type="text"
                    value={joinCode}
                    onChange={(e) => setJoinCode(e.target.value)}
                    placeholder="Enter contest code"
                    className="w-full px-4 py-3 ui-page border border-slate-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
                  />

                  {errorMessage && <p className="text-red-700 text-sm">{errorMessage}</p>}

                  <div className="flex gap-3 justify-end">
                    <button
                      onClick={() => setIsPopupOpen(false)}
                      className="px-4 py-2 text-slate-600 hover:text-slate-900 transition-colors"
                    >
                      Cancel
                    </button>

                    <button
                      onClick={() => {
                        setIsLoading(true);
                        // Add your join contest logic here
                        setTimeout(() => {
                          setIsLoading(false);
                          if (joinCode === "demo") {
                            navigate('/contest/demo');
                          } else {
                            setErrorMessage("Invalid contest code. Please try again.");
                          }
                        }, 1500);
                      }}
                      disabled={isLoading}
                      className="px-5 py-2 bg-blue-600 hover:bg-blue-700 rounded-lg transition-colors flex items-center justify-center"
                    >
                      {isLoading ? (
                        <svg className="animate-spin h-5 w-5" viewBox="0 0 24 24">
                          <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                          <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                        </svg>
                      ) : (
                        "Join Contest"
                      )}
                    </button>
                  </div>
                </div>
              </motion.div>
            </motion.div>
          )}
        </AnimatePresence>

        <Footer />
      </main>
    </div>
  );
};

