                    <li>The leaderboard is updated in real-time</li>
                    <li>
                      In case of a tie, the contestant with earlier submission
                      wins
                    </li>
                  </ul>
                </div>
              </div>
            </div>
          )}

          {activeTab === "problems" && (
            <div className="p-8">
              <h2 className="text-2xl font-bold text-slate-900 mb-6 flex items-center gap-2">
                <Code className="text-blue-700" size={24} />
                Contest Problems
              </h2>

              <div className="space-y-6">
                {contest.problems.map((problem) => (
                  <div
                    key={problem._id}
                    className="ui-page border-2 border-indigo-500/20 rounded-lg overflow-hidden transform transition-all duration-500 hover:scale-[1.02] hover:shadow-[0_0_30px_rgba(79,70,229,0.3)] group"
                  >
                    <div className="p-6">
                      <div className="flex justify-between items-center mb-4">
                        <h3 className="text-xl font-bold text-blue-700 group-hover:text-blue-700 transition-colors duration-300">
                          {problem.title}
                        </h3>
                        <div className="flex items-center gap-2">
                          <span className="font-semibold text-slate-900 bg-indigo-600/30 px-3 py-1 rounded-full text-sm">
                            Score: {problem.score}
                          </span>
                          <span
                            className={`px-3 py-1 rounded-full text-xs font-semibold uppercase ${
                              problem.difficulty === "easy"
                                ? "bg-green-500/80"
                                : problem.difficulty === "medium"
                                ? "bg-yellow-500/80"
                                : "bg-red-500/80"
                            }`}
                          >
                            {problem.difficulty}
                          </span>
                        </div>
                      </div>

                      <div className="flex flex-wrap gap-2 mt-4">
                        {problem.tags.map((tag, index) => (
                          <span
                            key={index}
                            className="ui-surface px-3 py-1 rounded-full text-xs font-medium text-slate-600 border border-slate-200 group-hover:bg-indigo-50 group-hover:border-indigo-500/30 transition-all duration-300"
                          >
                            {tag}
                          </span>
                        ))}
                      </div>

                      <div className="mt-6 flex justify-end">
                        {userRole !== "student" && (
                          <button
                            className="p-2 mr-2 rounded-lg bg-green-600/20 text-green-700 hover:bg-green-600/40 transition-colors"
                            title="Dashboard"
                            onClick={() =>
                              handleDashboardConfirmation(
                                problem._id,
                                problem.title,
                                problem.difficulty,
                                problem.createdAt
                              )
                            }
                          >
                            <BarChart2 className="w-4 h-4" />
                          </button>
                        )}
                        <button
                          onClick={() => handleProblemClick(problem._id)}
                          className="px-4 py-2 bg-indigo-600 text-slate-900 rounded-lg hover:bg-indigo-700 transition-colors duration-300 flex items-center gap-2 group"
                        >
                          <span>Solve Problem</span>
                          <svg
                            xmlns="http://www.w3.org/2000/svg"
                            className="h-4 w-4 transform transition-transform duration-300 group-hover:translate-x-1"
                            fill="none"
                            viewBox="0 0 24 24"
                            stroke="currentColor"
                          >
                            <path
                              strokeLinecap="round"
                              strokeLinejoin="round"
                              strokeWidth={2}
                              d="M9 5l7 7-7 7"
                            />
                          </svg>
                        </button>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>

        {/* Back Button */}
        <div className="mt-8 flex justify-center">
          <button
            onClick={() => navigate(-1)}
            className="group flex items-center space-x-2 px-6 py-3 ui-surface backdrop-blur-sm border border-slate-200 rounded-lg hover:bg-indigo-600/20 hover:border-indigo-500/50 transition-all duration-300"
          >
            <ArrowLeft
              className="transform group-hover:-translate-x-1 transition-transform duration-300"
              size={18}
            />
            <span>Back to Contests</span>
          </button>
        </div>
      </div>
    </div>
  );
};

export default Contest;

import React, { useEffect, useState } from "react";
import axiosInstance from "../../utils/axiosInstance";
import { useParams } from "react-router-dom";
import * as XLSX from 'xlsx';
import jsPDF from 'jspdf';
import 'jspdf-autotable';

const ContestDashboard = () => {
  const [dashboardData, setDashboardData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [filters, setFilters] = useState({
    page: 1,
    limit: 10,
    sortBy: 'totalMarks',
    sortOrder: 'asc',
    branch: 'cspit-it',
    semester: '6',
    batch: 'a1'
  });

  const { id } = useParams();
  const pageSizeOptions = [10, 20, 50, 100, 500, 1000];

  const branchOptions = [
    { value: 'ALL', label: 'All Branches' },
    { value: 'cspit-it', label: 'CSPIT-IT' },
    { value: 'cspit-ce', label: 'CSPIT-CE' },
    { value: 'cspit-cse', label: 'CSPIT-CSE' }
  ];

  const semesterOptions = [
    { value: 'ALL', label: 'All Semesters' },
    ...Array.from({ length: 8 }, (_, i) => ({
      value: String(i + 1),
      label: `Semester ${i + 1}`
    }))
  ];

  const batchOptions = [
    { value: 'ALL', label: 'All Batches' },
    ...['a1', 'a2', 'b1', 'b2', 'c1', 'c2', 'd1', 'd2'].map(batch => ({
      value: batch,
      label: `Batch ${batch}`
    }))
  ];

  const fetchDashboard = async () => {
    try {
      setLoading(true);
      const queryParams = new URLSearchParams(filters);
      const response = await axiosInstance.get(`/contests/${id}/dashboard?${queryParams}`);
      console.log(response.data)
      setDashboardData(response.data);
    } catch (error) {
      console.error("Error fetching dashboard:", error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchDashboard();
  }, [id, filters]);

  const downloadExcel = () => {
    if (!dashboardData?.rankings) return;

    const data = dashboardData.rankings.map(student => ({
      Rank: student.rank,
      'Student ID': student.studentId,
      Name: student.username,
      Branch: student.branch,
      Semester: student.semester,
      Batch: student.batch,
      ...student.problemMarks.reduce((acc, mark, index) => {
        acc[`Problem ${index + 1} Marks`] = mark;
        return acc;
      }, {}),
      'Total Marks': student.totalMarks,
      'Last Submission Date': student.lastSubmissionDate,
      'Last Submission Time': student.lastSubmissionTime
    }));

    const wb = XLSX.utils.book_new();
    const ws = XLSX.utils.json_to_sheet(data);
    XLSX.utils.book_append_sheet(wb, ws, "Rankings");
    XLSX.writeFile(wb, `${dashboardData.contestName}-rankings.xlsx`);
  };

  const downloadPDF = () => {
    if (!dashboardData?.rankings) return;

    const doc = new jsPDF();
    doc.text(dashboardData.contestName, 14, 15);

    const head = [
      ['Rank', 'Student ID', 'Name', 'Branch', 'Semester', 'Batch', ...dashboardData.problemNames.map((_, index) => `Problem ${index + 1} Marks`), 'Total Marks', 'Last Submission Date', 'Last Submission Time']
    ];
    const body = dashboardData.rankings.map(student => [
      student.rank,
      student.studentId,
      student.username,
      student.branch,
      student.semester,
      student.batch,
      ...student.problemMarks,
      student.totalMarks,
      student.lastSubmissionDate,
      student.lastSubmissionTime
    ]);

    doc.autoTable({
      startY: 25,
      head,
      body
    });
    doc.save(`${dashboardData.contestName}-rankings.pdf`);
  };

  const handleSort = (sortBy) => {
    setFilters(prev => ({
      ...prev,
      sortBy,
      sortOrder: prev.sortBy === sortBy ? (prev.sortOrder === 'asc' ? 'desc' : 'asc') : 'desc',
      page: 1
    }));
  };

  return (
    <div className="ui-page-height ui-page text-slate-900 p-6 ui-page-top">
      <div className="max-w-7xl mx-auto">
        {/* Header - Always visible */}
        <div className="assessment-dashboard-heading flex justify-between items-center mb-6">
          <div>
            <h1 className="text-2xl font-bold">
              {dashboardData?.contestName || "Contest Dashboard"}
            </h1>
            <div className="text-slate-600 mt-2">
              Total Submissions: {dashboardData?.pagination?.totalStudents || 0}
              {dashboardData?.sortBy && (
                <span className="ml-2">
                  | Filtered: {dashboardData.pagination.totalStudents} students
                </span>
              )}
            </div>
          </div>
          
          <div className="assessment-dashboard-controls flex gap-4 items-center">
            {/* Controls - Always visible but disabled during loading */}
            <select 
              value={filters.limit}
              onChange={(e) => setFilters(prev => ({ 
                ...prev, 
                limit: Number(e.target.value),
                page: 1 
              }))}
              className="ui-surface rounded px-2 py-1"
              disabled={loading}
            >
              {pageSizeOptions.map(size => (
                <option key={size} value={size}>{size} per page</option>
              ))}
            </select>

            <select 
              value={filters.branch}
              onChange={(e) => setFilters(prev => ({ ...prev, branch: e.target.value, page: 1 }))}
              className="ui-surface rounded px-2 py-1"
              disabled={loading}
            >
              {branchOptions.map(option => (
                <option key={option.value} value={option.value}>{option.label}</option>
              ))}
            </select>

            <select 
              value={filters.semester}
              onChange={(e) => setFilters(prev => ({ ...prev, semester: e.target.value, page: 1 }))}
              className="ui-surface rounded px-2 py-1"
              disabled={loading}
            >
              {semesterOptions.map(option => (
                <option key={option.value} value={option.value}>{option.label}</option>
              ))}
            </select>

            <select 
              value={filters.batch}
              onChange={(e) => setFilters(prev => ({ ...prev, batch: e.target.value, page: 1 }))}
              className="ui-surface rounded px-2 py-1"
              disabled={loading}
            >
              {batchOptions.map(option => (
                <option key={option.value} value={option.value}>{option.label}</option>
              ))}
            </select>

            <button 
              onClick={downloadExcel} 
              className="bg-green-600 px-3 py-1 rounded"
              disabled={loading || !dashboardData?.rankings?.length}
            >
              Excel
            </button>
            <button 
              onClick={downloadPDF} 
              className="bg-red-600 px-3 py-1 rounded"
              disabled={loading || !dashboardData?.rankings?.length}
            >
              PDF
            </button>
          </div>
        </div>

        {/* Table - Always visible with conditional content */}
        <div className="overflow-x-auto ui-surface rounded-lg">
          <table className="w-full">
            <thead>
              <tr className="ui-surface">
                <th className="p-3 text-left">Rank</th>
                <th className="p-3 text-left cursor-pointer" onClick={() => handleSort('studentId')}>ID</th>
                <th className="p-3 text-left">Name</th>
                <th className="p-3 text-left">Branch</th>
                <th className="p-3 text-left">Semester</th>
                <th className="p-3 text-left">Batch</th>
                {dashboardData?.problemNames?.map((problem, index) => (
                  <th key={index} className="p-3 text-right">
                    {problem.name}<br/>
                    <span className="text-sm text-slate-600">({problem.maxMarks})</span>
                  </th>
                ))}
                <th className="p-3 text-right cursor-pointer" onClick={() => handleSort('totalMarks')}>Total Marks</th>
                <th className="p-3 text-right">Last Submission</th>
              </tr>
            </thead>
            <tbody>
              {loading ? (
                <tr>
                  <td colSpan="7" className="p-8 text-center">
                    <div className="flex items-center justify-center space-x-2">
                      <div className="animate-spin rounded-full h-6 w-6 border-b-2 border-white"></div>
                      <span>Loading submissions...</span>
                    </div>
                  </td>
                </tr>
              ) : dashboardData?.rankings?.length ? (
                dashboardData.rankings.map((student) => (
                  <tr key={student.studentId} className="border-t border-slate-200 hover:ui-surface">
                    <td className="p-3">{student.rank}</td>
                    <td className="p-3">{student.studentId}</td>
                    <td className="p-3">{student.username}</td>
                    <td className="p-3">{student.branch}</td>
                    <td className="p-3">{student.semester}</td>
                    <td className="p-3">{student.batch}</td>
                    {student.problemMarks.map((marks, index) => (
                      <td key={index} className="p-3 text-right">
                        {marks || '-'}
                      </td>
                    ))}
                    <td className="p-3 text-right">{student.totalMarks}</td>
                    <td className="p-3 text-right">
                      <div>{student.lastSubmissionDate}</div>
                      <div className="text-sm text-slate-600">{student.lastSubmissionTime}</div>
                    </td>
                  </tr>
                ))
              ) : (
                <tr>
                  <td colSpan="7" className="p-8 text-center">
                    No submissions found
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>

        {/* Pagination - Show only when we have data */}
        {dashboardData?.rankings?.length > 0 && (
          <div className="mt-4 flex justify-between items-center">
            <span className="text-sm">
              Showing {((filters.page - 1) * filters.limit) + 1} to{' '}
              {Math.min(filters.page * filters.limit, dashboardData.pagination.totalStudents)} of{' '}
              {dashboardData.pagination.totalStudents} submissions
              {filters.sortBy !== 'totalMarks' && (
                <span className="ml-2 text-slate-600">
                  (Filtered from {dashboardData.pagination.totalStudents} total)
                </span>
              )}
            </span>
            <div className="flex gap-1">
              {Array.from({ length: dashboardData.pagination.totalPages }, (_, i) => (
                <button
                  key={i + 1}
                  onClick={() => setFilters(prev => ({ ...prev, page: i + 1 }))}
                  className={`px-3 py-1 rounded ${
                    filters.page === i + 1 ? 'bg-blue-600' : 'ui-surface'
                  }`}
                  disabled={loading}
                >
                  {i + 1}
                </button>
              ))}
            </div>
          </div>
        )}

        {/* Statistics Panel */}
        <div className="mt-6 grid grid-cols-1 md:grid-cols-3 gap-4">
          <div className="ui-surface p-4 rounded-lg">
            <h3 className="font-semibold mb-2">Total Submissions</h3>
            <p className="text-2xl">{dashboardData?.pagination?.totalStudents || 0}</p>
          </div>
          <div className="ui-surface p-4 rounded-lg">
            <h3 className="font-semibold mb-2">Filtered Count</h3>
            <p className="text-2xl">{dashboardData?.pagination?.totalStudents || 0}</p>
          </div>
        </div>
      </div>
    </div>
  );
};

export default ContestDashboard;

import React, { useState, useEffect } from "react";
import axiosInstance from "../../utils/axiosInstance";
import ConfirmationModal from "../ConfirmationModal";
import toast from "react-hot-toast";
import { useNavigate, useParams } from "react-router-dom";
import { useSelector } from "react-redux";

const CreateContest = () => {
  const navigate = useNavigate();
  const { id } = useParams();
  const user = useSelector((store) => store.app.user);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isEditMode, setIsEditMode] = useState(false);
  const [assignLoading, setAssignLoading] = useState(false); // For button-specific loading
  const [contest, setContest] = useState({
    name: "",
    description: "",
    problems: [],
    created_by: user._id,
    start_time: "",
    end_time: "",
  });

  const [problems, setProblems] = useState([]);
  const [searchTerm, setSearchTerm] = useState("");
  const [isInvalid, setIsInvalid] = useState({
    name: false,
    description: false,
    problems: false,
    start_time: false,
    end_time: false,
  });

  useEffect(() => {
    const fetchProblems = async () => {
      try {
        const response = await axiosInstance.get("/problems");
        let { problems: allProblems } = response.data;
        allProblems = allProblems.sort(
          (a, b) => new Date(b.createdAt) - new Date(a.createdAt)
        );
        setProblems(allProblems);
      } catch (error) {
        toast.error("Error fetching problems.");
        console.error("Error fetching problems:", error);
      }
    };
    fetchProblems();
  }, []);

  const formatDateTimeLocal = (isoString) => {
    const date = new Date(isoString);
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, "0");
    const day = String(date.getDate()).padStart(2, "0");
    const hours = String(date.getHours()).padStart(2, "0");
    const minutes = String(date.getMinutes()).padStart(2, "0");
    return `${year}-${month}-${day}T${hours}:${minutes}`;
  };

  useEffect(() => {
    if (id) {
      setIsEditMode(true);
      const fetchContest = async () => {
        try {
          setAssignLoading(true); // Start loading
          const response = await axiosInstance.get(`/contests/${id}`);
          const contestData = response.data;
          setContest({
            name: contestData.name,
            description: contestData.description,
            problems: contestData.problems.map((problem) => problem._id),
            created_by: contestData.created_by,
            start_time: formatDateTimeLocal(contestData.start_time),
            end_time: formatDateTimeLocal(contestData.end_time),
          });
        } catch (error) {
          console.error("Error fetching contest data:", error);
        } finally {
          setAssignLoading(false); // Stop loading
        }
      };
      fetchContest();
    }
  }, [id]);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setContest((prevContest) => ({
      ...prevContest,
      [name]: value,
    }));
    setIsInvalid((prevInvalid) => ({ ...prevInvalid, [name]: false }));
  };

  const handleProblemSelect = (problemId) => {
    setContest((prevContest) => {
      const isSelected = prevContest.problems.includes(problemId);
      if (isSelected) {
        return {
          ...prevContest,
          problems: prevContest.problems.filter((id) => id !== problemId),
        };
      } else {
        return {
          ...prevContest,
          problems: [...prevContest.problems, problemId],
        };
      }
    });
    setIsInvalid((prevInvalid) => ({ ...prevInvalid, problems: false }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    const invalidFields = {
      name: contest.name.trim() === "",
      description: contest.description.trim() === "",
      problems: contest.problems.length === 0,
      start_time: contest.start_time.trim() === "",
      end_time: contest.end_time.trim() === "",
    };
    setIsInvalid(invalidFields);
    if (Object.values(invalidFields).some((field) => field)) {
      toast.error("Please fill in all required fields.");
      return;
    }
    try {
      if (isEditMode) {
        await axiosInstance.put(`/contests/${id}`, contest);
        toast.success("Contest updated successfully!");
      } else {
        await axiosInstance.post("/contests/create", contest);
        toast.success("Contest created successfully!");
      }
      navigate("/make-contest");
    } catch (error) {
      toast.error("Error creating/updating contest.");
      console.error("Error creating/updating contest:", error);
    }
  };

  const handleBackClick = () => {
    setIsModalOpen(true);
  };

  const handleConfirmBack = () => {
    setIsModalOpen(false);
    navigate(-1);
  };

  const handleCloseModal = () => {
    setIsModalOpen(false);
  };

  const filteredProblems = Array.isArray(problems)
    ? problems.filter((problem) =>
        problem.title.toLowerCase().includes(searchTerm.toLowerCase())
      )
    : [];
  const displayedProblems = searchTerm ? filteredProblems : problems;

  return (
    <div className="ui-page-height ui-gradient   text-slate-900 px-4 py-8 ui-page-top">
      <div className="max-w-6xl mx-auto">
        <div className="text-center mb-12">
          <h1 className="text-4xl font-bold  text-slate-900 ui-gradient  ">
            {isEditMode ? "Edit Contest" : "Create Contest"}
          </h1>
          <p className="mt-3 text-slate-600">
            Design your perfect coding challenge
          </p>
        </div>
        {assignLoading && (
          <div className="fixed inset-0 bg-black bg-opacity-70 flex items-center justify-center z-50">
            <div className="flex flex-col items-center">
              <svg
                className="animate-spin h-12 w-12 text-blue-700 mb-4"
                xmlns="http://www.w3.org/2000/svg"
                fill="none"
                viewBox="0 0 24 24"
              >
                <circle
                  className="opacity-25"
                  cx="12"
                  cy="12"
                  r="10"
                  stroke="currentColor"
                  strokeWidth="4"
                ></circle>z
                <path
                  className="opacity-75"
                  fill="currentColor"
                  d="M4 12a8 8 0 018-8v8H4z"
                ></path>
              </svg>
              <p className="text-slate-900 text-lg font-semibold">Loading...</p>
            </div>
          </div>
        )}
        <button
          onClick={handleBackClick}
          className="group flex items-center space-x-2 px-4 py-2 mb-8 ui-surface rounded-lg hover:ui-surface transition-all duration-300"
        >
          <span className="transform group-hover:-translate-x-1 transition-transform duration-300">
            ←
          </span>
          <span>Back</span>
        </button>
        <ConfirmationModal
          isOpen={isModalOpen}
          onClose={handleCloseModal}
          onConfirm={handleConfirmBack}
        />
        <div className="ui-page rounded-lg p-8 ui-card-shadow border border-slate-200">
          <form className="space-y-8" onSubmit={handleSubmit}>
            <div>
              <label
                className="block text-lg font-medium mb-3 text-slate-900"
                htmlFor="name"
              >
                Contest Name <span className="text-red-700">*</span>
              </label>
              <input
                type="text"
                id="name"
                className={`w-full p-4 ui-page border rounded-lg transition-all duration-300 focus:ring-2 focus:ring-blue-500 focus:border-transparent ${
                  isInvalid.name ? "border-red-400" : "border-slate-200"
                }`}
                onChange={handleChange}
                name="name"
                value={contest.name}
                placeholder="Enter an engaging title for your contest"
              />
            </div>
            <div>
              <label
                className="block text-g font-medium mb-3 text-slate-900"
                htmlFor="description"
              >
                Description <span className="text-red-700">*</span>
              </label>
              <textarea
                id="description"
                rows={5}
                name="description"
                value={contest.description}
                onChange={handleChange}
                className={`w-full p-4 ui-page border rounded-lg transition-all duration-300 focus:ring-2 focus:ring-blue-500 focus:border-transparent ${
                  isInvalid.description ? "border-red-400" : "border-slate-200"
                }`}
                placeholder="Describe your contest objectives and guidelines"
              />
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div>
                <label
                  className="block text-lg font-medium mb-3 text-slate-900"
                  htmlFor="start_time"
                >
                  Start Time <span className="text-red-700">*</span>
                </label>
                <input
                  type="datetime-local"
                  id="start_time"
                  name="start_time"
                  value={contest.start_time}
                  onChange={handleChange}
                  className={`w-full p-4 ui-page border rounded-lg transition-all duration-300 focus:ring-2 focus:ring-blue-500 focus:border-transparent ${
                    isInvalid.start_time ? "border-red-400" : "border-slate-200"
                  }`}
                />
              </div>
              <div>
                <label
                  className="block text-lg font-medium mb-3 text-slate-900"
                  htmlFor="end_time"
                >
                  End Time <span className="text-red-700">*</span>
                </label>
                <input
                  type="datetime-local"
                  id="end_time"
                  name="end_time"
                  value={contest.end_time}
                  onChange={handleChange}
                  className={`w-full p-4 ui-page border rounded-lg transition-all duration-300 focus:ring-2 focus:ring-blue-500 focus:border-transparent ${
                    isInvalid.end_time ? "border-red-400" : "border-slate-200"
                  }`}
                />
              </div>
            </div>
            <div>
              <label className="block text-lg font-medium mb-3 text-slate-900">
                Select Problems <span className="text-red-700">*</span>
              </label>
              <div className="relative">
                <input
                  type="text"
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                  placeholder="Search problems..."
                  className="w-full p-4 ui-page border border-slate-200 rounded-lg mb-4 pl-10 focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                />
                <svg
                  className="absolute left-3 top-4 h-5 w-5 text-slate-600"
                  fill="none"
                  stroke="currentColor"
                  viewBox="0 0 24 24"
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={2}
                    d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"
                  />
                </svg>
              </div>
              <div className="max-h-64 overflow-y-auto rounded-lg border border-slate-200 ui-page">
                {displayedProblems.map((problem) => (
                  <div
                    key={problem._id}
                    className="p-4 border-b border-slate-200 last:border-b-0 hover:ui-surface transition-colors duration-200"
                  >
                    <label className="flex items-center space-x-4 cursor-pointer">
                      <input
                        type="checkbox"
                        checked={contest.problems.includes(problem._id)}
                        onChange={() => handleProblemSelect(problem._id)}
                        className="w-5 h-5 rounded border-slate-200 text-blue-700 focus:ring-blue-500 focus:ring-offset-gray-900"
                      />
                      <span className="text-lg">{problem.title}</span>
                    </label>
                  </div>
                ))}
              </div>
            </div>
            <button
              type="submit"
              className="w-full py-4 ui-gradient   text-slate-900 text-lg font-semibold rounded-lg ui-card-shadow   transform hover:scale-[1.02] transition-all duration-300"
            >
              {isEditMode ? "Update Contest" : "Create Contest"}
            </button>
          </form>
        </div>
      </div>
    </div>
  );
};

export default CreateContest;

import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import axiosInstance from "../../utils/axiosInstance";
import toast from "react-hot-toast";
import "../../CSS/Quiz.css";
import { useSelector } from "react-redux";
import {
  Search,
  Filter,
  Plus,
  Edit,
  Trash2,
  BarChart2,
  UserPlus,
  ChevronUp,
  ChevronDown,
} from "lucide-react";

const MakeContest = () => {
  const user = useSelector((store) => store.app.user);
  const navigate = useNavigate();
  const [contests, setContests] = useState([]);
  const [loading, setLoading] = useState(false);
  const [searchQuery, setSearchQuery] = useState("");
  const [showDeleteModal, setShowDeleteModal] = useState(false);
  const [contestToDelete, setContestToDelete] = useState(null);
  const [userRole, setUserRole] = useState(null); // State to store the user role
  const [statusFilter, setStatusFilter] = useState(""); // State for status filter

  const [sortConfig, setSortConfig] = useState({
    key: "createdAt",
    direction: "desc",
  });

  const getSortIcon = (columnName) => {
    if (sortConfig.key !== columnName) {
      return null;
    }
    return sortConfig.direction === "asc" ? (
      <ChevronUp className="inline w-4 h-4" />
    ) : (
      <ChevronDown className="inline w-4 h-4" />
    );
  };

  const handleAddContest = () => {
    navigate("/create-contest");
  };

  const handleEditContest = (contestId) => {
    navigate(`/create-contest/${contestId}`);
  };

  const handleDeleteContest = async () => {
    try {
      await axiosInstance.delete(`/contests/${contestToDelete}`);
      toast.success("Contest deleted successfully!");
      setShowDeleteModal(false);
      setContestToDelete(null);
      fetchContests();
    } catch (error) {
      toast.error("Error deleting contest!");
      console.error("Error deleting contest:", error);
    }
  };

  const handleDeleteConfirmation = (contestId) => {
    setContestToDelete(contestId);
    setShowDeleteModal(true);
  };

  const cancelDelete = () => {
    setShowDeleteModal(false);
    setContestToDelete(null);
  };

  const fetchContests = async () => {
    try {
      setLoading(true);
      const response = await axiosInstance.get("/contests");
      console.log("Fetched contests response:", response.data); // Debug statement
      // Assuming the contests are directly in response.data
      setContests(Array.isArray(response.data) ? response.data : []);
    } catch (error) {
      toast.error("Error fetching contests!");
      console.error("Error fetching contests:", error);
    } finally {
      setLoading(false);
    }
  };

  const fetchUserRole = () => {
    const role = user.role;
    setUserRole(role);
  };

  useEffect(() => {
    fetchContests();
    fetchUserRole(); // Fetch the user role when component mounts
  }, []);

  const sortedContests = React.useMemo(() => {
    let sortableContests = Array.isArray(contests) ? [...contests] : [];
    if (sortConfig !== null) {
      sortableContests.sort((a, b) => {
        if (a[sortConfig.key] < b[sortConfig.key]) {
          return sortConfig.direction === "asc" ? -1 : 1;
        }
        if (a[sortConfig.key] > b[sortConfig.key]) {
          return sortConfig.direction === "asc" ? 1 : -1;
        }
        return 0;
      });
    }
    return sortableContests;
  }, [contests, sortConfig]);

  const handleSort = (key) => {
    let direction = "asc";
    if (sortConfig.key === key && sortConfig.direction === "asc") {
      direction = "desc";
    }
    setSortConfig({ key, direction });
  };

  const filteredContests = sortedContests
    .filter((contest) =>
      contest.name.toLowerCase().includes(searchQuery.toLowerCase())
    )
    .filter((contest) => {
      if (statusFilter === "") return true;
      return contest?.status === statusFilter;
    });

  const formatDate = (dateString) => {
    const date = new Date(dateString);
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, "0");
    const day = String(date.getDate()).padStart(2, "0");
    const hours = String(date.getHours()).padStart(2, "0");
    const minutes = String(date.getMinutes()).padStart(2, "0");
    return `${day}-${month}-${year} ${hours}:${minutes}`;
  };

  const assignContestToStudents = (contestId) => {
    navigate(`/assignContestToStudents/${contestId}`);
  };

  const truncateTitle = (title, maxLength) => {
    return title && title.length > maxLength
      ? `${title.slice(0, maxLength)}...`
      : title || "Untitled";
  };

  return (
    <div className="ui-page-height ui-gradient   text-slate-900">
      {/* Header with gradient */}
      <div className="py-6 px-8 ui-page-top flex items-center justify-center">
        <h1 className="text-3xl font-bold text-slate-900">Contest Bank</h1>
      </div>

      <div className="max-w-7xl mx-auto p-6">
        {/* Action Bar */}
        <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-4 mb-8">
          {/* Add Contest Button (for non-students) */}
          {userRole !== "student" && (
            <button
              onClick={handleAddContest}
              className="flex items-center gap-2 ui-gradient   text-slate-900 font-semibold py-3 px-6 rounded-lg   transition-all shadow-md"
            >
              <Plus className="w-5 h-5" />
              <span>Add Contest</span>
            </button>
          )}

          {/* Filters and Search */}
          <div className="flex flex-col md:flex-row gap-4 w-full md:w-auto">
            <div className="relative">
              <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                <Filter className="h-5 w-5 text-slate-600" />
              </div>
              <select
                value={statusFilter}
                onChange={(e) => setStatusFilter(e.target.value)}
                className="ui-surface text-slate-900 py-3 pl-10 pr-4 rounded-lg border border-slate-200 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent w-full md:w-48"
              >
                <option value="">All Statuses</option>
                <option value="upcoming">Upcoming</option>
                <option value="ongoing">Ongoing</option>
                <option value="completed">Completed</option>
              </select>
            </div>

            <div className="relative flex-grow">
              <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                <Search className="h-5 w-5 text-slate-600" />
              </div>
              <input
                type="text"
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                placeholder="Search contests..."
                className="ui-surface text-slate-900 py-3 pl-10 pr-4 rounded-lg border border-slate-200 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent w-full"
              />
            </div>
          </div>
        </div>

        {/* Contests Table */}
        <div className="ui-page rounded-lg ui-card-shadow overflow-hidden">
          <div className="overflow-x-auto">
            <table className="w-full border-collapse">
              <thead>
                <tr className="ui-surface text-slate-900 text-sm uppercase">
                  <th className="py-4 px-6 text-left">
                    <button
                      onClick={() => handleSort("_id")}
                      className="flex items-center font-semibold"
                    >
                      # {getSortIcon("_id")}
                    </button>
                  </th>
                  <th className="py-4 px-6 text-left">
                    <button
                      onClick={() => handleSort("name")}
                      className="flex items-center font-semibold"
                    >
                      Name {getSortIcon("name")}
                    </button>
                  </th>
                  <th className="py-4 px-6 text-center">
                    <button
                      onClick={() => handleSort("start_time")}
                      className="flex items-center justify-center font-semibold"
                    >
                      Start Date {getSortIcon("start_time")}
                    </button>
                  </th>
                  <th className="py-4 px-6 text-center">
                    <button
                      onClick={() => handleSort("status")}
                      className="flex items-center justify-center font-semibold"
                    >
                      Status {getSortIcon("status")}
                    </button>
                  </th>
                  {userRole !== "student" && (
                    <th className="py-4 px-6 text-center">Actions</th>
                  )}
                </tr>
              </thead>
              <tbody>
                {filteredContests.length > 0 ? (
                  filteredContests.map((contest, index) => (
                    <tr
                      key={contest._id}
                      className="border-t border-slate-200 hover:ui-surface transition-colors"
                    >
                      <td className="py-4 px-6 text-slate-600 font-medium">
                        {index + 1}
                      </td>
                      <td className="py-4 px-6">
                        <div
                          className="capitalize font-semibold text-blue-700 hover:text-blue-700 cursor-pointer transition-colors"
                          onClick={() => navigate(`/contests/${contest._id}`)}
                        >
                          {/* {contest.name} */}
                          {truncateTitle(
                            contest?.name,
                            window.innerWidth < 900 ? 25 : 50
                          )}
                        </div>
                      </td>
                      <td className="py-4 px-6 text-center text-slate-600 text-sm">
                        {formatDate(contest.start_time)}
                      </td>
                      <td
                        className={`py-4 px-6 text-center ${
                          contest.status === "upcoming"
                            ? "text-yellow-500"
                            : contest.status === "ongoing"
                            ? "text-green-500"
                            : "text-red-500"
                        }`}
                      >
                        {contest.status}
                      </td>
                      {userRole !== "student" && (
                        <td className="py-4 px-6">
                          <div className="flex items-center justify-center gap-2">
                            <button
                              onClick={() => handleEditContest(contest._id)}
                              className="p-2 rounded-lg bg-blue-600/20 text-blue-700 hover:bg-blue-600/40 transition-colors"
                              title="Edit"
                            >
                              <Edit className="w-4 h-4" />
                            </button>
                            <button
                              onClick={() =>
                                handleDeleteConfirmation(contest._id)
                              }
                              className="p-2 rounded-lg bg-red-600/20 text-red-700 hover:bg-red-600/40 transition-colors"
                              title="Delete"
                            >
                              <Trash2 className="w-4 h-4" />
                            </button>
                            <button
                              onClick={() =>
                                navigate(`/contests/${contest._id}/dashboard`)
                              }
                              className="p-2 rounded-lg bg-green-600/20 text-green-700 hover:bg-green-600/40 transition-colors"
                              title="Dashboard"
                            >
                              <BarChart2 className="w-4 h-4" />
                            </button>
                            <button
                              onClick={() =>
                                assignContestToStudents(contest._id)
                              }
                              className="p-2 rounded-lg bg-purple-600/20 text-blue-700 hover:bg-purple-600/40 transition-colors"
                              title="Assign"
                            >
                              <UserPlus className="w-4 h-4" />
                            </button>
                          </div>
                        </td>
                      )}
                    </tr>
                  ))
                ) : (
                  <tr>
                    <td
                      colSpan={userRole !== "student" ? 5 : 4}
                      className="py-8 px-6 text-center text-slate-600"
                    >
                      <div className="flex flex-col items-center justify-center">
                        <Search className="w-12 h-12 text-slate-700 mb-3" />
                        <p className="text-lg font-medium">No contests found</p>
                        <p className="text-sm text-slate-600">
                          Try adjusting your search or filter
                        </p>
                      </div>
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        </div>
      </div>

      {/* Delete Confirmation Modal */}
      {showDeleteModal && (
        <div className="fixed inset-0 flex items-center justify-center z-50 bg-black bg-opacity-70">
          <div className="ui-surface p-8 rounded-lg w-11/12 max-w-md mx-auto border border-slate-200 ui-card-shadow transform transition-all">
            <div className="flex flex-col items-center">
              <div className="bg-red-500/20 p-3 rounded-full mb-4">
                <Trash2 className="w-8 h-8 text-red-500" />
              </div>
              <h3 className="text-xl font-bold mb-2 text-slate-900">
                Confirm Deletion
              </h3>
              <p className="text-slate-600 mb-6 text-center">
                Are you sure you want to delete this contest? This action cannot
                be undone.
              </p>
              <div className="flex gap-4 w-full">
                <button
                  onClick={cancelDelete}
                  className="flex-1 py-3 px-4 ui-surface hover:ui-subtle text-slate-900 rounded-lg transition-colors"
                >
                  Cancel
                </button>
                <button
                  onClick={handleDeleteContest}
                  className="flex-1 py-3 px-4 bg-red-600 hover:bg-red-50 text-slate-900 rounded-lg transition-colors"
                >
                  Delete
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default MakeContest;

import React, { useState, useEffect } from "react";
import { useNavigate, useParams } from "react-router-dom";
import axiosInstance from "../../utils/axiosInstance";
import toast from "react-hot-toast";
import StudentTable from "../Problem/StudentTable.jsx";

const UnAssignContest = () => {
  const { contestId } = useParams();
  const navigate = useNavigate();
  const [loading, setLoading] = useState(true);
  const [assignLoading, setAssignLoading] = useState(false);
  const [unassignedStudents, setUnassignedStudents] = useState([]);
  const [selectedStudents, setSelectedStudents] = useState([]);
  const [filters, setFilters] = useState({
    branch: "cspit-it",
    semester: "6",
    batch: "a1",
  });
  const [error, setError] = useState("");
  const [currentPage, setCurrentPage] = useState(1);
  const studentsPerPage = 12;

  useEffect(() => {
    const fetchUnassignedStudents = async () => {
      setLoading(true);
      try {
        const response = await axiosInstance.get(
          `/contests/${contestId}/unassignedStudents`,
          {
            params: {
              branch: filters.branch,
              semester: filters.semester,
              batch: filters.batch,
            },
          }
        );
        setUnassignedStudents(response.data.unassignedStudents || []);
      } catch (err) {
        toast.error("Failed to fetch unassigned students. Please try again.");
        setError("Failed to fetch unassigned students");
      } finally {
        setLoading(false);
      }
    };

    fetchUnassignedStudents();
  }, [contestId, filters]);

  const updateFilter = (key, value) => {
    setFilters((prev) => ({ ...prev, [key]: value }));
    setCurrentPage(1);
  };

  const handleSelectAll = () => {
    if (selectedStudents.length === unassignedStudents.length) {
      setSelectedStudents([]);
    } else {
      setSelectedStudents(unassignedStudents.map((student) => student._id));
    }
  };

  const handleSelectStudent = (id) => {
    if (selectedStudents.includes(id)) {
      setSelectedStudents(
        selectedStudents.filter((studentId) => studentId !== id)
      );
    } else {
      setSelectedStudents([...selectedStudents, id]);
    }
  };

  const handleAssign = async () => {
    setAssignLoading(true);
    try {
      const res = await axiosInstance.post(
        `/contests/${contestId}/assignContestToStudents`,
        {
          studentIds: selectedStudents,
        }
      );
      setUnassignedStudents(
        unassignedStudents.filter(
          (student) => !selectedStudents.includes(student._id)
        )
      );
      toast.success(res.data.message);
      setSelectedStudents([]);
      setError(null);
    } catch (error) {
      toast.error("Failed to assign students. Please try again.");
      setError("Failed to assign students. Please try again.");
    } finally {
      setAssignLoading(false);
    }
  };

  const totalPages = Math.ceil(unassignedStudents.length / studentsPerPage);

  const handlePageChange = (pageNumber) => {
    setCurrentPage(pageNumber);
  };

  return (
    <div className="relative ui-page-height ui-page text-slate-900">
      <h1 className="text-2xl font-bold mb-4 ui-page-top justify-center flex items-center">
        Contest Unassigned Students List
      </h1>

      {error && <p className="text-red-500 mb-4">{error}</p>}

      {assignLoading && (
        <div className="fixed inset-0 bg-black bg-opacity-70 flex items-center justify-center z-50">
          <div className="flex flex-col items-center">
            <svg
              className="animate-spin h-12 w-12 text-blue-700 mb-4"
              xmlns="http://www.w3.org/2000/svg"
              fill="none"
              viewBox="0 0 24 24"
            >
              <circle
                className="opacity-25"
                cx="12"
                cy="12"
                r="10"
                stroke="currentColor"
                strokeWidth="4"
              ></circle>
              <path
                className="opacity-75"
                fill="currentColor"
                d="M4 12a8 8 0 018-8v8H4z"
              ></path>
            </svg>
            <p className="text-slate-900 text-lg font-semibold">Assigning...</p>
          </div>
        </div>
      )}
      <div className="p-4">
        <button
          onClick={() => navigate(`/unassignContestToStudents/${contestId}`)}
          className="bg-red-500 text-slate-900 font-semibold py-2 px-4 rounded-lg hover:bg-red-600 transition mb-4"
        >
          View Assigned Students
        </button>
      </div>

      <div className="px-4 mb-4">
        <p className="text-xl font-medium">
          Unassigned Students: {unassignedStudents.length}
        </p>
      </div>

      <StudentTable
        users={unassignedStudents}
        selectedStudents={selectedStudents}
        handleSelectStudent={handleSelectStudent}
        handleSelectAll={handleSelectAll}
        filters={filters}
        updateFilter={updateFilter}
        loading={loading}
        currentPage={currentPage}
        itemsPerPage={studentsPerPage}
        handlePageChange={handlePageChange}
        totalPages={totalPages}
      />

      <div className="flex justify-start p-4">
        <button
          onClick={handleAssign}
          disabled={selectedStudents.length === 0}
          className="bg-green-500 text-slate-900  px-4 py-2 rounded hover:bg-green-600 disabled:ui-subtle"
        >
          Assign Problem
        </button>
      </div>
    </div>
  );
};

export default UnAssignContest;

import React, { useEffect, useState } from "react";
import { useSelector } from "react-redux";
import { useNavigate } from "react-router-dom";
import axiosInstance from "../../utils/axiosInstance";
import toast from "react-hot-toast";
import { BeatLoader } from "react-spinners";

const Faculty = () => {
  const user = useSelector((store) => store.app.user);
  const navigate = useNavigate();

  const [pendingUsers, setPendingUsers] = useState([]);
  const [currentPage, setCurrentPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [loading, setLoading] = useState(false);
  const [actionLoading, setActionLoading] = useState(false);

  const PAGE_SIZE = 10;

  // Only faculty allowed
  useEffect(() => {
    if (user?.role !== "faculty") navigate("/");
  }, [user, navigate]);

  // Fetch users with pagination
  const fetchUsers = async (page = 1) => {
    let facultyId = user._id;
    // console.log("This is faculty id: ", facultyId);

    if (!facultyId) {
      toast.error("Faculty ID is required.");
      return;
    }

    setLoading(true);
    try {
      const response = await axiosInstance.get(
        `/faculty/get-pending-users?page=${page}&facultyId=${facultyId}`
      );
      // console.log(response.data);

      if (response?.data?.success) {
        setPendingUsers(Array.isArray(response.data.data) ? response.data.data : []);
        setTotalPages(response.data.totalPages || 0);
      } else {
        setPendingUsers([]);
        setTotalPages(0);
      }
    } catch (error) {
      console.error("Error fetching data:", error);
      toast.error("An error occurred while fetching data.");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchUsers(currentPage);
  }, [currentPage]);

  // Accept a single user
  const handleAcceptUser = async (userId) => {
    let facultyId = user._id;

    if (!facultyId) {
      toast.error("Faculty ID is required.");
      return;
    }

    setActionLoading(userId);
    try {
      const response = await axiosInstance.post(`/faculty/accept-request`, {
        userId,
        facultyId,
      });

      if (response.data.success) {
        toast.success("User accepted successfully.");
        setPendingUsers((prev) => prev.filter((user) => user._id !== userId));
      } else {
        toast.error(response.data.message || "Failed to accept user.");
      }
    } catch (error) {
      console.error("Error accepting user:", error);
      toast.error("An error occurred while accepting the user.");
    } finally {
      setActionLoading(false);
    }
  };

  // Decline a single user
  const handleDeclineUser = async (userId) => {
    let facultyId = user._id;

    if (!facultyId) {
      toast.error("Faculty ID is required.");
      return;
    }

    setActionLoading(userId);
    try {
      const response = await axiosInstance.post(`/faculty/decline-request`, {
        userId,
        facultyId,
      });

      if (response.data.success) {
        toast.success(response.data.message || "User declined successfully.");
        setPendingUsers((prev) => prev.filter((user) => user._id !== userId));
      } else {
        toast.error(response.data.message || "Failed to decline user.");
      }
    } catch (error) {
      console.error("Error declining user request:", error);
      toast.error("An error occurred while declining the user.");
    } finally {
      setActionLoading(false);
    }
  };

  // Accept all pending users
  const handleAcceptAll = async () => {
    let facultyId = user._id;

    if (!facultyId) {
      toast.error("Faculty ID is required.");
      return;
    }

    setActionLoading(true);
    try {
      const response = await axiosInstance.post(
        `/faculty/accept-all-requests`,
        {
          facultyId,
        }
      );

      if (response.data.success) {
        toast.success(
          response.data.message || "All pending users have been approved."
        );
        setPendingUsers([]);
        fetchUsers(currentPage);
      } else {
        toast.error(response.data.message || "Failed to accept all users.");
      }
    } catch (error) {
      console.error("Error accepting all users:", error);
      toast.error("An error occurred while accepting all users.");
    } finally {
      setActionLoading(false);
    }
  };

  // Decline all pending users
  const handleDeclineAll = async () => {
    setActionLoading(true);
    try {
      const response = await axiosInstance.post(
        `/faculty/decline-all-requests`,
        {
          facultyId: user._id,
        }
      );

      if (response.data.success) {
        toast.success(response.data.message);
        setPendingUsers([]);
        fetchUsers(currentPage);
      } else {
        toast.error(response.data.message || "Failed to decline all users.");
      }
    } catch (error) {
      toast.error("An error occurred while declining all users.");
    } finally {
      setActionLoading(false);
    }
  };

  return (
    <>
      <div className="ui-page text-slate-900 ui-page-height overflow-hidden">
        <div className="flex justify-between items-center mb-4 p-6 ui-page-top">
          <h1 className="text-2xl font-bold">
            Pending User Requests For Subject {user?.subject}
          </h1>
          <div className="flex gap-2">
            <button
              onClick={handleAcceptAll}
              disabled={pendingUsers.length === 0}
              className="bg-green-600 text-slate-900 py-2 px-4 rounded-lg hover:bg-green-700 transition disabled:opacity-50"
            >
              {actionLoading ? (
                <BeatLoader size={10} color="#fff" />
              ) : (
                "Accept All"
              )}
            </button>
            <button
              onClick={handleDeclineAll}
              disabled={pendingUsers.length === 0}
              className="bg-red-600 text-slate-900 py-2 px-4 rounded-lg hover:bg-red-50 transition disabled:opacity-50"
            >
              {actionLoading ? (
                <BeatLoader size={10} color="#fff" />
              ) : (
                "Decline All"
              )}
            </button>
          </div>
        </div>

        <div className="p-4">
          <button className="bg-blue-500 hover:bg-blue-600 text-slate-900 mr-2 font-bold py-2 px-4 rounded-lg shadow-md focus:outline-none focus:ring-2 focus:ring-blue-300 transition"
          onClick={() => navigate("/add-student-using-file")}>
            Add Student Using File
          </button>
          <button className="bg-blue-500 hover:bg-blue-600 text-slate-900 font-bold py-2 px-4 rounded-lg shadow-md focus:outline-none focus:ring-2 focus:ring-blue-300 transition"
          onClick={() => navigate("/registerStudent")}>
            Register Student 
          </button>
        </div>

        {loading ? (
          <div className="flex justify-center items-center h-64">
            <BeatLoader size={15} color="#4A90E2" />
          </div>
        ) : (
          <div className="p-4">
            <table className="min-w-full  text-lg text-left text-slate-600">
              <thead className="ui-page text-slate-600">
                <tr>
                  <th className="py-3 px-6">#</th>
                  <th className="py-3 px-6">Id</th>
                  <th className="py-3 px-6">Name</th>
                  <th className="py-3 px-6">Mobile No</th>
                  <th className="py-3 px-6">Branch</th>
                  <th className="py-3 px-6">Semester</th>
                  <th className="py-3 px-6">Batch</th>
                  <th className="py-3 px-6">Actions</th>
                </tr>
              </thead>
              <tbody>
                {pendingUsers.length > 0 ? (
                  pendingUsers.map((user, index) => (
                    <tr
                      key={user._id}
                      className={`${
                        index % 2 === 0 ? "ui-page" : "ui-surface"
                      }`}
                    >
                      <td className="py-3 px-6">
                        {(currentPage - 1) * PAGE_SIZE + index + 1}
                      </td>
                      <td className="py-3 px-6 text-slate-600">{user.id}</td>
                      <td className="capitalize py-3 px-6">{user.username}</td>
                      <td className="py-3 px-6 text-slate-600">
                        {user.mobileNo}
                      </td>
                      <td className="py-3 px-6">{user.branch}</td>
                      <td className="py-3 px-6 text-slate-600">
                        {user.semester}
                      </td>
                      <td className="py-3 px-6">{user.batch}</td>
                      <td className="py-3 px-6 flex gap-2">
                        <button
                          onClick={() => handleAcceptUser(user._id)}
                          disabled={actionLoading === user._id}
                          className="bg-green-600 text-slate-900 py-1 px-3 rounded-lg hover:bg-green-700 transition disabled:opacity-50"
                        >
                          {actionLoading === user._id ? (
                            <BeatLoader size={10} color="#fff" />
                          ) : (
                            "Accept"
                          )}
                        </button>
                        <button
                          onClick={() => handleDeclineUser(user._id)}
                          disabled={actionLoading === user._id}
                          className="bg-red-600 text-slate-900 py-1 px-3 rounded-lg hover:bg-red-50 transition disabled:opacity-50"
                        >
                          {actionLoading === user._id ? (
                            <BeatLoader size={10} color="#fff" />
                          ) : (
                            "Decline"
                          )}
                        </button>
                      </td>
                    </tr>
                  ))
                ) : (
                  <tr>
                    <td
                      colSpan="8"
                      className="py-3 px-6 text-center text-slate-600"
                    >
                      No pending users found.
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        )}

        <div className="flex justify-center mt-4">
          <button
            onClick={() => setCurrentPage((prev) => Math.max(prev - 1, 1))}
            disabled={currentPage === 1}
            className="cursor-pointer ui-surface text-slate-900 py-2 px-4 rounded-lg hover:ui-surface transition disabled:opacity-50"
          >
            Previous
          </button>
          <span className="mx-4 mt-1 text-slate-900">{`Page ${currentPage} of ${totalPages}`}</span>
          <button
            onClick={() =>
              setCurrentPage((prev) => Math.min(prev + 1, totalPages))
            }
            disabled={currentPage === totalPages}
            className="cursor-pointer ui-surface text-slate-900 py-2 px-4 rounded-lg hover:ui-surface transition disabled:opacity-50"
          >
            Next
          </button>
        </div>
      </div>
    </>
  );
};

