export default FacultyPage;

import React, { useEffect, useState } from "react";
import axiosInstance from "../../utils/axiosInstance";
import { useSelector } from "react-redux";
import { useNavigate } from "react-router-dom";
import toast from "react-hot-toast";

const FacultyRegister = () => {
  const user = useSelector((store) => store.app.user);
  const navigate = useNavigate();
  const [students, setStudents] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [currentPage, setCurrentPage] = useState(1);
  const [totalStudents, setTotalStudents] = useState(0);
  const studentsPerPage = 10;
  const [totalPages, setTotalPages] = useState(0);
  const [showDeleteModal, setShowDeleteModal] = useState(false);
  const [userId, setuserId] = useState(null);

  const fetchStudents = async (page) => {
    try {
      setLoading(true);
      const response = await axiosInstance.post(
        "/faculty/get-students-by-faculty",
        {
          facultyId: user._id,
          page,
          limit: studentsPerPage,
        }
      );

      if (response.data.success) {
        setStudents(response.data.students);
        setTotalStudents(response.data.totalStudents);
        setTotalPages(response.data.totalPages);
      } else {
        setError(response.data.message || "Failed to fetch students.");
      }
    } catch (err) {
      setError("An error occurred while fetching students.");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchStudents(currentPage);
  }, [currentPage]);

  const handleNextPage = () => {
    if (currentPage < totalPages) setCurrentPage(currentPage + 1);
  };

  const handlePreviousPage = () => {
    if (currentPage > 1) setCurrentPage(currentPage - 1);
  };

  const formatDate = (dateString) => {
    const date = new Date(dateString);
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, "0");
    const day = String(date.getDate()).padStart(2, "0");
    const hours = String(date.getHours()).padStart(2, "0");
    const minutes = String(date.getMinutes()).padStart(2, "0");
    return `${day}-${month}-${year} ${hours}:${minutes}`;
  };

  const openDeleteModal = (studentId) => {
    setuserId(studentId);
    setShowDeleteModal(true);
  };

  const cancelDelete = () => {
    setuserId(null);
    setShowDeleteModal(false);
  };

  const handleDelete = async () => {
    try {
      // console.log(userId)
      const response = await axiosInstance.delete(
        `/faculty/remove-user/${userId}`
      );

      // console.log(response.data);
      if (response.data.success) {
        toast.success(response.data.message);
        fetchStudents(currentPage);
      } else {
        toast.error(response.data.message || "Failed to remove the user.");
      }
    } catch (error) {
      toast.error(error.response?.data?.message || "Error in removing user.");
    } finally {
      cancelDelete();
    }
  };

  return (
    <div className="relative ui-page-height ui-page text-slate-900">

      <div className="flex justify-center ui-page-top">
        <h1 className="text-2xl font-bold mb-4">Student Register</h1>
      </div>

      <button
        className="py-2 px-6 ml-6 ui-gradient mb-4   text-slate-900 font-semibold rounded-lg shadow-md   active:scale-95 transition transform duration-200"
        onClick={() => navigate(-1)}
      >
        Back
      </button>

      <div className="flex items-center ml-4 text-slate-900 py-2 px-4 rounded-full ui-card-shadow text-lg font-semibold">
        <span>Total Number of Students Register:</span>
        <span className="ml-2 text-xl font-bold">{totalStudents}</span>
      </div>

      <div>
        {loading ? (
          <div className="flex justify-center items-center h-64">
            <div className="flex flex-col items-center">
              <div className="animate-spin rounded-full h-16 w-16 border-t-4 border-blue-500 border-opacity-75"></div>
              <p className="mt-4 text-blue-700 text-lg font-medium">
                Loading, please wait...
              </p>
            </div>
          </div>
        ) : error ? (
          <p className="text-red-500">{error}</p>
        ) : (
          <div className="overflow-x-auto ui-page shadow-md rounded-lg p-4">
            <table className="min-w-full text-lg text-left text-slate-600">
              <thead className="ui-page text-slate-600">
                <tr>
                  <th className="py-3 px-6">#</th>
                  <th className="py-3 px-6">ID</th>
                  <th className="py-3 px-6">Username</th>
                  <th className="py-3 px-6">Semester</th>
                  <th className="py-3 px-6">Branch</th>
                  <th className="py-3 px-6">Batch</th>
                  <th className="py-3 px-6">Create Date</th>
                  <th className="py-3 px-6">Action</th>
                </tr>
              </thead>
              <tbody>
                {students.map((student, index) => (
                  <tr
                    key={student._id}
                    className={`${
                      index % 2 === 0 ? "ui-page" : "ui-surface"
                    }`}
                  >
                    <td className="py-3 px-6">
                      {(currentPage - 1) * studentsPerPage + index + 1}
                    </td>
                    <td className="py-3 px-6">{student?.id?.toUpperCase()}</td>
                    <td className="capitalize py-3 px-6">
                      {student?.username}
                    </td>
                    <td className="py-3 px-6">{student?.semester}</td>
                    <td className="py-3 px-6">
                      {student?.branch?.toUpperCase()}
                    </td>
                    <td className="py-3 px-6">
                      {student?.batch?.toUpperCase()}
                    </td>

                    <td className="py-3">{formatDate(student?.createdAt)} </td>
                    <td className="py-3 px-6">
                      <button
                        onClick={() => openDeleteModal(student._id)}
                        className="bg-red-600 text-slate-900 py-1 px-3 rounded-lg hover:bg-red-50 transition"
                      >
                        Delete
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>

            {/* Pagination Controls */}
            <div className="mt-4 flex items-center justify-center">
              <button
                onClick={handlePreviousPage}
                disabled={currentPage === 1}
                className="ui-surface text-slate-900 py-2 px-4 rounded-lg hover:ui-subtle transition disabled:opacity-50"
              >
                Previous
              </button>
              <span className="text-slate-600 pr-2 pl-2">
                Page {currentPage} of {totalPages}
              </span>
              <button
                onClick={handleNextPage}
                disabled={currentPage === totalPages}
                className="ui-surface text-slate-900 py-2 px-4 rounded-lg hover:ui-subtle transition disabled:opacity-50"
              >
                Next
              </button>
            </div>
          </div>
        )}
      </div>

      {/* Delete Confirmation Modal */}
      {showDeleteModal && (
        <div className="fixed inset-0 flex items-center justify-center z-50 bg-black bg-opacity-50">
          <div className="ui-surface p-6 sm:p-8 rounded-lg w-11/12 max-w-md sm:max-w-lg mx-auto">
            <h3 className="text-slate-900 text-lg sm:text-xl font-bold mb-4 text-center">
              Confirm Deletion
            </h3>
            <p className="text-slate-600 mb-4 text-sm sm:text-base text-center">
              Are you sure you want to delete this student? This action cannot
              be undone.
            </p>
            <div className="flex justify-center gap-4">
              <button
                onClick={cancelDelete}
                className="ui-subtle text-slate-900 py-2 px-4 sm:py-2.5 sm:px-6 rounded-lg hover:ui-subtle transition"
              >
                Cancel
              </button>
              <button
                onClick={handleDelete}
                className="bg-red-500 text-slate-900 py-2 px-4 sm:py-2.5 sm:px-6 rounded-lg hover:bg-red-600 transition"
              >
                Delete
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default FacultyRegister;

import React, { useState } from "react";
import * as XLSX from "xlsx";
import axiosInstance from "../../utils/axiosInstance";
import { useSelector } from "react-redux";
import toast from "react-hot-toast";
import { useNavigate } from "react-router-dom";

const StudentRegister = () => {
  const [students, setStudents] = useState([]); // Holds parsed Excel data
  const [selectedStudents, setSelectedStudents] = useState({}); // Tracks selected students for registration
  const [errorMessages, setErrorMessages] = useState([]); // Holds error messages from the backend
  const user = useSelector((store) => store.app.user);
  const [isModalOpen, setIsModalOpen] = useState(false); // Modal visibility state
  const [newStudent, setNewStudent] = useState({
    id: "",
    username: "",
    batch: "",
    semester: "",
  });
  const navigate = useNavigate();

  const handleFileUpload = (e) => {
    const file = e.target.files[0];
    // console.log(file);

    if (!file) return;

    // Create a FileReader to read the file
    const reader = new FileReader();

    reader.onload = (event) => {
      const data = new Uint8Array(event.target.result); // Read the file as ArrayBuffer
      const workbook = XLSX.read(data, { type: "array" }); // Parse the Excel data into a workbook
      const sheet = workbook.Sheets[workbook.SheetNames[0]]; // Get the first sheet
      const parsedData = XLSX.utils.sheet_to_json(sheet); // Parse the sheet into JSON data
      // console.log("Parsed Data:", parsedData); // Log parsed data to debug

      // Transform parsed data to expected format
      setStudents(
        parsedData.map((row, index) => ({
          id: row.ID?.toLowerCase() || "", // Match the key 'ID' in the parsed data
          username: row.Username || "", // Match the key 'Username'
          batch: row.Batch?.toLowerCase() || "", // Match the key 'Batch'
          semester: row.Semester || "", // Match the key 'Semester'
          index,
        }))
      );

      // Reset selected students and error messages
      setSelectedStudents({});
      setErrorMessages([]);
    };

    reader.readAsArrayBuffer(file); // Start reading the file
  };

  // Toggle select all students
  const toggleSelectAll = () => {
    if (Object.keys(selectedStudents).length === students.length) {
      setSelectedStudents({});
    } else {
      const allSelected = {};
      students.forEach((student) => (allSelected[student.index] = true));
      setSelectedStudents(allSelected);
    }
  };

  // Handle individual student selection toggle
  const toggleSelectStudent = (index) => {
    setSelectedStudents((prev) => ({
      ...prev,
      [index]: !prev[index],
    }));
  };

  // Submit selected students or registration

  const facultyId = user._id;

  const handleRegisterSelected = async () => {
    const selectedData = students.filter(
      (student) => selectedStudents[student.index]
    );

    if (selectedData.length === 0) {
      toast.error("No students selected for registration.");
      return;
    }

    try {
      const response = await axiosInstance.post("/faculty/bulk-register", {
        students: selectedData,
        facultyId,
      });

      // Display success and error messages from the response
      const { results } = response.data;
      setErrorMessages([
        ...results.errors.map((err) => `${err.id}: ${err.message}`),
      ]);

      // Optionally, you can display success messages as well
      if (results.success.length > 0) {
        toast.success("Registration completed successfully.");
      }

      // Remove successfully registered students from the list
      setStudents((prev) =>
        prev.filter((student) => !selectedStudents[student.index])
      );
      setSelectedStudents({});
    } catch (error) {
      console.error(error);
      toast.error(
        "Error registering students. Please check console for details."
      );
    }
  };

  const handleModalSubmit = () => {
    if (!newStudent.id || !newStudent.username || !newStudent.batch || !newStudent.semester) {
      toast.error("Please fill in all fields.");
      return;
    }
  
    // Add the new student to the list
    setStudents((prev) => [
      ...prev,
      {
        id: newStudent.id.toLowerCase(),
        username: newStudent.username,
        batch: newStudent.batch.toLowerCase(),
        semester: newStudent.semester,
        index: students.length,
      },
    ]);
  
    // Reset the form and close the modal
    setNewStudent({ id: "", username: "", batch: "", semester: "" });
    setIsModalOpen(false);
    toast.success("Student added successfully!");
  };

  // Handle declining a single student
  const handleDecline = (index) => {
    setStudents((prev) => prev.filter((student) => student.index !== index));
    setSelectedStudents((prev) => {
      const updated = { ...prev };
      delete updated[index];
      return updated;
    });
  };

  const [currentPage, setCurrentPage] = useState(1);
  const PAGE_SIZE = 10;

  // Calculate the total pages
  const totalPages = Math.ceil(students.length / PAGE_SIZE);

  // Slice the students to display only the current page data
  const paginatedStudents = students.slice(
    (currentPage - 1) * PAGE_SIZE,
    currentPage * PAGE_SIZE
  );

  // Handlers for pagination
  const handleNextPage = () => {
    if (currentPage < totalPages) setCurrentPage(currentPage + 1);
  };

  const handlePreviousPage = () => {
    if (currentPage > 1) setCurrentPage(currentPage - 1);
  };

  return (
    <div className="relative ui-page-height ui-page text-slate-900">

      <div className="pl-10 ui-page-top">
        <button
          className="py-2 px-6 ui-gradient   text-slate-900 font-semibold rounded-lg shadow-md   active:scale-95 transition transform duration-200"
          onClick={() => navigate(-1)}
        >
          Back
        </button>
      </div>

      
      <div className="student-import-heading mt-6 flex flex-wrap items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold mb-4">Bulk Student Registration</h1>
          {/* File Upload Input */}
          <input
            type="file"
            accept=".xlsx, .xls"
            onChange={handleFileUpload}
            className="mb-4"
            style={{ cursor: "pointer" }}
          />
        </div>
        <div>
        <button
          className="py-2 px-6 ui-gradient   text-slate-900 font-semibold rounded-lg shadow-md   active:scale-95 transition transform duration-200"
          onClick={() => setIsModalOpen(true)}
        >
          Add Single Student
        </button>
        </div>
      </div>

      {/* Render Student Data Table */}
      {students.length > 0 ? (
        <div className="overflow-x-auto ui-page shadow-md rounded-lg p-8">
          <table className="min-w-full text-lg text-left text-slate-600">
            <thead className="ui-page text-slate-600">
              <tr>
                <th className="py-3 px-6">
                  <input
                    type="checkbox"
                    className="accent-blue-500"
                    checked={
                      Object.keys(selectedStudents).length === students.length
                    }
                    onChange={toggleSelectAll}
                  />
                </th>
                <th className="py-3 px-6">#</th>
                <th className="py-3 px-6">ID</th>
                <th className="py-3 px-6">Username</th>
                <th className="py-3 px-6">Batch</th>
                <th className="py-3 px-6">Semester</th>
                <th className="py-3 px-6">Actions</th>
              </tr>
            </thead>
            <tbody>
              {paginatedStudents.map((student, index) => (
                <tr
                  key={index}
                  className={`${
                    index % 2 === 0 ? "ui-page" : "ui-surface"
                  }`}
                >
                  <td className="py-3 px-6">
                    <input
                      type="checkbox"
                      className="accent-blue-500"
                      checked={!!selectedStudents[student.index]}
                      onChange={() => toggleSelectStudent(student.index)}
                    />
                  </td>
                  <td className="py-3 px-6">
                    {(index + 1 + (currentPage - 1) * PAGE_SIZE)
                      .toString()
                      .padStart(2, "0")}
                  </td>
                  <td className="py-3 px-6">{student.id}</td>
                  <td className="capitalize py-3 px-6">{student.username}</td>
                  <td className="py-3 px-6">{student.batch}</td>
                  <td className="py-3 px-6">{student.semester}</td>
                  <td className="py-3 px-6 flex gap-2">
                    <button
                      className="bg-red-600 text-slate-900 py-1 px-3 rounded-lg hover:bg-red-50 transition"
                      onClick={() => handleDecline(student.index)}
                    >
                      Decline
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>

          {/* Pagination Controls */}
          <div className="mt-4 flex items-center justify-center">
            <button
              onClick={handlePreviousPage}
              disabled={currentPage === 1}
              className="ui-surface text-slate-900 py-2 px-4 rounded-lg hover:ui-subtle transition disabled:opacity-50"
            >
              Previous
            </button>
            <span className="text-slate-600 pr-2 pl-2 ">
              Page {currentPage} of {totalPages}
            </span>
            <button
              onClick={handleNextPage}
              disabled={currentPage === totalPages}
              className="ui-surface text-slate-900 py-2 px-4 rounded-lg hover:ui-subtle transition disabled:opacity-50"
            >
              Next
            </button>
          </div>

          <button
            onClick={handleRegisterSelected}
            className="bg-green-600 hover:bg-green-700 text-slate-900 py-2 px-6 rounded-lg shadow transition"
          >
            Register Selected
          </button>
        </div>
      ) : (
        <div className="text-center py-6 text-slate-600">
          <p>No data available</p>
        </div>
      )}

      {/* Display error messages */}
      <div className="p-4">
        {errorMessages.length > 0 && (
          <div className="mt-4 bg-red-100 text-red-800 p-4 rounded">
            <h3 className="font-bold">Errors:</h3>
            <ul>
              {errorMessages.map((message, index) => (
                <li key={index}>{message}</li>
              ))}
            </ul>
          </div>
        )}
      </div>



      {isModalOpen && (
        <div className="fixed inset-0 flex items-center justify-center bg-black bg-opacity-50 z-50">
          <div className="ui-page rounded-lg ui-card-shadow p-8" style={{ width: "min(100%, 560px)" }}>
            <h2 className="text-2xl font-bold text-slate-900 mb-4">Add Student</h2>
            <div className="flex flex-col gap-4">
              <input
                type="text"
                placeholder="Student ID"
                value={newStudent.id}
                onChange={(e) => setNewStudent({ ...newStudent, id: e.target.value })}
                className="p-4 rounded-md ui-surface text-slate-900 placeholder-slate-500 focus:ring-2 focus:ring-blue-500 focus:outline-none w-full"
              />
              <input
                type="text"
                placeholder="Username"
                value={newStudent.username}
                onChange={(e) => setNewStudent({ ...newStudent, username: e.target.value })}
                className="p-4 rounded-md ui-surface text-slate-900 placeholder-slate-500 focus:ring-2 focus:ring-blue-500 focus:outline-none w-full"
              />
              <input
                type="text"
                placeholder="Batch"
                value={newStudent.batch}
                onChange={(e) => setNewStudent({ ...newStudent, batch: e.target.value })}
                className="p-4 rounded-md ui-surface text-slate-900 placeholder-slate-500 focus:ring-2 focus:ring-blue-500 focus:outline-none w-full"
              />
              <input
                type="text"
                placeholder="Semester"
                value={newStudent.semester}
                onChange={(e) => setNewStudent({ ...newStudent, semester: e.target.value })}
                className="p-4 rounded-md ui-surface text-slate-900 placeholder-slate-500 focus:ring-2 focus:ring-blue-500 focus:outline-none w-full"
              />
              <div className="flex justify-end gap-4">
                <button
                  className="py-2 px-4 ui-subtle text-slate-900 rounded-lg hover:ui-subtle transition"
                  onClick={() => setIsModalOpen(false)}
                >
                  Cancel
                </button>
                <button
                  className="py-2 px-4 bg-blue-600 text-slate-900 rounded-lg hover:bg-blue-500 transition"
                  onClick={handleModalSubmit}
                >
                  Add Student
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default StudentRegister;

import React, { useState, useEffect, useRef } from "react";
import { useSelector, useDispatch } from "react-redux";
import { useNavigate, Link, useLocation } from "react-router-dom";
import { motion, AnimatePresence } from "framer-motion";
import toast from "react-hot-toast";
import { logout, setUser } from "../redux/userSlice";
import axiosInstance from "../utils/axiosInstance";
import { persistor } from "../redux/store";
import { logoutHistory } from "../redux/slices/historySlice";
import { logoutSubmissions } from "../redux/slices/submissionSlice";
import {
  Menu,
  X,
  Home,
  User,
  History,
  HelpCircle,
  Code2,
  ClipboardList,
  LogOut,
  ChevronDown,
  Plus,
  Terminal,
} from "lucide-react";
import { navigateWithTransition } from '../utils/transitionManager.jsx';

const Header = () => {
  const user = useSelector((store) => store.app.user);
  const authStatus = useSelector((store) => store.app.authStatus);
  const dispatch = useDispatch();
  const navigate = useNavigate();
  const location = useLocation();
  const [isAdmin, setIsAdmin] = useState(false);
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [isScreenSmall, setIsScreenSmall] = useState(false);
  const [isOnMakeContest, setIsOnMakeContest] = useState(false);
  const [isUserMenuOpen, setIsUserMenuOpen] = useState(false);
  const [scrolled, setScrolled] = useState(false);
  const userMenuRef = useRef(null);
  const headerRef = useRef(null);

  useEffect(() => {
    const handleScroll = () => {
      const scrollPosition = window.scrollY;
      const scrollThreshold = 20;
      
      // Use requestAnimationFrame for smoother animation
      requestAnimationFrame(() => {
        if (scrollPosition > scrollThreshold) {
          if (!scrolled) setScrolled(true);
        } else {
          if (scrolled) setScrolled(false);
        }
      });
    };

    window.addEventListener("scroll", handleScroll, { passive: true });
    return () => {
      window.removeEventListener("scroll", handleScroll);
    };
  }, [scrolled]);

  useEffect(() => {
    const handleClickOutside = (event) => {
      if (userMenuRef.current && !userMenuRef.current.contains(event.target)) {
        setIsUserMenuOpen(false);
      }
    };

    if (isUserMenuOpen) {
      document.addEventListener("mousedown", handleClickOutside);
    }

    return () => {
      document.removeEventListener("mousedown", handleClickOutside);
    };
  }, [isUserMenuOpen]);

  useEffect(() => {
    if (authStatus === false) {
      navigate("/");
    }
  }, [authStatus, navigate]);

  useEffect(() => {
    setIsAdmin(user?.role);
  }, [user?.role]);

  useEffect(() => {
    const handleResize = () => {
      setIsScreenSmall(window.innerWidth <= 1200);
    };

    handleResize();
    window.addEventListener("resize", handleResize);

    return () => {
      window.removeEventListener("resize", handleResize);
    };
  }, []);

  useEffect(() => {
    setIsOnMakeContest(location.pathname === "/make-contest");
  }, [location]);

  const logoutHandler = async () => {
    try {
      await axiosInstance.post("auth/logout");
      localStorage.removeItem("UserToken");
      
      // Dispatch actions in the correct order
      dispatch(logoutSubmissions());
      dispatch(logoutHistory());
      dispatch(logout());
      
      await persistor.purge();
      toast.success("Logged out successfully");
      navigate("/");
    } catch (error) {
      console.error("Logout Error:", error);
      toast.error("Failed to log out. Please try again.");
    }
  };

  const toggleMakeContest = () => {
    if (isOnMakeContest) {
      navigate("/browse");
    } else {
      navigate("/make-contest");
    }
  };

  const handleNavigate = (path) => {
    // Smooth navigation with transition
    dispatch(navigateWithTransition(navigate, path));
  };

  const isActive = (path) => location.pathname === path;
  const makeContestButtonText =
    user?.role === "student" ? "Contest" : "Make Contest";

  const navLinks = [
    { path: "/browse", label: "Home", icon: <Home size={18} /> },
    {
      path: "/make-problem",
      label: user?.role === "student" ? "Problems" : "Problem",
      icon: <Code2 size={18} />,
    },
    { path: "/profile", label: "Profile", icon: <User size={18} /> },
    { path: "/history", label: "History", icon: <History size={18} /> },
    { path: "/support", label: "Support", icon: <HelpCircle size={18} /> },
  ];

  if (user?.role === "admin") {
    navLinks.push({
      path: "/pending-requests",
      label: "Requests",
      icon: <ClipboardList size={18} />,
    });
  }
  if (user?.role === "faculty") {
    navLinks.push({
      path: "/faculty-section",
      label: "Requests",
      icon: <ClipboardList size={18} />,
    });
  }

  return (
    <motion.nav
      initial={{ y: -100 }}
      animate={{ y: 0 }}
      ref={headerRef}
      className={`z-50 w-full fixed ${
        scrolled 
          ? "top-0 bg-black shadow-sm" 
          : "top-3 mx-auto max-w-[95%] left-0 right-0 bg-black rounded-full px-2"
      } transition-all duration-300`}
    >
      <div className={`mx-auto px-4 ${scrolled ? "max-w-7xl sm:px-6 lg:px-8" : "max-w-7xl"}`}>
        <div className="flex items-center justify-between h-14">
          <motion.div 
            whileHover={{ scale: 1.03 }} 
            className="flex items-center space-x-2"
            onClick={() => navigate('/browse')}
            style={{ cursor: 'pointer' }}
          >
            <div className="relative flex items-center">
              <Terminal 
                size={24} 
                className={`${
                  scrolled 
                    ? "text-blue-500" 
                    : "text-blue-400"
                } transition-colors duration-300`}
              />
              <span className="absolute -top-0.5 -right-0.5 w-1.5 h-1.5 bg-blue-500 rounded-full"></span>
            </div>
            <h1 className={`text-2xl font-bold ${
              scrolled ? "translate-y-0" : "translate-y-0.5"
            } transition-transform duration-300`}>
              <span className="font-medium italic text-white" style={{ fontFamily: "'Pacifico', cursive, system-ui" }}>
                Codify
              </span>
              <span className="text-blue-500 text-xl font-normal">.</span>
            </h1>
          </motion.div>

          {isScreenSmall && user ? (
            <button
              onClick={() => setIsMenuOpen(!isMenuOpen)}
              className={`text-white p-2 rounded-md transition-colors ${
                scrolled ? "hover:bg-blue-500/20" : "hover:bg-white/10"
              }`}
            >
              {isMenuOpen ? <X size={24} /> : <Menu size={24} />}
            </button>
          ) : (
            user && (
              <div className="hidden md:flex items-center space-x-3">
                {navLinks.map((link) => (
                  <Link
                    key={link.path}
                    onClick={(e) => {
                      e.preventDefault();
                      handleNavigate(link.path);
                    }}
                    to={link.path}
                    className={`flex items-center space-x-1 px-3 py-2 rounded-md text-sm font-medium transition-all duration-200 ${
                      isActive(link.path)
                        ? `bg-blue-500/20 text-blue-400 ${scrolled ? 'shadow-inner' : ''}`
                        : `text-gray-300 hover:bg-blue-500/10 hover:text-blue-300 ${
                            scrolled ? 'hover:shadow-sm' : ''
                          }`
                    }`}
                  >
                    {link.icon}
                    <span>{link.label}</span>
                  </Link>
                ))}

                {/* User Dropdown */}
                <div className="relative" ref={userMenuRef}>
                  <button
                    onClick={() => setIsUserMenuOpen(!isUserMenuOpen)}
                    className={`flex items-center space-x-1 px-3 py-2 rounded-md text-sm font-medium transition-all duration-200 ${
                      isUserMenuOpen
                        ? "bg-blue-500/20 text-blue-400"
                        : `text-gray-300 hover:bg-blue-500/10 hover:text-blue-300 ${
                            scrolled ? 'hover:shadow-sm' : ''
                          }`
                    }`}
                  >
                    <div className="w-6 h-6 rounded-full bg-blue-500/30 flex items-center justify-center text-blue-200 text-xs mr-1">
                      {user?.username?.charAt(0).toUpperCase()}
                    </div>
                    <span className="font-medium">{user?.username?.split(' ')[0]}</span>
                    <ChevronDown 
                      size={16} 
                      className={`transition-transform duration-200 ${isUserMenuOpen ? 'rotate-180' : 'rotate-0'}`}
                    />
                  </button>

                  <AnimatePresence>
                    {isUserMenuOpen && (
                      <motion.div
                        initial={{ opacity: 0, y: -10, scale: 0.95 }}
                        animate={{ opacity: 1, y: 0, scale: 1 }}
                        exit={{ opacity: 0, y: -10, scale: 0.95 }}
                        transition={{ duration: 0.2 }}
                        className="absolute right-0 mt-2 w-56 bg-gray-800 border border-gray-700 rounded-lg shadow-xl py-1 overflow-hidden"
                      >
                        <div className="px-4 py-3 border-b border-gray-700">
                          <p className="text-sm text-gray-400">Logged in as</p>
                          <p className="text-sm font-medium text-white truncate">{user?.email}</p>
                        </div>
                        <button
                          onClick={logoutHandler}
                          className="flex items-center space-x-2 w-full px-4 py-2 text-sm text-gray-300 hover:bg-red-500/10 hover:text-red-300"
                        >
                          <LogOut size={16} />
                          <span>Logout</span>
                        </button>
                      </motion.div>
                    )}
                  </AnimatePresence>
                </div>

                {/* Make Contest Button */}
                <motion.button
                  whileHover={{ scale: 1.05 }}
                  whileTap={{ scale: 0.95 }}
                  onClick={toggleMakeContest}
                  className={`flex items-center space-x-1 px-4 py-2 text-white rounded-md font-medium shadow-lg transition-all duration-300 ${
                    scrolled 
                      ? "bg-blue-600 hover:bg-blue-700" 
                      : "bg-gradient-to-r from-blue-500 to-purple-600 hover:from-blue-600 hover:to-purple-700"
                  }`}
                >
                  {isOnMakeContest ? <Home size={18} /> : <Plus size={18} />}
                  <span>{isOnMakeContest ? "Home" : makeContestButtonText}</span>
                </motion.button>
              </div>
            )
          )}
        </div>
      </div>

      <AnimatePresence>
        {isScreenSmall && isMenuOpen && user && (
          <motion.div
            initial={{ opacity: 0, height: 0 }}
            animate={{ opacity: 1, height: "auto" }}
            exit={{ opacity: 0, height: 0 }}
            className="border-t border-blue-500/20"
          >
            <div className="px-2 pt-2 pb-3 space-y-1">
              {navLinks.map((link) => (
                <Link
                  key={link.path}
                  to={link.path}
                  onClick={() => setIsMenuOpen(false)}
                  className={`flex items-center space-x-2 px-3 py-2 rounded-md text-base font-medium ${
                    isActive(link.path)
                      ? "bg-blue-500/20 text-blue-400"
                      : "text-gray-300 hover:bg-blue-500/10 hover:text-blue-300"
                  }`}
                >
                  {link.icon}
                  <span>{link.label}</span>
                </Link>
              ))}

              <button
                onClick={logoutHandler}
                className="flex items-center space-x-2 w-full px-3 py-2 rounded-md text-base font-medium text-red-400 hover:bg-red-500/10"
              >
                <LogOut size={18} />
                <span>Logout</span>
              </button>

              <button
                onClick={() => {
                  setIsMenuOpen(false);
                  toggleMakeContest();
                }}
                className="flex items-center space-x-2 w-full px-3 py-2 rounded-md text-base font-medium bg-gradient-to-r from-blue-500 to-purple-600 text-white hover:from-blue-600 hover:to-purple-700"
              >
                {isOnMakeContest ? <Home size={18} /> : <Plus size={18} />}
                <span>{isOnMakeContest ? "Home" : makeContestButtonText}</span>
              </button>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </motion.nav>
  );
};

export default Header;

import React, { useEffect } from "react";
import { useDispatch, useSelector } from "react-redux";
import { fetchHistory, setCurrentPage } from "../redux/slices/historySlice";
import {
  ChevronLeft,
  ChevronRight,
  Clock,
  Code,
  CheckCircle,
  XCircle,
  AlertCircle,
  FileText,
} from "lucide-react";
import { useNavigate } from "react-router-dom";

const History = () => {
  const dispatch = useDispatch();
  const navigate = useNavigate();
  const { history, loading, error, currentPage, totalPages } = useSelector(
    (state) => state.history
  );
  const user = useSelector((state) => state.app.user);

  useEffect(() => {
    if (history.length === 0) {
      dispatch(fetchHistory({ page: currentPage, limit: 9 }));
    }
  }, [dispatch, currentPage, history.length]);

  const handlePageChange = (newPage) => {
    if (newPage >= 1 && newPage <= totalPages) {
      dispatch(setCurrentPage(newPage));
      dispatch(fetchHistory({ page: newPage, limit: 9 }));
    }
  };

  // Utility functions
  const formatDate = (dateString) => {
    const date = new Date(dateString);
    return `${date.toLocaleDateString()} ${date.toLocaleTimeString([], {
      hour: "2-digit",
      minute: "2-digit",
    })}`;
  };

  const getStatusInfo = (status) => {
    if (!status) return { icon: AlertCircle, color: "gray" };
    switch (status.toLowerCase()) {
      case "completed":
      case "accepted":
        return { icon: CheckCircle, color: "green" };
      case "rejected":
        return { icon: XCircle, color: "red" };
      case "time limit exceeded":
        return { icon: Clock, color: "yellow" };
      case "runtime error":
      case "compilation error":
        return { icon: AlertCircle, color: "orange" };
      default:
        return { icon: AlertCircle, color: "gray" };
    }
  };

  return (
    <div className="ui-page-height ui-gradient   text-slate-900 pt-10">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-12">
        <header className="flex flex-col md:flex-row justify-between items-center mb-8">
          <div>
            <h1 className="text-3xl font-bold  text-slate-900 ui-gradient  ">
              Submission History
            </h1>
            <p className="text-slate-600 mt-2">
              Complete record of your code submissions
            </p>
          </div>
          <div className="p-4 bg-blue-500/10 rounded-full">
            <Code size={28} className="text-blue-700" />
          </div>
        </header>

        {loading ? (
          <div className="flex flex-col items-center justify-center h-64">
            <div className="animate-spin h-16 w-16 border-4 border-blue-500 border-t-transparent rounded-full"></div>
            <p className="mt-4 text-blue-700 text-xl font-medium">
              Loading history...
            </p>
          </div>
        ) : error ? (
          <div className="mb-8 bg-red-500/10 border border-red-500/30 rounded-lg p-6">
            <div className="flex items-center">
              <AlertCircle size={24} className="text-red-500 mr-4" />
              <div>
                <h3 className="text-red-500 font-semibold text-lg">
                  Error Loading History
                </h3>
                <p className="text-slate-600">{error}</p>
              </div>
            </div>
          </div>
        ) : history.length === 0 ? (
          <div className="bg-blue-500/10 border border-blue-500/30 rounded-lg p-8 text-center">
            <FileText size={48} className="mx-auto text-blue-700 mb-4" />
            <p className="text-xl font-medium text-slate-900 mb-2">
              No history found
            </p>
            <p className="text-slate-600 mb-6">
              You haven't submitted any solutions yet.
            </p>
            <button
              onClick={() => navigate("/problems")}
              className="px-6 py-3 bg-blue-600 text-slate-900 rounded-lg hover:bg-blue-700 transition-all duration-300 ui-card-shadow"
            >
              Browse Problems
            </button>
          </div>
        ) : (
          <div className="ui-gradient   rounded-lg ui-card-shadow border border-slate-200 overflow-hidden">
            <div className="overflow-x-auto">
              <table className="w-full">
                <thead className="ui-surface border-b border-slate-200">
                  <tr>
                    <th className="py-4 px-6 text-left text-xs font-medium text-slate-600 uppercase tracking-wider">
                      #
                    </th>
                    <th className="py-4 px-6 text-left text-xs font-medium text-slate-600 uppercase tracking-wider">
                      Problem
                    </th>
                    <th className="py-4 px-6 text-center text-xs font-medium text-slate-600 uppercase tracking-wider">
                      Language
                    </th>
                    <th className="py-4 px-6 text-center text-xs font-medium text-slate-600 uppercase tracking-wider">
                      Test Cases
                    </th>
                    <th className="py-4 px-6 text-center text-xs font-medium text-slate-600 uppercase tracking-wider">
                      Status
                    </th>
                    <th className="py-4 px-6 text-center text-xs font-medium text-slate-600 uppercase tracking-wider">
                      Submitted
                    </th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-200">
                  {history.map((submission, index) => {
                    const { icon: StatusIcon, color } = getStatusInfo(
                      submission.status
                    );
                    return (
                      <tr
                        key={submission._id}
                        onClick={() =>
                          navigate(`/submissions/${submission._id}`)
                        }
                        className="hover:bg-blue-500/5 cursor-pointer transition-colors duration-200"
                      >
                        <td className="py-4 px-6 text-sm font-medium text-slate-600">
                          {index + 1 + (currentPage - 1) * 9}
                        </td>
                        <td className="py-4 px-6">
                          <div className="flex items-center">
                            <div className="flex-shrink-0 h-10 w-10 rounded-full ui-surface flex items-center justify-center">
                              <Code size={18} className="text-blue-700" />
                            </div>
                            <div className="ml-4">
                              <div className="text-sm font-medium text-slate-900">
                                {submission.problem_id?.title || "Untitled"}
                              </div>
                            </div>
                          </div>
                        </td>
                        <td className="py-4 px-6 text-sm text-center">
                          <span className="px-3 py-1 inline-flex text-xs font-semibold rounded-full ui-surface text-slate-600 capitalize">
                            {submission.language || "Unknown"}
                          </span>
                        </td>
                        <td className="py-4 px-6 text-sm text-center">
                          {submission.numberOfTestCase != null &&
                          submission.numberOfTestCasePass != null ? (
                            <div className="flex items-center justify-center">
                              <div className="relative w-full max-w-[100px] h-2 ui-surface rounded-full overflow-hidden">
                                <div
                                  className="absolute top-0 left-0 h-full bg-blue-500 rounded-full"
                                  style={{
                                    width: `${
                                      (submission.numberOfTestCasePass /
                                        submission.numberOfTestCase) *
                                      100
                                    }%`,
                                  }}
                                ></div>
                              </div>
                              <span className="ml-2 text-xs font-medium">
                                {submission.numberOfTestCasePass}/
                                {submission.numberOfTestCase}
                              </span>
                            </div>
                          ) : (
                            <span className="text-slate-600">N/A</span>
                          )}
                        </td>
                        <td className="py-4 px-6 text-sm text-center">
                          <div className="flex items-center justify-center">
                            <StatusIcon
                              size={16}
                              className={`text-${color}-500 mr-1.5`}
                            />
                            <span className={`text-${color}-500 capitalize`}>
                              {submission.status || "Unknown"}
                            </span>
                          </div>
                        </td>
                        <td className="py-4 px-6 text-sm text-center text-slate-600">
                          <div className="flex items-center justify-center">
                            <Clock size={14} className="mr-1.5" />
                            <span>{formatDate(submission.createdAt)}</span>
                          </div>
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>

            {/* Pagination Controls */}
            <div className="ui-surface px-6 py-4 border-t border-slate-200 flex items-center justify-between">
              <span className="text-sm text-slate-600">
                Showing page {currentPage} of {totalPages}
              </span>
              <div className="flex space-x-2">
                <button
                  onClick={() => handlePageChange(currentPage - 1)}
                  disabled={currentPage === 1}
                  className={`flex items-center justify-center px-4 py-2 rounded-lg text-sm font-medium transition-all duration-200 ${
                    currentPage === 1
                      ? "ui-surface text-slate-600 cursor-not-allowed"
                      : "ui-surface text-slate-900 hover:ui-subtle"
                  }`}
                >
                  <ChevronLeft size={16} className="mr-1" />
                  Previous
                </button>
                <button
                  onClick={() => handlePageChange(currentPage + 1)}
                  disabled={currentPage === totalPages}
                  className={`flex items-center justify-center px-4 py-2 rounded-lg text-sm font-medium transition-all duration-200 ${
                    currentPage === totalPages
                      ? "ui-surface text-slate-600 cursor-not-allowed"
                      : "bg-blue-600 text-slate-900 hover:bg-blue-500"
                  }`}
                >
                  Next
                  <ChevronRight size={16} className="ml-1" />
                </button>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default History;

import React, { useState, useEffect } from "react";
import toast from "react-hot-toast";
import { useNavigate } from "react-router-dom";
import { useDispatch, useSelector } from "react-redux";
import { fetchProfilePicThunk, setImageUrl, setLoading, setUser } from "../redux/userSlice";
import axiosInstance from "../utils/axiosInstance";
import { SEM, BRANCH } from "../utils/constants";
import PasswordChange from "./PassWordChange";
import { ClipLoader } from "react-spinners";

const Login = () => {
  const user = useSelector((store) => store.app.user);
  const [isLogin, setIsLogin] = useState(true);
  const authStatus = useSelector((store) => store.app.authStatus);
  const [fullName, setFullName] = useState("");
  const [username, setUsername] = useState("");
  const [idOrEmail, setIdOrEmail] = useState("");
  const [mobileNo, setMobileNo] = useState("");
  const [branch, setBranch] = useState("");
  const [sem, setSem] = useState("");
  const [batch, setBatch] = useState("");
  const [subject, setSubject] = useState("");
  const [subjects, setSubjects] = useState([]);
  const [password, setPassword] = useState("");
  const [showPassword, setShowPassword] = useState(false);
  const [isFirstTime, setIsFirstTime] = useState(false);
  const navigate = useNavigate();
  const dispatch = useDispatch();
  const isLoading = useSelector((store) => store.app.isLoading);
  const [userType, setUserType] = useState("");
  const [isLoad, setIsLoad] = useState(false);
  const [canTerminateSession, setCanTerminateSession] = useState(false);
  const [cachedCredentials, setCachedCredentials] = useState(null);

  const toggleLogin = () => {
    setIsLogin(!isLogin);
    setCanTerminateSession(false);
    setCachedCredentials(null);
  };

  useEffect(() => {
    if (authStatus) {
      navigate("/browse");
    } else {
      navigate("/");
    }
  }, [authStatus]);

  useEffect(() => {
    const fetchSubjects = async () => {
      try {
        if (userType === "student") {
          setIsLoad(true);
          const res = await axiosInstance.get("auth/fetch-subjects");
          if (res.data.success) {
            // console.log(res.data.subjects);
            setSubjects(res.data.subjects);
          }
          setIsLoad(false);
        }
      } catch (error) {
        setIsLoad(false);
        console.error("Failed to fetch subjects:", error);
      }
    };

    fetchSubjects();
  }, [userType]);

  const validateRegistration = () => {
    if (!username || !idOrEmail || !userType || !subject) {
      toast.error("Username, ID/Email, User Type, and Subject are required.");
      return false;
    }
    if (userType === "student") {
      if (!mobileNo || !branch || !sem || !batch) {
        toast.error("All fields are required for student registration.");
        return false;
      }
      if (mobileNo.length !== 10 || !/^\d+$/.test(mobileNo)) {
        toast.error("Mobile number must be 10 digits.");
        return false;
      }
    } else if (userType === "faculty") {
      if (!/\S+@\S+\.\S+/.test(idOrEmail)) {
        toast.error("Please enter a valid email for faculty.");
        return false;
      }
    }
    return true;
  };

  const handleRegistration = async (e) => {
    e.preventDefault();
    if (!validateRegistration()) return;

    const selectedSubject = subjects.find((subj) => subj.id === subject);
    const newUser = {
      username,
      id: userType === "student" ? idOrEmail.toLowerCase() : undefined, // Convert ID to lowercase
      facultyId: userType === "student" ? selectedSubject.id : undefined,
      email: userType === "faculty" ? idOrEmail.toLowerCase() : undefined, // Convert email to lowercase
      mobileNo: userType === "student" ? mobileNo : undefined,
      branch: userType === "student" ? branch.toLowerCase() : undefined, // Convert branch to lowercase
      semester: userType === "student" ? sem : undefined,
      batch: userType === "student" ? batch.toLowerCase() : undefined,
      subject: userType === "student" ? selectedSubject.subject : subject,
      role: userType,
    };

    // console.log(newUser);

    try {
      dispatch(setLoading(true));

      const res = await axiosInstance.post("auth/register", newUser);

      if (res.data.success) {
        toast.success(res.data.message);
        setIsLogin(true);
      }
    } catch (error) {
      toast.error(error.response?.data?.message || "Registration failed.");
    } finally {
      dispatch(setLoading(false));
    }
  };

  const validateLogin = () => {
    if (!idOrEmail || !password) {
      toast.error("ID/Email and password are required for login.");
      return false;
    }
    return true;
  };

  const handleLogin = async (e, options = {}) => {
    if (e && e.preventDefault) e.preventDefault();
    if (!validateLogin()) return;

    dispatch(setLoading(true));
    const userPayload = {
      [idOrEmail.includes("@") ? "email" : "id"]: idOrEmail.toLowerCase().trim(),
      password,
      terminateExisting: Boolean(options.terminateExisting),
    };

    try {
      const url = `auth/login`;
      const res = await axiosInstance.post(url, userPayload);
      console.log(res.data);
      if (res.data.success) {
        setCanTerminateSession(false);
        setCachedCredentials(null);

        const { firstTimeLogin, message } = res.data;
        if (firstTimeLogin) {
          setIsFirstTime(true);
          toast.success("Welcome to your first login!");
          return;
        }

        const { user: loggedInUser } = res.data;
        toast.success(message || "Login successful!");
        dispatch(setUser(loggedInUser));
        dispatch(setLoading(true));
        dispatch(fetchProfilePicThunk());
        dispatch(setLoading(false));
        resetForm();
        navigate("/browse");
      } else {
        toast.error(res.data.message || "Login failed!");
      }
    } catch (error) {
      const errorMessage =
        error?.response?.data?.message || "An error occurred during login.";
      toast.error(errorMessage);

      if (error?.response?.data?.canTerminate) {
        setCanTerminateSession(true);
        setCachedCredentials(userPayload);
      } else {
        setCanTerminateSession(false);
        setCachedCredentials(null);
      }
    } finally {
      dispatch(setLoading(false));
    }
  };

  const handleTerminateAndLogin = async () => {
    if (!cachedCredentials) return;
    dispatch(setLoading(true));
    try {
      const res = await axiosInstance.post("auth/login", {
        ...cachedCredentials,
        terminateExisting: true,
      });
      if (res.data.success) {
        setCanTerminateSession(false);
        setCachedCredentials(null);
        const { user: loggedInUser, message } = res.data;
        toast.success(message || "Previous session terminated. Welcome back!");
        dispatch(setUser(loggedInUser));
        dispatch(setLoading(true));
        dispatch(fetchProfilePicThunk());
        dispatch(setLoading(false));
        resetForm();
        navigate("/browse");
      } else {
        toast.error(res.data.message || "Login failed!");
      }
    } catch (error) {
      toast.error(
        error?.response?.data?.message || "Failed to terminate session and log in."
      );
    } finally {
      dispatch(setLoading(false));
    }
  };

  const resetForm = () => {
    setFullName("");
    setUsername("");
    setIdOrEmail("");
    setPassword("");
    setCanTerminateSession(false);
    setCachedCredentials(null);
  };

  return (
    <>
      <div style={{ backgroundColor: "var(--background)" }}>
        <div className="relative ui-page-height flex items-center justify-center ui-gradient overflow-hidden py-12 px-4 sm:px-6 lg:px-8">
          {isFirstTime ? (
            <PasswordChange id={idOrEmail} />
          ) : (
            <form
              onSubmit={isLogin ? handleLogin : handleRegistration}
              className="flex flex-col w-full max-w-lg p-8 space-y-6 ui-page bg-opacity-90 rounded-lg ui-card-shadow"
            >
              <h1 className="text-4xl text-slate-900 font-bold text-center">
                {isLogin ? "Login" : "Signup"}
              </h1>
              {!isLogin && (
                <>
                  {/* username */}
                  <input
                    value={username}
                    onChange={(e) => setUsername(e.target.value)}
                    type="text"
                    placeholder="Username"
                    className="p-4 rounded-md ui-surface text-slate-900 placeholder-slate-500 focus:ring-2 focus:ring-blue-500 focus:outline-none w-full"
                  />

                  {/* idOrEmail and userType */}
                  <div className="grid grid-cols-2 gap-4">
                    <input
                      value={idOrEmail}
                      onChange={(e) => setIdOrEmail(e.target.value)}
                      type={userType === "faculty" ? "email" : "text"}
                      placeholder={
                        userType === "faculty" ? "Faculty Email" : "Student ID"
                      }
                      className="p-4 rounded-md ui-surface text-slate-900 placeholder-slate-500 focus:ring-2 focus:ring-blue-500 focus:outline-none"
                    />

                    <select
                      id="userType"
                      value={userType}
                      onChange={(e) => {
                        setUserType(e.target.value);
                        setSubject("");
                      }}
                      className="p-3 w-full cursor-pointer rounded-md ui-surface text-slate-900 placeholder-slate-500 focus:ring-2 focus:ring-blue-500 focus:outline-none"
                    >
                      <option value="" disabled>
                        -- Select User Type --
                      </option>
                      <option value="student">Student</option>
                      <option value="faculty">Faculty</option>
                    </select>
                  </div>

                  {/* For Students: branch, semester, batch, mobileNo */}
                  {userType === "student" && (
                    <>
                      <div className="grid grid-cols-2 gap-4">
                        <select
                          value={branch}
                          onChange={(e) => setBranch(e.target.value)}
                          className="p-4 cursor-pointer rounded-md ui-surface text-slate-900 placeholder-slate-500 focus:ring-2 focus:ring-blue-500 focus:outline-none"
                        >
                          <option value="">Select Branch</option>
                          {Object.values(BRANCH).map((branchOption, index) => (
                            <option key={index} value={branchOption}>
                              {branchOption}
                            </option>
                          ))}
                        </select>

                        <select
                          value={sem}
                          onChange={(e) => setSem(e.target.value)}
                          className="p-4 cursor-pointer rounded-md ui-surface text-slate-900 placeholder-slate-500 focus:ring-2 focus:ring-blue-500 focus:outline-none"
                        >
                          <option value="">Select Semester</option>
                          {Object.values(SEM).map((semOption, index) => (
                            <option key={index} value={semOption}>
                              Semester {semOption}
                            </option>
                          ))}
                        </select>
                      </div>

                      <div className="grid grid-cols-2 gap-4">
                        <select
                          value={batch}
                          onChange={(e) => setBatch(e.target.value)}
                          className="p-4 rounded-md ui-surface text-slate-900 placeholder-slate-500 focus:ring-2 focus:ring-blue-500 focus:outline-none"
                        >
                          <option value="" disabled>
                            Select Batch
                          </option>
                          <option value="a1">A1</option>
                          <option value="b1">B1</option>
                          <option value="c1">C1</option>
                          <option value="d1">D1</option>
                          <option value="a2">A2</option>
                          <option value="b2">B2</option>
                          <option value="c2">C2</option>
                          <option value="d2">D2</option>
                        </select>

                        <input
                          value={mobileNo}
                          onChange={(e) => setMobileNo(e.target.value)}
                          type="text"
                          placeholder="Mobile No"
                          className="p-4 rounded-md ui-surface text-slate-900 placeholder-slate-500 focus:ring-2 focus:ring-blue-500 focus:outline-none"
                        />
                      </div>
                    </>
                  )}

                  {/* Subject */}
                  <div className="mt-4">
                    {userType === "student" && (
                      <select
                        value={subject}
                        onChange={(e) => setSubject(e.target.value)}
                        className="p-4 w-full cursor-pointer rounded-md ui-surface text-slate-900 placeholder-slate-500 focus:ring-2 focus:ring-blue-500 focus:outline-none"
                      >
                        <option value="" disabled>
                          -- Select Subject --
                        </option>
                        {subjects.map((subj, index) => (
                          <option key={index} value={subj.id}>
                            {subj.subject} ({subj.teacher})
                          </option>
                        ))}
                      </select>
                    )}

                    {userType === "faculty" && (
                      <input
                        value={subject}
                        onChange={(e) => setSubject(e.target.value)}
                        type="text"
                        placeholder="Enter Subject"
                        className="p-4 w-full rounded-md ui-surface text-slate-900 placeholder-slate-500 focus:ring-2 focus:ring-blue-500 focus:outline-none"
                      />
                    )}
                  </div>
                </>
              )}
              {isLogin && (
                <>
                  <input
                    value={idOrEmail}
                    onChange={(e) => {
                      setIdOrEmail(e.target.value);
                      setCanTerminateSession(false);
                    }}
                    type="name"
                    placeholder="Id"
                    className="p-4 rounded-md ui-surface text-slate-900 placeholder-slate-500 focus:ring-2 focus:ring-blue-500 focus:outline-none"
                  />
                  <div className="relative w-full">
                    <input
                      value={password}
                      onChange={(e) => {
                        setPassword(e.target.value);
                        setCanTerminateSession(false);
                      }}
                      type={showPassword ? "text" : "password"}
                      placeholder="Password"
                      className="p-4 w-full rounded-md ui-surface text-slate-900 placeholder-slate-500 focus:ring-2 focus:ring-blue-500 focus:outline-none"
                    />
                    <button
                      type="button"
                      onClick={() => setShowPassword(!showPassword)}
                      className="absolute right-3 top-1/2 transform -translate-y-1/2 text-slate-600 hover:text-blue-700 focus:outline-none"
                    >
                      {showPassword ? (
                        <span>🔓</span>
                      ) : (
                        <span>🔒</span> //
                      )}
                    </button>
                  </div>
                  {canTerminateSession && (
                    <div className="p-4 bg-amber-950/80 border border-amber-500/70 rounded-lg text-amber-200 text-sm flex flex-col gap-3">
                      <div>
                        <p className="font-bold text-amber-300 flex items-center gap-1.5">
                          <span>⚠️</span> Active Session Detected
                        </p>
                        <p className="mt-1 text-xs text-amber-100/90 leading-relaxed">
                          This administrator account is active in another tab or device (e.g., closed incognito window). As an admin, you can terminate that session and log in now.
                        </p>
                      </div>
                      <button
                        type="button"
                        onClick={handleTerminateAndLogin}
                        className="w-full py-2.5 px-4 bg-amber-600 hover:bg-amber-500 text-slate-900 font-semibold rounded-md shadow transition duration-150 active:scale-98"
                      >
                        Terminate Active Session &amp; Log In
                      </button>
                    </div>
                  )}
                </>
              )}
              <button
                type="submit"
                className="w-full py-4 bg-blue-600 text-slate-900 font-bold rounded-md transition-transform transform hover:scale-105 focus:scale-95"
              >
                {isLoading ? "Loading..." : isLogin ? "Login" : "Signup"}
              </button>
              <p className="text-slate-900 text-center">
                {isLogin ? "New to Coding App?" : "Already have an account?"}
                <button
                  type="button"
                  onClick={toggleLogin}
                  className="ml-2 text-blue-700 cursor-pointer hover:underline"
                >
                  {isLogin ? "Signup" : "Login"}
                </button>
              </p>
            </form>
          )}
        </div>
      </div>
    </>
  );
};

export default Login;

import React, { useState } from "react";
import axiosInstance from "../utils/axiosInstance";
import { useNavigate } from "react-router-dom";
import toast from "react-hot-toast";

const PasswordChange = ({ id }) => {
  const [oldPassword, setOldPassword] = useState("");
  const [newPassword, setNewPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [showOldPassword, setShowOldPassword] = useState(false);
  const [showNewPassword, setShowNewPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);
  const [error, setError] = useState("");
  const [isLoading, setIsLoading] = useState(false);
  const navigate = useNavigate();

  const handleSubmit = async (e) => {
    e.preventDefault();
    setIsLoading(true);
    setError("");

    if (!oldPassword || !newPassword || !confirmPassword) {
      setError("All fields are required.");
      setIsLoading(false);
      return;
    }

    if (newPassword.length < 8) {
      setError("New Password must be at least 8 characters long.");
      setIsLoading(false);
      return;
    }

    if (newPassword !== confirmPassword) {
      setError("New Password and Confirm Password do not match!");
      setIsLoading(false);
      return;
    }

    try {
      const user = { id, oldPassword, newPassword };
      const url = "auth/change-password";
      const res = await axiosInstance.post(url, user);

      if (res.status === 200) {
        setOldPassword("");
        setNewPassword("");
        setConfirmPassword("");
        toast.success("Password changed successfully! Please log in with your new password.");
        setTimeout(() => {
          window.location.href = "/";
        }, 1200);
      } else {
        setError(
          res.data.message || "An error occurred while changing the password."
        );
      }
    } catch (error) {
      setError(
        error.response?.data?.message ||
          "An error occurred while processing your request."
      );
      console.error(error);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <form
      onSubmit={handleSubmit}
      className="flex flex-col w-full max-w-lg p-8 space-y-6 ui-page bg-opacity-90 rounded-lg ui-card-shadow"
    >
      <h2 className="text-2xl font-bold text-center text-slate-900 mb-6">
        Change Password
      </h2>

      {error && (
        <div className="mb-4 text-red-500 bg-red-100 p-3 rounded-lg">
          {error}
        </div>
      )}

      <div className="mb-4 relative">
        <input
          type={showOldPassword ? "text" : "password"}
          id="oldPassword"
          value={oldPassword}
          onChange={(e) => setOldPassword(e.target.value)}
          className="p-4 rounded-md ui-surface text-slate-900 placeholder-slate-500 focus:ring-2 focus:ring-blue-500 focus:outline-none w-full"
          placeholder="Enter old password"
        />
        <button
          type="button"
          onClick={() => setShowOldPassword(!showOldPassword)}
          className="absolute right-3 top-1/2 transform -translate-y-1/2 text-slate-600 hover:text-blue-700 focus:outline-none"
        >
          {showOldPassword ? "🔓" : "🔒"}
        </button>
      </div>

      <div className="mb-4 relative">
        <input
          type={showNewPassword ? "text" : "password"}
          id="newPassword"
          value={newPassword}
          onChange={(e) => setNewPassword(e.target.value)}
          className="p-4 rounded-md ui-surface text-slate-900 placeholder-slate-500 focus:ring-2 focus:ring-blue-500 focus:outline-none w-full"
          placeholder="Enter new password"
        />
        <button
          type="button"
          onClick={() => setShowNewPassword(!showNewPassword)}
          className="absolute right-3 top-1/2 transform -translate-y-1/2 text-slate-600 hover:text-blue-700 focus:outline-none"
        >
          {showNewPassword ? "🔓" : "🔒"}
        </button>
      </div>

      <div className="mb-6 relative">
        <input
          type={showConfirmPassword ? "text" : "password"}
          id="confirmPassword"
          value={confirmPassword}
          onChange={(e) => setConfirmPassword(e.target.value)}
          className="p-4 rounded-md ui-surface text-slate-900 placeholder-slate-500 focus:ring-2 focus:ring-blue-500 focus:outline-none w-full"
          placeholder="Confirm new password"
        />
        <button
          type="button"
          onClick={() => setShowConfirmPassword(!showConfirmPassword)}
          className="absolute right-3 top-1/2 transform -translate-y-1/2 text-slate-600 hover:text-blue-700 focus:outline-none"
        >
          {showConfirmPassword ? "🔓" : "🔒"}
        </button>
      </div>

      <button
        type="submit"
        className="w-full py-4 bg-blue-600 text-slate-900 font-bold rounded-md transition-transform transform hover:scale-105 focus:scale-95"
      >
        {isLoading ? "Changing password..." : "Change Password"}
      </button>
    </form>
  );
};

export default PasswordChange;

import React, { useState } from "react";
import toast from "react-hot-toast";
import {
  Sparkles,
  Wand2,
  FileCode,
  CheckCircle2,
  AlertCircle,
  X,
  Loader2,
  RefreshCw,
  Eye,
  EyeOff,
} from "lucide-react";
import axiosInstance from "../../utils/axiosInstance";

const QUICK_TOPICS = [
  "Array",
  "String",
  "Binary Search",
  "Two Pointers",
  "Stack & Queue",
  "Linked List",
  "Recursion",
  "Dynamic Programming",
  "Trees & Graphs",
  "Hash Map",
];

const AIProblemModal = ({ isOpen, onClose, onApplyProblem }) => {
  const [activeTab, setActiveTab] = useState("generate"); // 'generate' | 'convert'
  const [topic, setTopic] = useState("Array");
  const [difficulty, setDifficulty] = useState("easy");
  const [customPrompt, setCustomPrompt] = useState("");
  const [rawText, setRawText] = useState("");

  const [loading, setLoading] = useState(false);
  const [generatedProblem, setGeneratedProblem] = useState(null);
  const [errorMsg, setErrorMsg] = useState("");

  if (!isOpen) return null;

  const handleGenerate = async () => {
    setErrorMsg("");
    setGeneratedProblem(null);

    if (activeTab === "generate" && !topic.trim()) {
      toast.error("Please enter or select a topic.");
      return;
    }
    if (activeTab === "convert" && !rawText.trim()) {
      toast.error("Please paste the problem content to convert.");
      return;
    }

    setLoading(true);

    try {
      const payload =
        activeTab === "generate"
          ? {
              mode: "generate",
              topic: topic.trim(),
              difficulty,
              prompt: customPrompt.trim(),
            }
          : {
              mode: "convert",
              rawText: rawText.trim(),
              difficulty,
            };

      const response = await axiosInstance.post("/problems/ai-generate/", payload);

      if (response.data && response.data.success) {
        setGeneratedProblem(response.data.data);
        toast.success("Problem generated successfully!");
      } else {
        const msg = response.data?.message || "Failed to generate problem.";
        setErrorMsg(msg);
        toast.error(msg);
      }
    } catch (err) {
      console.error("AI Generation error:", err);
      const msg =
        err.response?.data?.message ||
        "Failed to communicate with AI service. Please check your GEMINI_API_KEY configuration.";
      setErrorMsg(msg);
      toast.error(msg);
    } finally {
      setLoading(false);
    }
  };

  const handleApply = () => {
    if (!generatedProblem) return;
    onApplyProblem(generatedProblem);
    toast.success("AI generated problem applied to form!");
    onClose();
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm overflow-y-auto">
      <div className="relative w-full max-w-4xl ui-page border border-slate-200 rounded-lg ui-card-shadow overflow-hidden my-8 max-h-[90vh] flex flex-col">
        {/* Header */}
        <div className="flex items-center justify-between px-6 py-4 border-b border-slate-200 ui-gradient   ">
          <div className="flex items-center gap-3">
            <div className="p-2 bg-indigo-500/20 text-blue-700 rounded-lg border border-indigo-500/30">
              <Sparkles className="w-6 h-6 animate-pulse text-blue-700" />
            </div>
            <div>
              <h2 className="text-xl font-bold text-slate-900 flex items-center gap-2">
                AI Problem Assistant
                <span className="text-xs font-semibold px-2 py-0.5 rounded-full bg-indigo-500/20 text-blue-700 border border-indigo-500/40">
                  Gemini Powered
                </span>
              </h2>
              <p className="text-xs text-slate-600">
                Draft new problems or convert LeetCode/HackerRank questions in seconds.
              </p>
            </div>
          </div>
          <button
            onClick={onClose}
            className="p-1.5 text-slate-600 hover:text-slate-900 rounded-lg hover:ui-surface transition"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Tab Selection */}
        <div className="flex border-b border-slate-200 ui-page px-6">
          <button
            onClick={() => {
              setActiveTab("generate");
              setErrorMsg("");
            }}
            className={`flex items-center gap-2 py-3 px-4 font-medium text-sm border-b-2 transition ${
              activeTab === "generate"
                ? "border-indigo-500 text-blue-700 bg-indigo-500/10"
                : "border-transparent text-slate-600 hover:text-slate-900"
            }`}
          >
            <Wand2 className="w-4 h-4" />
            Generate from Scratch
          </button>
          <button
            onClick={() => {
              setActiveTab("convert");
              setErrorMsg("");
            }}
            className={`flex items-center gap-2 py-3 px-4 font-medium text-sm border-b-2 transition ${
              activeTab === "convert"
                ? "border-indigo-500 text-blue-700 bg-indigo-500/10"
                : "border-transparent text-slate-600 hover:text-slate-900"
            }`}
          >
            <FileCode className="w-4 h-4" />
            Import from LeetCode / Text
          </button>
        </div>

        {/* Modal Body */}
        <div className="p-6 overflow-y-auto space-y-6 flex-1 text-slate-900">
          {/* Difficulty Selector (Shared) */}
          <div>
            <label className="block text-xs font-semibold uppercase tracking-wider text-slate-600 mb-2">
              Difficulty Level
            </label>
            <div className="flex gap-3">
              {[
                { id: "easy", label: "Easy", color: "border-green-500/50 text-green-700 bg-green-500/10" },
                { id: "medium", label: "Medium", color: "border-yellow-500/50 text-yellow-700 bg-yellow-500/10" },
                { id: "hard", label: "Hard", color: "border-red-500/50 text-red-700 bg-red-500/10" },
              ].map((diff) => (
                <button
                  key={diff.id}
                  type="button"
                  onClick={() => setDifficulty(diff.id)}
                  className={`flex-1 py-2 px-3 rounded-lg border text-sm font-medium transition ${
                    difficulty === diff.id
                      ? `${diff.color} ring-1 ring-offset-0 ring-white/20 font-bold shadow`
                      : "border-slate-200 ui-page text-slate-600 hover:border-slate-200"
                  }`}
                >
                  {diff.label}
                </button>
              ))}
            </div>
          </div>

          {activeTab === "generate" ? (
            <>
              {/* Topic Input & Quick Suggestions */}
              <div>
                <label className="block text-xs font-semibold uppercase tracking-wider text-slate-600 mb-2">
                  Topic / Category
                </label>
                <input
                  type="text"
                  placeholder="e.g. Array, Dynamic Programming, Two Pointers..."
                  value={topic}
                  onChange={(e) => setTopic(e.target.value)}
                  className="w-full px-4 py-2.5 ui-surface border border-slate-200 rounded-lg text-slate-900 placeholder-slate-500 focus:outline-none focus:ring-2 focus:ring-indigo-500"
                />

                <div className="flex flex-wrap gap-1.5 mt-2">
                  <span className="text-xs text-slate-600 self-center mr-1">Quick pick:</span>
                  {QUICK_TOPICS.map((t) => (
                    <button
                      key={t}
                      type="button"
                      onClick={() => setTopic(t)}
                      className={`text-xs px-2 py-0.5 rounded-md border transition ${
                        topic.toLowerCase() === t.toLowerCase()
                          ? "bg-indigo-600 text-slate-900 border-indigo-500"
                          : "ui-surface text-slate-600 border-slate-200 hover:ui-surface hover:text-slate-900"
                      }`}
                    >
                      {t}
                    </button>
                  ))}
                </div>
              </div>

              {/* Custom Guidance Prompt */}
              <div>
                <label className="block text-xs font-semibold uppercase tracking-wider text-slate-600 mb-2">
                  Additional Guidance / Instructions (Optional)
                </label>
                <textarea
                  rows="3"
                  placeholder="e.g. Focus on prefix sums, include a test case with all negative numbers, story about a library..."
                  value={customPrompt}
                  onChange={(e) => setCustomPrompt(e.target.value)}
                  className="w-full px-4 py-2.5 ui-surface border border-slate-200 rounded-lg text-slate-900 placeholder-slate-500 focus:outline-none focus:ring-2 focus:ring-indigo-500 text-sm"
                />
              </div>
            </>
          ) : (
            <>
              {/* LeetCode / Raw Text Paste */}
              <div>
                <label className="block text-xs font-semibold uppercase tracking-wider text-slate-600 mb-2">
                  Paste Problem Statement & Examples
                </label>
                <textarea
                  rows="7"
                  placeholder="Paste problem copied from LeetCode, HackerRank, GeeksforGeeks, or PDF assignment..."
                  value={rawText}
                  onChange={(e) => setRawText(e.target.value)}
                  className="w-full px-4 py-3 ui-surface border border-slate-200 rounded-lg text-slate-900 placeholder-slate-500 focus:outline-none focus:ring-2 focus:ring-indigo-500 font-mono text-sm"
                />
                <p className="text-xs text-slate-600 mt-1">
                  💡 The AI will parse the title, description, constraints, and format test cases automatically.
                </p>
              </div>
            </>
          )}

          {/* Error Banner */}
          {errorMsg && (
            <div className="flex items-start gap-3 p-3 bg-red-50 border border-red-800/80 rounded-lg text-red-700 text-sm">
              <AlertCircle className="w-5 h-5 flex-shrink-0 mt-0.5 text-red-700" />
              <div>
                <p className="font-semibold">Generation Failed</p>
                <p className="text-xs text-red-700/90 mt-0.5">{errorMsg}</p>
              </div>
            </div>
          )}

          {/* Trigger Generate Button */}
          <div className="flex justify-end pt-2">
            <button
              type="button"
              disabled={loading}
              onClick={handleGenerate}
              className="flex items-center gap-2 px-6 py-2.5 ui-gradient     text-slate-900 font-medium rounded-lg ui-card-shadow shadow-indigo-600/30 transition disabled:opacity-50 disabled:cursor-not-allowed cursor-pointer"
            >
              {loading ? (
                <>
                  <Loader2 className="w-4 h-4 animate-spin" />
                  Generating Problem with AI...
                </>
              ) : (
                <>
                  <Sparkles className="w-4 h-4" />
                  {generatedProblem ? "Regenerate Problem" : "Generate with AI"}
                </>
              )}
            </button>
          </div>

          {/* Generated Result Preview */}
          {generatedProblem && (
            <div className="mt-6 p-5 ui-page border border-indigo-500/30 rounded-lg space-y-4">
              <div className="flex items-start justify-between">
                <div>
                  <span className="text-xs font-semibold px-2 py-0.5 rounded bg-indigo-500/20 text-blue-700 border border-indigo-500/30">
                    Preview Generated Problem
                  </span>
                  <h3 className="text-lg font-bold text-slate-900 mt-1.5 flex items-center gap-2">
                    {generatedProblem.title}
                    <span
                      className={`text-xs px-2 py-0.5 rounded-full capitalize font-semibold ${
                        generatedProblem.difficulty === "easy"
                          ? "bg-green-50 text-green-700 border border-green-800"
                          : generatedProblem.difficulty === "medium"
                          ? "bg-yellow-50 text-yellow-700 border border-yellow-800"
                          : "bg-red-50 text-red-700 border border-red-800"
                      }`}
                    >
                      {generatedProblem.difficulty}
                    </span>
                  </h3>
                </div>

                <button
                  type="button"
                  onClick={handleApply}
                  className="flex items-center gap-2 px-4 py-2 bg-green-600 hover:bg-green-500 text-slate-900 text-sm font-semibold rounded-lg shadow-md shadow-green-600/20 transition cursor-pointer"
                >
                  <CheckCircle2 className="w-4 h-4" />
                  Apply to Form
                </button>
              </div>

              {/* Description preview */}
              <div>
                <span className="text-xs font-semibold text-slate-600">Description:</span>
                <p className="text-xs text-slate-600 mt-1 line-clamp-3 ui-page p-2.5 rounded border border-slate-200">
                  {generatedProblem.description}
                </p>
              </div>

              {/* Tags */}
              {generatedProblem.tags && generatedProblem.tags.length > 0 && (
                <div className="flex items-center gap-2 flex-wrap">
                  <span className="text-xs text-slate-600">Tags:</span>
                  {generatedProblem.tags.map((tag, i) => (
                    <span
                      key={i}
                      className="text-xs ui-surface text-slate-600 px-2 py-0.5 rounded border border-slate-200"
                    >
                      #{tag}
                    </span>
                  ))}
                </div>
              )}

              {/* Test cases breakdown */}
              <div className="grid grid-cols-1 sm:grid-cols-3 gap-3 pt-2 border-t border-slate-200">
                <div className="p-2.5 ui-page rounded-lg border border-slate-200 text-center">
                  <p className="text-xs text-slate-600">Sample I/O</p>
                  <p className="text-base font-bold text-slate-900 mt-0.5">
                    {generatedProblem.sampleIO?.length || 0} pairs
                  </p>
                </div>
                <div className="p-2.5 ui-page rounded-lg border border-slate-200 text-center">
                  <p className="text-xs text-slate-600 flex items-center justify-center gap-1">
                    <Eye className="w-3.5 h-3.5 text-blue-700" /> Visible Test Cases
                  </p>
                  <p className="text-base font-bold text-slate-900 mt-0.5">
                    {generatedProblem.testCases?.filter((tc) => !tc.is_hidden).length || 0}
                  </p>
                </div>
                <div className="p-2.5 ui-page rounded-lg border border-slate-200 text-center">
                  <p className="text-xs text-slate-600 flex items-center justify-center gap-1">
                    <EyeOff className="w-3.5 h-3.5 text-red-700" /> Hidden Test Cases
                  </p>
                  <p className="text-base font-bold text-slate-900 mt-0.5">
                    {generatedProblem.testCases?.filter((tc) => tc.is_hidden).length || 0}
                  </p>
                </div>
              </div>

              {/* Bottom apply action */}
              <div className="pt-2 flex justify-end">
                <button
                  type="button"
                  onClick={handleApply}
                  className="w-full sm:w-auto flex items-center justify-center gap-2 px-6 py-2.5 ui-gradient     text-slate-900 font-semibold rounded-lg ui-card-shadow shadow-green-600/30 transition cursor-pointer"
                >
                  <CheckCircle2 className="w-4 h-4" />
                  Apply Problem & Fill Form
                </button>
              </div>
            </div>
          )}
        </div>

        {/* Footer */}
        <div className="px-6 py-3 border-t border-slate-200 ui-page flex items-center justify-between text-xs text-slate-600">
          <span>You can always review and edit all fields after applying.</span>
          <button
            onClick={onClose}
            className="px-3 py-1 ui-surface hover:ui-surface text-slate-600 rounded transition"
          >
            Close
          </button>
        </div>
      </div>
    </div>
  );
};

export default AIProblemModal;

import React, { useState, useEffect } from "react";
import { useNavigate, useParams } from "react-router-dom";
import axiosInstance from "../../utils/axiosInstance";
import toast from "react-hot-toast";
import StudentTable from "./StudentTable";

const AssignProblem = () => {
  const { problemId } = useParams();
  const navigate = useNavigate();
  const [loading, setLoading] = useState(true);
  const [assignLoading, setAssignLoading] = useState(false); // For button-specific loading
  const [unassignedStudents, setUnassignedStudents] = useState([]);
  const [selectedStudents, setSelectedStudents] = useState([]);
  const [filters, setFilters] = useState({
    branch: "cspit-it",
    semester: "6",
    batch: "a1",
  });
  const [error, setError] = useState("");
  const [currentPage, setCurrentPage] = useState(1);
  const studentsPerPage = 12;

  useEffect(() => {
    const fetchUnassignedStudents = async () => {
      setLoading(true);
      try {
        const response = await axiosInstance.get(
          `/problems/${problemId}/unassignStudent`,
          {
            params: {
              branch: filters.branch,
              semester: filters.semester,
              batch: filters.batch,
            },
          }
        );
        setUnassignedStudents(response.data.unassignedStudents);
      } catch (err) {
        toast.error("Failed to fetch unassigned students. Please try again.");
        setError("Failed to fetch unassigned students");
      } finally {
        setLoading(false);
      }
    };

    fetchUnassignedStudents();
  }, [problemId, filters]);

  const updateFilter = (key, value) => {
    setFilters((prev) => ({ ...prev, [key]: value }));
    setCurrentPage(1);
  };

  const handleSelectAll = () => {
    if (selectedStudents.length === unassignedStudents.length) {
      setSelectedStudents([]);
    } else {
      setSelectedStudents(unassignedStudents.map((student) => student._id));
    }
  };

  const handleSelectStudent = (id) => {
    if (selectedStudents.includes(id)) {
      setSelectedStudents(
        selectedStudents.filter((studentId) => studentId !== id)
      );
    } else {
      setSelectedStudents([...selectedStudents, id]);
    }
  };

  const handleAssign = async () => {
    setAssignLoading(true);
    try {
      const res = await axiosInstance.post(`/problems/${problemId}/assign`, {
        studentIds: selectedStudents,
      });
      setUnassignedStudents(
        unassignedStudents.filter(
          (student) => !selectedStudents.includes(student._id)
        )
      );
      toast.success(res.data.message);
      setSelectedStudents([]);
      setError(null);
    } catch (error) {
      toast.error("Failed to assign students. Please try again.");
      setError("Failed to assign students. Please try again.");
    } finally {
      setAssignLoading(false);
    }
  };

  const totalPages = Math.ceil(unassignedStudents.length / studentsPerPage);

  const handlePageChange = (pageNumber) => {
    setCurrentPage(pageNumber);
  };

  return (
    <div className="relative ui-page-height ui-page text-slate-900">
      <h1 className="text-2xl font-bold mb-4 ui-page-top justify-center flex items-center">
        List of Students unAssigned to the Problem
      </h1>

      {error && <p className="text-red-500 mb-4">{error}</p>}

      {assignLoading && (
        <div className="fixed inset-0 bg-black bg-opacity-70 flex items-center justify-center z-50">
          <div className="flex flex-col items-center">
            <svg
              className="animate-spin h-12 w-12 text-blue-700 mb-4"
              xmlns="http://www.w3.org/2000/svg"
              fill="none"
              viewBox="0 0 24 24"
            >
              <circle
                className="opacity-25"
                cx="12"
                cy="12"
                r="10"
                stroke="currentColor"
                strokeWidth="4"
              ></circle>
              <path
                className="opacity-75"
                fill="currentColor"
                d="M4 12a8 8 0 018-8v8H4z"
              ></path>
            </svg>
            <p className="text-slate-900 text-lg font-semibold">Assigning...</p>
          </div>
        </div>
      )}

      <button
        className="py-2 px-6 ml-6 ui-gradient mb-4   text-slate-900 font-semibold rounded-lg shadow-md   active:scale-95 transition transform duration-200"
        onClick={() => navigate(`/assignedStudents/${problemId}`)}
      >
        View Assigned Students
      </button>

      <div className="px-4 mb-4">
        <p className="text-xl font-medium">
          Unassigned Students: {unassignedStudents.length}
        </p>
      </div>

      <StudentTable
        users={unassignedStudents}
        selectedStudents={selectedStudents}
        handleSelectStudent={handleSelectStudent}
        handleSelectAll={handleSelectAll}
        filters={filters}
        updateFilter={updateFilter}
        loading={loading}
        currentPage={currentPage}
        itemsPerPage={studentsPerPage}
        handlePageChange={handlePageChange}
        totalPages={totalPages}
      />

      <div className="flex justify-start ml-4 p-4">
        <button
          onClick={handleAssign}
          disabled={selectedStudents.length === 0}
          className="bg-green-500 text-slate-900 px-4 py-2 rounded hover:bg-green-600 disabled:ui-subtle"
        >
          Assign Problem
        </button>
      </div>
    </div>
  );
};

