  const [error, setError] = useState("");
  const [currentPage, setCurrentPage] = useState(1);
  const studentsPerPage = 12;

  useEffect(() => {
    const fetchStudents = async () => {
      setLoading(true);
      try {
        const response = await axiosInstance.get(
          `/problems/${problemId}/students`
        );
        setStudents(response.data.assignedStudents || []);
        setTotalAssigned(response.data.assignedStudents.length);
      } catch (err) {
        setError("Failed to load students");
      } finally {
        setLoading(false);
      }
    };

    fetchStudents();
  }, [problemId]);

  const updateFilter = (key, value) => {
    setFilters((prev) => ({ ...prev, [key]: value }));
    setCurrentPage(1); // Reset to the first page when filters change
  };

  const handleSelectAll = () => {
    if (selectedStudents.length === students.length) {
      setSelectedStudents([]);
    } else {
      setSelectedStudents(students.map((student) => student._id));
    }
  };

  const handleSelectStudent = (id) => {
    if (selectedStudents.includes(id)) {
      setSelectedStudents(
        selectedStudents.filter((studentId) => studentId !== id)
      );
    } else {
      setSelectedStudents([...selectedStudents, id]);
    }
  };

  const handleUnassign = async () => {
    setAssignLoading(true);
    try {
      const res = await axiosInstance.post(`/problems/${problemId}/unassign-students`, {
        studentIds: selectedStudents,
      });
      setStudents(
        students.filter((student) => !selectedStudents.includes(student._id))
      );
      toast.success(res.data.message);
      setSelectedStudents([]);
      setError(null);
    } catch (error) {
      toast.error("Failed to unassign students. Please try again.");
      setError("Failed to unassign students. Please try again.");
    } finally {
      setAssignLoading(false); // Stop loading
    }
  };

  const totalPages = Math.ceil(students.length / studentsPerPage);

  const handlePageChange = (pageNumber) => {
    setCurrentPage(pageNumber);
  };

  return (
    <div className="relative ui-page-height ui-page text-slate-900">
      <h1 className="text-2xl font-bold mb-4 ui-page-top justify-center flex items-center">
