import React, { useEffect, useState } from "react";
import { useParams, useLocation, useNavigate } from "react-router-dom";
import axiosInstance from "../../utils/axiosInstance";
import * as XLSX from "xlsx";
import jsPDF from "jspdf";
import "jspdf-autotable";

const Dashboard = () => {
  const { problemId } = useParams();
  const location = useLocation();
  const navigate = useNavigate();
  const [submissions, setSubmissions] = useState([]);
  const [filteredSubmissions, setFilteredSubmissions] = useState([]);
  const [selectedSubmission, setSelectedSubmission] = useState(null);
  const [TotalSubmission, setTotalSubmission] = useState(0);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [sortField, setSortField] = useState(null);
  const [sortOrder, setSortOrder] = useState("asc");

  const [filters, setFilters] = useState({
    branch: "ALL",
    semester: "ALL",
    language: "ALL",
    status: "ALL",
    batch: "ALL",
  });

  const { problemTitle, difficulty, createdAt } = location.state || {};

  useEffect(() => {
    const fetchSubmissions = async () => {
      try {
        const response = await axiosInstance.get("/submissions/problem", {
          params: { problem_id: problemId },
        });
        setSubmissions(response.data.submissions);
        setTotalSubmission(response.data.submissions.length);
        setFilteredSubmissions(response.data.submissions);
        // console.log(response.data);
      } catch (err) {
        setError(
          err.response ? err.response.data.message : "Error fetching data"
        );
      } finally {
        setLoading(false);
      }
    };

    fetchSubmissions();
  }, [problemId]);

  useEffect(() => {
    applyFilters();
  }, [filters]);

  const handleSort = (field) => {
    const order = sortField === field && sortOrder === "asc" ? "desc" : "asc";
    setSortField(field);
    setSortOrder(order);

    const sortedData = [...filteredSubmissions].sort((a, b) => {
      const valA =
        field === "branch" || field === "batch"
          ? a.user_id[field]?.toUpperCase()
          : a.user_id[field];
      const valB =
        field === "branch" || field === "batch"
          ? b.user_id[field]?.toUpperCase()
          : b.user_id[field];

      if (order === "asc") {
        return valA > valB ? 1 : valA < valB ? -1 : 0;
      } else {
        return valA < valB ? 1 : valA > valB ? -1 : 0;
      }
    });

    setFilteredSubmissions(sortedData);
  };

  const applyFilters = () => {
    let filtered = submissions;

    if (filters.branch !== "ALL") {
      filtered = filtered.filter(
        (submission) =>
          submission.user_id.branch?.toUpperCase() === filters.branch
      );
    }

    if (filters.semester !== "ALL") {
      filtered = filtered.filter((submission) => {
        const semester = submission.user_id.semester; // Extract semester
        return semester && String(semester) === String(filters.semester);
      });
    }

    if (filters.language !== "ALL") {
      filtered = filtered.filter(
        (submission) => submission.language?.toUpperCase() === filters.language
      );
    }

    if (filters.status !== "ALL") {
      filtered = filtered.filter(
        (submission) => submission.status?.toUpperCase() === filters.status
      );
    }
    if (filters.batch !== "ALL") {
      // console.log(filters.batch);
      filtered = filtered.filter((submission) => {
        return submission.user_id.batch?.toUpperCase() === filters.batch;
      });
    }

    setFilteredSubmissions(filtered);
  };

  const updateFilter = (key, value) => {
    setFilters((prev) => ({ ...prev, [key]: value }));
  };

  const formatDate = (dateString) => {
    const date = new Date(dateString);
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, "0");
    const day = String(date.getDate()).padStart(2, "0");
    const hours = String(date.getHours()).padStart(2, "0");
    const minutes = String(date.getMinutes()).padStart(2, "0");
    return `${day}-${month}-${year} ${hours}:${minutes}`;
  };

  const downloadExcel = () => {
    const totalSubmissions = filteredSubmissions.length;

    // Add a header row for the total number of submissions
    const headerRow = [
      { ID: `Total Submissions: ${totalSubmissions}` },
      {}, // Blank cells to adjust layout
    ];

    const dataToExport = filteredSubmissions.map((submission) => ({
      ID: submission.user_id.id,
      Username: submission.user_id.username,
      Branch: submission.user_id.branch?.toUpperCase() || "N/A",
      Batch: submission.user_id.batch?.toUpperCase() || "N/A",
      Semester: submission.user_id.semester || "N/A",
      "Test Cases Passed": `${submission.numberOfTestCasePass || 0}/${
        submission.numberOfTestCase || 0
      }`,
      "Submission Date": formatDate(submission.createdAt),
      Marks: submission.totalMarks ?? "N/A",
    }));

    const worksheet = XLSX.utils.json_to_sheet([]);
    XLSX.utils.sheet_add_aoa(worksheet, [
      [`Total Submissions: ${totalSubmissions}`],
    ]);
    XLSX.utils.sheet_add_json(worksheet, dataToExport, { origin: "A3" });

    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, "Submissions");

    XLSX.writeFile(workbook, "Submissions.xlsx");
  };

  const downloadPDF = () => {
    const totalSubmissions = filteredSubmissions.length;

    const doc = new jsPDF();
    const tableColumnHeaders = [
      "ID",
      "Username",
      "Branch",
      "Batch",
      "Semester",
      "Test Cases Passed",
      "Submission Date",
      "Marks",
    ];
    const tableRows = filteredSubmissions.map((submission) => [
      submission.user_id.id,
      submission.user_id.username,
      submission.user_id.branch?.toUpperCase() || "N/A",
      submission.user_id.batch?.toUpperCase() || "N/A",
      submission.user_id.semester || "N/A",
      `${submission.numberOfTestCasePass || 0}/${
        submission.numberOfTestCase || 0
      }`,
      formatDate(submission.createdAt),
      submission.totalMarks ?? "N/A",
    ]);

    // Add a title and the total submissions
    doc.text("Submissions Report", 14, 15);
    doc.text(`Total Submissions: ${totalSubmissions}`, 14, 25);

    // Generate the table
    doc.autoTable({
      head: [tableColumnHeaders],
      body: tableRows,
      startY: 30,
    });

    doc.save("Submissions.pdf");
  };

  return (
    <>
      <div className="relative ui-page-height ui-page text-slate-900">
        <div className="mx-auto px-5 ui-page-top pb-5">
          {problemTitle && (
            <div className="mb-6 ui-surface p-6 rounded-lg ui-card-shadow border-l-4 border-blue-500">
              <h3 className="text-2xl sm:text-3xl font-bold text-blue-700 mb-4">
                {problemTitle}
              </h3>
              <div className="flex flex-col sm:flex-row sm:justify-between text-base sm:text-lg">
                <p className="font-semibold text-slate-600 mb-2 sm:mb-0">
                  Difficulty:{" "}
                  <span className="text-blue-700">{difficulty}</span>
                </p>
                <p className="font-semibold text-slate-600">
                  Created on:{" "}
                  <span className="text-slate-600">{formatDate(createdAt)}</span>
                </p>
              </div>
            </div>
          )}

          <div className="mb-4 font-medium text-xl  text-slate-600">
            Total Number of Submissions :{" "}
            {TotalSubmission ? TotalSubmission : "0"}
          </div>

          {/* Filters */}
          <div className="mb-6 flex flex-col gap-4 sm:flex-row sm:justify-between items-center">
            {/* Filters Section */}
            <div className="flex flex-wrap gap-4 justify-center sm:justify-start">
              <select
                value={filters.branch}
                onChange={(e) => updateFilter("branch", e.target.value)}
                className="ui-surface text-slate-900 px-4 py-2 rounded focus:outline-none focus:ring-2 focus:ring-blue-500"
              >
                <option value="ALL">All Branches</option>
                <option value="CSPIT-IT">CSPIT-IT</option>
                <option value="CSPIT-CSE">CSPIT-CSE</option>
                <option value="CSPIT-CE">CSPIT-CE</option>
              </select>
              <select
                value={filters.semester}
                onChange={(e) => updateFilter("semester", e.target.value)}
                className="ui-surface text-slate-900 px-4 py-2 rounded focus:outline-none focus:ring-2 focus:ring-blue-500"
              >
                <option value="ALL">All Semesters</option>
                {[...Array(8)].map((_, i) => (
                  <option key={i + 1} value={i + 1}>
                    Semester {i + 1}
                  </option>
                ))}
              </select>
              {/* <select
                value={filters.language}
                onChange={(e) => updateFilter("language", e.target.value)}
                className="ui-surface text-slate-900 px-4 py-2 rounded focus:outline-none focus:ring-2 focus:ring-blue-500"
              >
                <option value="ALL">All Languages</option>
                <option value="CPP">C++</option>
                <option value="PYTHON">Python</option>
                <option value="JAVA">Java</option>
              </select> */}
              {/* <select
                value={filters.status}
                onChange={(e) => updateFilter("status", e.target.value)}
                className="ui-surface text-slate-900 px-4 py-2 rounded focus:outline-none focus:ring-2 focus:ring-blue-500"
              >
                <option value="ALL">All Statuses</option>
                <option value="COMPLETED">Completed</option>
                <option value="REJECTED">Rejected</option>
              </select> */}

              <select
                value={filters.batch}
                onChange={(e) => updateFilter("batch", e.target.value)}
                className="ui-surface text-slate-900 px-4 py-2 rounded focus:outline-none focus:ring-2 focus:ring-blue-500"
              >
                <option value="ALL">All Batches</option>
                {["A", "B", "C", "D"].map((letter) =>
                  [1, 2].map((num) => (
                    <option key={`${letter}${num}`} value={`${letter}${num}`}>
                      {`${letter}${num}`}
                    </option>
                  ))
                )}
              </select>
            </div>

            {/* Back Button Section */}
            <div>
              <button
                onClick={() => navigate(-1)}
                className="flex items-center ui-surface hover:ui-subtle text-slate-900 px-4 py-2 rounded-full shadow-md hover:ui-card-shadow transition-all duration-200 ease-in-out"
              >
                <svg
                  className="w-4 h-4 mr-2"
                  focusable="false"
                  viewBox="0 0 24 24"
                  aria-hidden="true"
                  fill="white"
                >
                  <path d="M20 11H7.83l5.59-5.59L12 4l-8 8 8 8 1.41-1.41L7.83 13H20v-2z"></path>
                </svg>
                Back
              </button>
            </div>
          </div>

          <div className="flex justify-end gap-4 mb-4">
            <button
              onClick={downloadExcel}
              className="bg-green-600 hover:bg-green-500 text-slate-900 px-4 py-2 rounded shadow transition-all duration-200"
            >
              Download Excel
            </button>
            <button
              onClick={downloadPDF}
              className="bg-blue-600 hover:bg-blue-500 text-slate-900 px-4 py-2 rounded shadow transition-all duration-200"
            >
              Download PDF
            </button>
          </div>

          {/* Submissions Table */}
          <div className="overflow-x-auto">
            <div className="mb-4 font-medium text-xl text-slate-600">
              Total After Filter of Submissions:{" "}
              {filteredSubmissions.length > 0
                ? filteredSubmissions.length
                : "0"}
            </div>

            <table className="w-full min-w-max text-sm text-left text-slate-600 border-collapse border border-slate-200">
              <thead className="ui-surface text-slate-600">
                <tr>
                  <th
                    className="py-3 px-6 border border-slate-200 text-sm md:text-base cursor-pointer"
                    onClick={() => handleSort("id")}
                  >
                    ID
                  </th>
                  <th
                    className="py-3 px-6 border border-slate-200 text-sm md:text-base cursor-pointer"
                    onClick={() => handleSort("username")}
                  >
                    User Name
                  </th>
                  <th className="py-3 px-6 border border-slate-200 text-sm md:text-base">
                    Branch
                  </th>
                  <th
                    className="py-3 px-6 border border-slate-200 text-sm md:text-base cursor-pointer"
                    onClick={() => handleSort("batch")}
                  >
                    Batch
                  </th>
                  <th
                    className="py-3 px-6 border border-slate-200 text-sm md:text-base cursor-pointer"
                    onClick={() => handleSort("semester")}
                  >
                    Semester
                  </th>
                  {/* <th className="py-3 px-6 border border-slate-200 text-sm md:text-base">
                    Language
                  </th> */}
                  {/* <th className="py-3 px-6 border border-slate-200 text-sm md:text-base">
                    Status
                  </th> */}
                  <th className="py-3 px-6 border border-slate-200 text-sm md:text-base">
                    TestCase Pass
                  </th>
                  <th className="py-3 px-6 border border-slate-200 text-sm md:text-base">
                    Submission Date
                  </th>
                  <th className="py-3 px-6 border border-slate-200 text-sm md:text-base">
                    Marks
                  </th>
                </tr>
              </thead>
              <tbody>
                {loading ? (
                  <tr>
                    <td colSpan="10" className="py-6 text-center">
                      <div className="flex flex-col items-center justify-center">
                        <div className="animate-spin rounded-full h-16 w-16 border-t-4 border-blue-500"></div>
                        <p className="mt-4 text-blue-700 text-lg font-medium">
                          Loading, please wait...
                        </p>
                      </div>
                    </td>
                  </tr>
                ) : filteredSubmissions.length > 0 ? (
                  filteredSubmissions.map((submission, index) => (
                    <tr
                      key={submission._id}
                      className={`${
                        index % 2 === 0 ? "ui-page" : "ui-surface"
                      } hover:ui-surface text-slate-600 cursor-pointer transition-all duration-200`}
                      onClick={() => navigate("/submissions/" + submission._id)}
                    >
                      <td className="py-3 px-6 border border-slate-200 text-sm md:text-base">
                        {submission.user_id.id}
                      </td>
                      <td className="py-3 px-6 border border-slate-200 text-sm md:text-base">
                        {submission.user_id.username}
                      </td>
                      <td className="py-3 px-6 border border-slate-200 text-sm md:text-base">
                        {submission.user_id.branch?.toUpperCase() || "N/A"}
                      </td>
                      <td className="py-3 px-6 border border-slate-200 text-sm md:text-base">
                        {submission.user_id.batch?.toUpperCase() || "N/A"}
                      </td>
                      <td className="py-3 px-6 border border-slate-200 text-sm md:text-base">
                        {submission.user_id.semester || "N/A"}
                      </td>
                      {/* <td className="py-3 px-6 border border-slate-200 text-sm md:text-base">
                        {submission.language || "N/A"}
                      </td> */}
                      {/* <td
                        className={`py-3 px-6 border border-slate-200 capitalize text-sm md:text-base ${
                          submission.status === "completed"
                            ? "text-green-500"
                            : "text-red-500"
                        }`}
                      >
                        {submission.status}
                      </td> */}
                      <td className="py-3 px-6 border border-slate-200 capitalize text-sm md:text-base">
                        {submission.numberOfTestCasePass != null &&
                        submission.numberOfTestCase != null
                          ? `${submission.numberOfTestCasePass}/${submission.numberOfTestCase}`
                          : "N/A"}
                      </td>
                      <td className="py-3 px-6 border border-slate-200 text-sm md:text-base">
                        {formatDate(submission?.createdAt)}
                      </td>
                      <td className="py-3 px-6 border border-slate-200 text-sm md:text-base">
                        {submission?.totalMarks ?? "N/A"}
                      </td>
                    </tr>
                  ))
                ) : (
                  <tr>
                    <td
                      colSpan="10"
                      className="py-3 px-6 text-center text-slate-600 border border-slate-200"
                    >
                      No submissions found
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    </>
  );
};

export default Dashboard;

import React, { useState, useEffect, useMemo } from "react";
import { useNavigate } from "react-router-dom";
import axiosInstance from "../../utils/axiosInstance";
import toast from "react-hot-toast";
import "../../CSS/Quiz.css";
import { useSelector } from "react-redux";
import {
  Search,
  Filter,
  Plus,
  Edit,
  Trash2,
  BarChart2,
  UserPlus,
  ChevronUp,
  ChevronDown,
  Sparkles,
} from "lucide-react";

const MakeProblem = () => {
  const user = useSelector((store) => store.app.user);
  const navigate = useNavigate();
  const [problems, setProblems] = useState([]);
  const [loading, setLoading] = useState(false);
  const [difficultyFilter, setDifficultyFilter] = useState("All");
  const [searchQuery, setSearchQuery] = useState("");
  const [showDeleteModal, setShowDeleteModal] = useState(false);
  const [problemToDelete, setProblemToDelete] = useState(null);
  const [userRole, setUserRole] = useState(null);
  const [sortConfig, setSortConfig] = useState({
    key: "createdAt",
    direction: "desc",
  });

  useEffect(() => {
    const role = user.role;
    setUserRole(role);
    fetchProblems();
  }, [user]);

  const fetchProblems = async () => {
    try {
      setLoading(true);
      const response = await axiosInstance.get(`/problems/`);
      const allProblems = Array.isArray(response.data?.problems) ? response.data.problems : [];
      console.log(allProblems);
      
      setProblems(allProblems);
    } catch (error) {
      toast.error("Error fetching problems!");
      console.error("Error fetching problems:", error);
    } finally {
      setLoading(false);
    }
  };

  const handleCreateProblem = () => {
    navigate("/problem-form");
  };

  const handleEditProblem = (problemId) => {
    navigate(`/problem-form/${problemId}`);
  };

  const handleDeleteProblem = async () => {
    try {
      await axiosInstance.delete(`/problems/${problemToDelete}`);
      toast.success("Problem deleted successfully!");
      setShowDeleteModal(false);
      setProblemToDelete(null);
      fetchProblems();
    } catch (error) {
      toast.error("Error deleting problem!");
      console.error("Error deleting problem:", error);
    }
  };

  const handleDeleteConfirmation = (problemId) => {
    setProblemToDelete(problemId);
    setShowDeleteModal(true);
  };

  const handleDashboardConfirmation = (problemId, title, difficulty, createdAt) => {
    navigate(`/dashboard/${problemId}`, {
      state: {
        problemTitle: title,
        difficulty: difficulty,
        createdAt: createdAt,
      },
    });
  };

  const assignProblem = (problemId) => {
    navigate(`/assignProblem/${problemId}`);
  };

  const cancelDelete = () => {
    setShowDeleteModal(false);
    setProblemToDelete(null);
  };

  const getSortIcon = (columnName) => {
    if (sortConfig.key !== columnName) {
      return null;
    }
    return sortConfig.direction === "asc" ? (
      <ChevronUp className="inline w-4 h-4" />
    ) : (
      <ChevronDown className="inline w-4 h-4" />
    );
  };

  const sortedProblems = useMemo(() => {
    let sortableProblems = [...problems];
    if (sortConfig !== null) {
      sortableProblems.sort((a, b) => {
        if (a[sortConfig.key] < b[sortConfig.key]) {
          return sortConfig.direction === "asc" ? -1 : 1;
        }
        if (a[sortConfig.key] > b[sortConfig.key]) {
          return sortConfig.direction === "asc" ? 1 : -1;
        }
        return 0;
      });
    }
    return sortableProblems;
  }, [problems, sortConfig]);

  const handleSort = (key) => {
    let direction = "asc";
    if (sortConfig.key === key && sortConfig.direction === "asc") {
      direction = "desc";
    }
    setSortConfig({ key, direction });
  };

  const filteredProblems = sortedProblems
    .filter((problem) =>
      difficultyFilter === "All"
        ? true
        : (problem?.difficulty || "").toLowerCase() === difficultyFilter.toLowerCase()
    )
    .filter((problem) =>
      (problem?.title || "").toLowerCase().includes(searchQuery.toLowerCase())
    );

  const formatDate = (dateString) => {
    const date = new Date(dateString);
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, "0");
    const day = String(date.getDate()).padStart(2, "0");
    const hours = String(date.getHours()).padStart(2, "0");
    const minutes = String(date.getMinutes()).padStart(2, "0");
    return `${day}-${month}-${year} ${hours}:${minutes}`;
  };

  const truncateTitle = (title, maxLength) => {
    return title && title.length > maxLength
      ? `${title.slice(0, maxLength)}...`
      : title || "Untitled";
  };

  useEffect(() => {
    if (!user) navigate("/");
  }, [user, navigate]);

  return (
    <div className="ui-page-height ui-gradient   text-slate-900">
      <div className="py-6 px-8 ui-page-top flex justify-center items-center">
        <h1 className="text-3xl font-bold text-slate-900">
          {userRole === "student" ? "Assigned Problems" : "Problem Bank"}
        </h1>
      </div>

      <div className="max-w-7xl mx-auto p-6">
        <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-4 mb-8">
          {userRole !== "student" && (
            <div className="flex items-center gap-3 flex-wrap">
              <button
                onClick={handleCreateProblem}
                className="flex items-center gap-2 ui-gradient   text-slate-900 font-semibold py-3 px-6 rounded-lg   transition-all shadow-md cursor-pointer"
              >
                <Plus className="w-5 h-5" />
                <span>Add Problem</span>
              </button>
              <button
                onClick={() => navigate("/problem-form?openAI=true")}
                className="flex items-center gap-2 ui-gradient    text-slate-900 font-semibold py-3 px-5 rounded-lg   transition-all shadow-md shadow-indigo-600/25 cursor-pointer"
              >
                <Sparkles className="w-5 h-5 text-yellow-700 animate-pulse" />
                <span>✨ Create with AI</span>
              </button>
            </div>
          )}

          <div className="flex flex-col md:flex-row gap-4 w-full md:w-auto">
            <div className="relative">
              <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                <Filter className="h-5 w-5 text-slate-600" />
              </div>
              <select
                value={difficultyFilter}
                onChange={(e) => setDifficultyFilter(e.target.value)}
                className="ui-surface text-slate-900 py-3 pl-10 pr-4 rounded-lg border border-slate-200 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent w-full md:w-48"
              >
                <option value="All">All Difficulties</option>
                <option value="easy">Easy</option>
                <option value="medium">Medium</option>
                <option value="hard">Hard</option>
              </select>
            </div>

            <div className="relative flex-grow">
              <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                <Search className="h-5 w-5 text-slate-600" />
              </div>
              <input
                type="text"
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                placeholder="Search problems..."
                className="ui-surface text-slate-900 py-3 pl-10 pr-4 rounded-lg border border-slate-200 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent w-full"
              />
            </div>
          </div>
        </div>

        <div className="ui-page rounded-lg ui-card-shadow overflow-hidden">
          <div className="overflow-x-auto">
            <table className="w-full border-collapse">
              <thead>
                <tr className="ui-surface text-slate-900 text-sm uppercase">
                  <th className="py-4 px-6 text-left">
                    <button
                      onClick={() => handleSort("_id")}
                      className="flex items-center font-semibold"
                    >
                      # {getSortIcon("_id")}
                    </button>
                  </th>
                  <th className="py-4 px-6 text-left">
                    <button
                      onClick={() => handleSort("title")}
                      className="flex items-center font-semibold"
                    >
                      Title {getSortIcon("title")}
                    </button>
                  </th>
                  <th className="py-4 px-6 text-center">
                    <button
                      onClick={() => handleSort("difficulty")}
                      className="flex items-center justify-center font-semibold"
                    >
                      Difficulty {getSortIcon("difficulty")}
                    </button>
                  </th>
                  <th className="py-4 px-6 text-center">
                    <button
                      onClick={() => handleSort("createdAt")}
                      className="flex items-center justify-center font-semibold"
                    >
                      Created Date {getSortIcon("createdAt")}
                    </button>
                  </th>
                  {userRole !== "student" && (
                    <th className="py-4 px-6 text-center">Actions</th>
                  )}
                </tr>
              </thead>
              <tbody>
                {filteredProblems.length > 0 ? (
                  filteredProblems.map((problem, index) => (
                    <tr
                      key={problem._id}
                      className="border-t border-slate-200 hover:ui-surface transition-colors"
                    >
                      <td className="py-4 px-6 text-slate-600 font-medium">
                        {index + 1}
                      </td>
                      <td
                        className="py-4 px-6"
                        onClick={() => navigate(`/problems/${problem._id}`)}
                      >
                        <div className="font-semibold capitalize text-blue-700 hover:text-blue-700 cursor-pointer transition-colors">
                          {truncateTitle(
                            problem?.title,
                            window.innerWidth < 900 ? 25 : 50
                          )}
                        </div>
                      </td>
                      <td className="py-4 px-6 text-center">
                        <span
                          className={`inline-flex items-center justify-center px-3 py-1 rounded-full text-xs font-medium ${
                            problem.difficulty === "easy"
                              ? "bg-green-50 text-green-700 border border-green-500/30"
                              : problem.difficulty === "medium"
                              ? "bg-yellow-50 text-yellow-700 border border-yellow-500/30"
                              : "bg-red-50 text-red-700 border border-red-500/30"
                          }`}
                        >
                          {(problem?.difficulty || "easy").charAt(0).toUpperCase() +
                            (problem?.difficulty || "easy").slice(1)}
                        </span>
                      </td>
                      <td className="py-4 px-6 text-center text-slate-600 text-sm">
                        {formatDate(problem.createdAt)}
                      </td>
                      {userRole !== "student" && (
                        <td className="py-4 px-6">
                          <div className="flex items-center justify-center gap-2">
                            <button
                              className="p-2 rounded-lg bg-blue-600/20 text-blue-700 hover:bg-blue-600/40 transition-colors"
                              title="Edit"
                              onClick={() => handleEditProblem(problem._id)}
                            >
                              <Edit className="w-4 h-4" />
                            </button>
                            <button
                              className="p-2 rounded-lg bg-red-600/20 text-red-700 hover:bg-red-600/40 transition-colors"
                              title="Delete"
                              onClick={() =>
                                handleDeleteConfirmation(problem._id)
                              }
                            >
                              <Trash2 className="w-4 h-4" />
                            </button>
                            <button
                              className="p-2 rounded-lg bg-green-600/20 text-green-700 hover:bg-green-600/40 transition-colors"
                              title="Dashboard"
                              onClick={() =>
                                handleDashboardConfirmation(
                                  problem._id,
                                  problem.title,
                                  problem.difficulty,
                                  problem.createdAt
                                )
                              }
                            >
                              <BarChart2 className="w-4 h-4" />
                            </button>
                            <button
                              className="p-2 rounded-lg bg-purple-600/20 text-blue-700 hover:bg-purple-600/40 transition-colors"
                              title="Assign"
                              onClick={() => assignProblem(problem._id)}
                            >
                              <UserPlus className="w-4 h-4" />
                            </button>
                          </div>
                        </td>
                      )}
                    </tr>
                  ))
                ) : (
                  <tr>
                    <td
                      colSpan={userRole !== "student" ? 5 : 4}
                      className="py-8 px-6 text-center text-slate-600"
                    >
                      <div className="flex flex-col items-center justify-center">
                        <Search className="w-12 h-12 text-slate-700 mb-3" />
                        <p className="text-lg font-medium">No problems found</p>
                        <p className="text-sm text-slate-600">
                          Try adjusting your search or filter
                        </p>
                      </div>
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        </div>
      </div>

      {showDeleteModal && (
        <div className="fixed inset-0 flex items-center justify-center z-50 bg-black bg-opacity-70">
          <div className="ui-surface p-8 rounded-lg w-11/12 max-w-md mx-auto border border-slate-200 ui-card-shadow transform transition-all">
            <div className="flex flex-col items-center">
              <div className="bg-red-500/20 p-3 rounded-full mb-4">
                <Trash2 className="w-8 h-8 text-red-500" />
              </div>
              <h3 className="text-xl font-bold mb-2 text-slate-900">
                Confirm Deletion
              </h3>
              <p className="text-slate-600 mb-6 text-center">
                Are you sure you want to delete this problem? This action cannot
                be undone.
              </p>
              <div className="flex gap-4 w-full">
                <button
                  onClick={cancelDelete}
                  className="flex-1 py-3 px-4 ui-surface hover:ui-subtle text-slate-900 rounded-lg transition-colors"
                >
                  Cancel
                </button>
                <button
                  onClick={handleDeleteProblem}
                  className="flex-1 py-3 px-4 bg-red-600 hover:bg-red-50 text-slate-900 rounded-lg transition-colors"
                >
                  Delete
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default MakeProblem;

import { useState } from "react";
import axiosInstance from "../../utils/axiosInstance";
import { useSelector } from "react-redux";

