            <select
              value={difficulty}
              onChange={(e) => setDifficulty(e.target.value)}
              className="mt-1 block w-full p-2 border border-slate-200 rounded-md"
              required
            >
              <option value="easy">Easy</option>
              <option value="medium">Medium</option>
              <option value="hard">Hard</option>
            </select>
          </div>

          <div>
            <label className="block text-sm font-medium text-slate-700">
              Input Format
            </label>
            <input
              type="text"
              value={inputFormat}
              onChange={(e) => setInputFormat(e.target.value)}
              className="mt-1 block w-full p-2 border border-slate-200 rounded-md"
              required
            />
          </div>
        </div>

        <div className="grid grid-cols-2 gap-4 mb-4">
          <div>
            <label className="block text-sm font-medium text-slate-700">
              Output Format
            </label>
            <input
              type="text"
              value={outputFormat}
              onChange={(e) => setOutputFormat(e.target.value)}
              className="mt-1 block w-full p-2 border border-slate-200 rounded-md"
              required
            />
          </div>

          <div>
            <label className="block text-sm font-medium text-slate-700">
              Constraints
            </label>
            <input
              type="text"
              value={constraints}
              onChange={(e) => setConstraints(e.target.value)}
              className="mt-1 block w-full p-2 border border-slate-200 rounded-md"
            />
          </div>
        </div>

        {/* Sample Input/Output */}
        <div className="mb-4">
          <h3 className="text-xl font-semibold mb-2">Sample Input/Output</h3>
          {sampleIO.map((sio, index) => (
            <div key={index} className="mb-4">
              <input
                type="text"
                placeholder="Sample Input"
                value={sio.input}
                onChange={(e) =>
                  handleSampleIOChange(index, "input", e.target.value)
                }
                className="mt-1 block w-full p-2 border border-slate-200 rounded-md mb-2"
              />
              <input
                type="text"
                placeholder="Sample Output"
                value={sio.output}
                onChange={(e) =>
                  handleSampleIOChange(index, "output", e.target.value)
                }
                className="mt-1 block w-full p-2 border border-slate-200 rounded-md"
              />
              <button
                type="button"
                onClick={() => handleRemoveSampleIO(index)}
                className="text-red-600 hover:text-red-800 mt-2"
              >
                Remove
              </button>
            </div>
          ))}
          <button
            type="button"
            onClick={handleAddSampleIO}
            className="px-4 py-2 bg-blue-500 text-slate-900 rounded-md"
          >
            Add Sample IO
          </button>
        </div>

        {/* Test Cases */}
        <div className="mb-4">
          <h3 className="text-xl font-semibold mb-2">Test Cases</h3>
          {testCases.map((testCase, index) => (
            <div key={index} className="mb-4 p-4 border rounded-md ui-subtle">
              <textarea
                placeholder="Input"
                value={testCase.inputs}
                onChange={(e) =>
                  handleTestCaseChange(index, "inputs", e.target.value)
                }
                className="block w-full p-2 border border-slate-200 rounded-md mb-2"
                rows="3"
              />
              <textarea
                placeholder="Expected Output"
                value={testCase.outputs}
                onChange={(e) =>
                  handleTestCaseChange(index, "outputs", e.target.value)
                }
                className="block w-full p-2 border border-slate-200 rounded-md mb-2"
                rows="3"
              />
              <input
                type="number"
                placeholder="Marks"
                value={testCase.marks}
                onChange={(e) =>
                  handleTestCaseChange(index, "marks", e.target.value)
                }
                className="block w-full p-2 border border-slate-200 rounded-md"
              />
              <button
                type="button"
                onClick={() => handleRemoveTestCase(index)}
                className="text-red-600 hover:text-red-800 mt-2"
              >
                Remove Test Case
              </button>
            </div>
          ))}
          <button
            type="button"
            onClick={handleAddTestCase}
            className="px-4 py-2 bg-blue-500 text-slate-900 rounded-md"
          >
            Add Test Case
          </button>
        </div>

        <div className="mb-4">
          <h4 className="font-medium">Total Marks: {totalMarks}</h4>
        </div>

        {/* Tags */}
        <div className="mb-4">
          <label className="block text-sm font-medium text-slate-700">
            Tags
          </label>
          <input
            type="text"
            placeholder="Comma-separated tags"
            value={tags.join(", ")}
            onChange={(e) =>
              setTags(e.target.value.split(",").map((tag) => tag.trim()))
            }
            className="mt-1 block w-full p-2 border border-slate-200 rounded-md"
          />
        </div>

        {/* Submit Button */}
        <button
          type="submit"
          className="px-6 py-2 bg-green-500 text-slate-900 font-semibold rounded-md"
        >
          Submit Problem
        </button>
      </form>
    </div>
  );
};

export default ProblemForm;

import React, { useState, useEffect } from "react";
import { useSelector } from "react-redux";
import toast from "react-hot-toast";
import { useNavigate, useParams, useLocation } from "react-router-dom";
import { Sparkles } from "lucide-react";
import axiosInstance from "../../utils/axiosInstance"; // Custom axios instance for API calls
import ConfirmationModal from "../ConfirmationModal"; // Import the modal component
import AIProblemModal from "./AIProblemModal";

const DIFFICULTY = {
  EASY: "easy",
  MEDIUM: "medium",
  HARD: "hard",
};

const ProblemForm = () => {
  const navigate = useNavigate();
  const { id } = useParams();
  const location = useLocation();
  const user = useSelector((state) => state.app.user);
  const [assignLoading, setAssignLoading] = useState(false); // For button-specific loading

  const [problemData, setProblemData] = useState({
    title: "",
    description: "",
    difficulty: DIFFICULTY.EASY,
    inputFormat: "",
    outputFormat: "",
    sampleIO: [{ input: "", output: "" }],
    constraints: "",
    tags: "",
    totalMarks: 0,
    testCases: [
      {
        inputs: "",
        outputs: "",
        marks: 0,
        cpu_time_limit: 1,
        memory_limit: 128,
        is_hidden: false,
      },
    ],
  });

  const [isEditing, setIsEditing] = useState(false);
  const [errors, setErrors] = useState({});
  const [isModalOpenInternal, setIsModalOpenInternal] = useState(false);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [modalMessage, setModalMessage] = useState("");
  const [isAIModalOpen, setIsAIModalOpen] = useState(false);

  // Auto-open AI modal if URL contains openAI=true
  useEffect(() => {
    const params = new URLSearchParams(location.search);
    if (params.get("openAI") === "true") {
      setIsAIModalOpen(true);
    }
  }, [location.search]);

  const handleApplyAIProblem = (aiProblem) => {
    const formattedTestCases = (aiProblem.testCases || []).map((tc) => ({
      inputs: tc.inputs || "",
      outputs: tc.outputs || "",
      marks: parseInt(tc.marks, 10) || 10,
      cpu_time_limit: parseFloat(tc.cpu_time_limit) || 1,
      memory_limit: parseInt(tc.memory_limit, 10) || 128,
      is_hidden: Boolean(tc.is_hidden),
    }));

    const total = formattedTestCases.reduce((sum, tc) => sum + tc.marks, 0);

    setProblemData({
      title: aiProblem.title || "",
      description: aiProblem.description || "",
      difficulty: aiProblem.difficulty || DIFFICULTY.EASY,
      inputFormat: aiProblem.inputFormat || "",
      outputFormat: aiProblem.outputFormat || "",
      sampleIO:
        aiProblem.sampleIO && aiProblem.sampleIO.length > 0
          ? aiProblem.sampleIO
          : [{ input: "", output: "" }],
      constraints: aiProblem.constraints || "",
      tags: Array.isArray(aiProblem.tags)
        ? aiProblem.tags.join(", ")
        : aiProblem.tags || "",
      totalMarks: total,
      testCases:
        formattedTestCases.length > 0
          ? formattedTestCases
          : [
              {
                inputs: "",
                outputs: "",
                marks: 0,
                cpu_time_limit: 1,
                memory_limit: 128,
                is_hidden: false,
              },
            ],
    });

    setErrors({});
  };

  // Fetch problem if editing
  useEffect(() => {
    setAssignLoading(true); // Start loading
    if (id) {
      setIsEditing(true);

      const fetchProblem = async () => {
        try {
          const response = await axiosInstance.get(
            `/problems/getProblemByIdForUpdate/${id}`
          );
          // console.log(response.data);
          const fetchedData = response.data;
          // console.log(response.data)

          setProblemData({
            title: fetchedData.title,
            description: fetchedData.description,
            difficulty: fetchedData.difficulty || DIFFICULTY.EASY,
            inputFormat: fetchedData.inputFormat,
            outputFormat: fetchedData.outputFormat,
            sampleIO: fetchedData.sampleIO || [{ input: "", output: "" }],
            constraints: fetchedData.constraints,
            tags: fetchedData.tags,
            totalMarks: fetchedData.totalMarks || 0,
            testCases: fetchedData.testCases.map((testCase) => ({
              inputs: testCase.inputs,
              outputs: testCase.outputs,
              marks: testCase.marks,
              memory_limit: testCase.memory_limit || 1,
              cpu_time_limit: testCase?.cpu_time_limit || 1,
              is_hidden: testCase.is_hidden || false,
            })),
          });
          setAssignLoading(false); // Start loading
        } catch (error) {
          toast.error("Failed to load problem data");
          console.error(error);
          setAssignLoading(false); // Start loading
        }
        
      };
      fetchProblem();
    } else {
      setIsEditing(false);
      setAssignLoading(false); // Start loading
    }
  }, [id]);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setProblemData({ ...problemData, [name]: value });
    setErrors({ ...errors, [name]: false });
  };

  const handleSampleChange = (index, e) => {
    const { name, value } = e.target;
    const newSampleIO = [...problemData.sampleIO];
    newSampleIO[index][name] = value;
    setProblemData({ ...problemData, sampleIO: newSampleIO });
  };

  const addSampleIO = () => {
    setProblemData({
      ...problemData,
      sampleIO: [...problemData.sampleIO, { input: "", output: "" }],
    });
  };

  const removeSampleIO = (index) => {
    const newSampleIO = problemData.sampleIO.filter((_, i) => i !== index);
    setProblemData({ ...problemData, sampleIO: newSampleIO });
  };

  const handleTestCaseChange = (index, field, value) => {
    const newTestCases = [...problemData.testCases];

    if (
      field === "marks" ||
      field === "cpu_time_limit" ||
      field === "memory_limit"
    ) {
      const numValue = parseInt(value, 10) || 0;
      if (numValue < 0) return;
      newTestCases[index][field] = numValue;
    } else if (field === "is_hidden") {
      newTestCases[index][field] = !newTestCases[index][field]; // Toggle boolean
    } else {
      newTestCases[index][field] = value;
    }

    setProblemData({ ...problemData, testCases: newTestCases });
    updateTotalMarks(newTestCases);
  };

  const addTestCase = () => {
    setProblemData({
      ...problemData,
      testCases: [
        ...problemData.testCases,
        {
          inputs: "",
          outputs: "",
          marks: 0,
          cpu_time_limit: 1,
          memory_limit: 128,
          is_hidden: false,
        },
      ],
    });
  };

  const handleRemoveTestCase = (index) => {
    const newTestCases = problemData.testCases.filter((_, i) => i !== index);
    setProblemData({ ...problemData, testCases: newTestCases });
    updateTotalMarks(newTestCases);
  };

  const updateTotalMarks = (testCases) => {
    const total = testCases.reduce((sum, tc) => sum + tc.marks, 0);
    setProblemData((prevData) => ({ ...prevData, totalMarks: total }));
  };

  const renderTestCases = () => {
    return problemData.testCases.map((testCase, index) => {
      // Determine if there's an error for this test case
      const hasError =
        errors[`testCase_${index}`] ||
        (errors.totalMarks && problemData.totalMarks === 0);

      return (
        <div
          key={index}
          className={`mb-6 p-6 border rounded-lg ui-card-shadow ${
            hasError ? "border-red-600" : "border-slate-200"
          } ui-page`}
        >
          <div className="flex justify-between items-center mb-4">
            <h3 className="text-lg font-semibold text-slate-600">
              Test Case {index + 1}
            </h3>

            <button
              type="button"
              onClick={() =>
                handleTestCaseChange(index, "is_hidden", !testCase.is_hidden)
              }
              className={`px-4 py-2 font-medium rounded-md transition flex items-center gap-2 text-slate-900 shadow-md ${
                testCase.is_hidden
                  ? "bg-red-600 hover:bg-red-50"
                  : "bg-green-600 hover:bg-green-700"
              }`}
            >
              {testCase.is_hidden ? "🔒 Hidden" : "👁 Show"}
            </button>
          </div>

          {/* Input Field */}
          <label className="block text-slate-600 mb-2">Input</label>
          <textarea
            placeholder="Enter test case input"
            value={testCase.inputs}
            onChange={(e) =>
              handleTestCaseChange(index, "inputs", e.target.value)
            }
            className={`w-full p-3 ui-surface border ${
              hasError ? "border-red-600" : "border-slate-200"
            } rounded-md mb-4 shadow-sm focus:outline-none focus:ring-2 focus:ring-blue-500`}
            rows="3"
          />

          {/* Expected Output Field */}
          <label className="block text-slate-600 mb-2">Expected Output</label>
          <textarea
            placeholder="Enter expected output"
            value={testCase.outputs}
            onChange={(e) =>
              handleTestCaseChange(index, "outputs", e.target.value)
            }
            className={`w-full p-3 ui-surface border ${
              hasError ? "border-red-600" : "border-slate-200"
            } rounded-md mb-4 shadow-sm focus:outline-none focus:ring-2 focus:ring-blue-500`}
            rows="3"
          />

          {/* Marks Field */}
          <label className="block text-slate-600 mb-2">Marks</label>
          <input
            type="number"
            placeholder="Enter marks for this test case"
            value={testCase.marks}
            onChange={(e) =>
              handleTestCaseChange(index, "marks", e.target.value)
            }
            className="w-full p-3 ui-surface border border-slate-200 rounded-md shadow-sm focus:ring-2 focus:ring-blue-500 mb-4"
          />

          {/* CPU Time Limit */}
          <label className="block text-slate-600 mb-2">
            CPU Time Limit (seconds 1s - 15s)
          </label>
          <input
            type="number"
            min="1"
            max="15"
            placeholder="Enter CPU time limit (sec)"
            value={testCase.cpu_time_limit}
            onChange={(e) => {
              const value = Math.min(15, Math.max(1, Number(e.target.value)));
              handleTestCaseChange(index, "cpu_time_limit", value);
            }}
            onInput={(e) => {
              if (e.target.value < 1) e.target.value = 1;
              if (e.target.value > 15) e.target.value = 15;
            }}
            className="w-full p-3 ui-surface border border-slate-200 rounded-md shadow-sm focus:ring-2 focus:ring-blue-500 mb-4"
          />

          {/* Memory Limit */}
          <label className="block text-slate-600 mb-2">
            Memory Limit (MB 1MB - 256MB)
          </label>
          <input
            type="number"
            min="1"
            max="256"
            placeholder="Enter memory limit (MB)"
            value={testCase.memory_limit}
            onChange={(e) => {
              const value = Math.min(256, Math.max(1, Number(e.target.value)));
              handleTestCaseChange(index, "memory_limit", value);
            }}
            onInput={(e) => {
              if (e.target.value < 1) e.target.value = 1;
              if (e.target.value > 256) e.target.value = 256;
            }}
            className="w-full p-3 ui-surface border border-slate-200 rounded-md shadow-sm focus:ring-2 focus:ring-blue-500 mb-4"
          />

          {/* Hidden/Show Toggle Button */}

          {/* Remove Test Case Button */}
          {problemData.testCases.length > 1 && (
            <button
              type="button"
              onClick={() => handleRemoveTestCase(index)}
              className="mt-4 px-4 py-2 w-full text-red-600 border border-red-600 rounded-md hover:bg-red-600 hover:text-slate-900 transition"
            >
              Remove Test Case
            </button>
          )}
        </div>
      );
    });
  };

  // Form validation
  const validateForm = () => {
    const newErrors = {};

    // Validate problem fields
    if (!problemData.title) newErrors.title = true;
    if (!problemData.description) newErrors.description = true;
    if (!problemData.inputFormat) newErrors.inputFormat = true;
    if (!problemData.outputFormat) newErrors.outputFormat = true;
    if (
      problemData.sampleIO.some((sample) => !sample.input || !sample.output)
    ) {
      newErrors.sampleIO = true;
    }
    if (!problemData.constraints) newErrors.constraints = true;
    if (!problemData.tags) newErrors.tags = true;

    // Validate test cases
    problemData.testCases.forEach((testCase, index) => {
      if (!testCase.inputs || !testCase.outputs || testCase.marks < 0) {
        newErrors[`testCase_${index}`] = true;
        // console.log("Test case error", index);
      }
    });

    if (problemData.totalMarks === 0) {
      newErrors.totalMarks = true;
      // Mark all test cases with an error if total marks is 0
      problemData.testCases.forEach((_, index) => {
        newErrors[`testCase_${index}`] = true;
      });
    }

    setErrors(newErrors); // Store errors for styling
    return newErrors;
  };

  // Handle form submission
  const handleSubmit = async (e) => {
    e.preventDefault();
    const newErrors = validateForm();
    if (Object.keys(newErrors).length > 0) {
      setErrors(newErrors);
      toast.error("Please fill in all required fields!");
      return;
    }
    setIsModalOpenInternal(true);
  };

  const confirmSubmit = async () => {
    const actionType = isEditing ? "edit" : "create";
    const apiMethod = isEditing ? axiosInstance.put : axiosInstance.post;
    const apiEndpoint = isEditing ? `/problems/${id}` : "/problems/";

    const tags =
      typeof problemData.tags === "string" && problemData.tags.trim() !== ""
        ? problemData.tags.split(",").map((tag) => tag.trim())
        : problemData.tags;

    try {
      const response = await apiMethod(apiEndpoint, {
        ...problemData,
        tags,
      });

      if (response.status === 200 || response.status === 201) {
        toast.success(
          isEditing
            ? "Problem updated successfully!"
            : "Problem created successfully!"
        );
        setTimeout(() => {
          setIsModalOpenInternal(false);
          navigate("/make-problem");
        }, 100);
      }
    } catch (error) {
      const errorMsg =
        error?.response?.data?.message ||
        (isEditing
          ? "Failed to update problem. Please try again."
          : "Failed to create problem. Please try again.");
      toast.error(errorMsg);
      setTimeout(() => {
        setIsModalOpenInternal(false);
      }, 2000);
      console.error("Submit problem error:", error);
    }
  };

  const handleBackClick = () => {
    setIsModalOpen(true);
  };

  const handleConfirmBack = () => {
    setIsModalOpen(false);
    navigate(-1);
  };

  const handleCloseModal = () => {
    setIsModalOpen(false);
  };

  return (
    <>
      <div className="relative ui-page-height ui-page text-slate-900">
        <div className="mx-auto p-4 ui-surface text-slate-900 rounded-lg ui-card-shadow">
          <h1 className="text-2xl font-bold mt-10 mb-6 text-center">
            {isEditing ? "Edit Problem" : "Create Problem"}
          </h1>

          <div className="flex items-center justify-between mb-6 flex-wrap gap-3">
            <button
              onClick={handleBackClick}
              className="px-4 py-1 sm:px-6 sm:py-2 bg-blue-500 text-slate-900 text-base sm:text-sm rounded-lg hover:bg-blue-600 transition duration-200 ease-in-out cursor-pointer"
            >
              Back
            </button>

            {!isEditing && (
              <button
                type="button"
                onClick={() => setIsAIModalOpen(true)}
                className="flex items-center gap-2 px-4 py-2 sm:px-5 sm:py-2.5 ui-gradient      text-slate-900 font-medium text-sm rounded-lg ui-card-shadow shadow-indigo-600/30 transition transform hover:-translate-y-0.5 cursor-pointer"
              >
                <Sparkles className="w-4 h-4 text-yellow-700 animate-pulse" />
                <span>✨ AI Problem Assistant</span>
              </button>
            )}
          </div>

          <ConfirmationModal
            isOpen={isModalOpen}
            onClose={handleCloseModal}
            onConfirm={handleConfirmBack}
          />

          <AIProblemModal
            isOpen={isAIModalOpen}
            onClose={() => setIsAIModalOpen(false)}
            onApplyProblem={handleApplyAIProblem}
          />

          {assignLoading && (
            <div className="fixed inset-0 bg-black bg-opacity-70 flex items-center justify-center z-50">
              <div className="flex flex-col items-center">
                <svg
                  className="animate-spin h-12 w-12 text-blue-700 mb-4"
                  xmlns="http://www.w3.org/2000/svg"
                  fill="none"
                  viewBox="0 0 24 24"
                >
                  <circle
                    className="opacity-25"
                    cx="12"
                    cy="12"
                    r="10"
                    stroke="currentColor"
                    strokeWidth="4"
                  ></circle>
                  <path
                    className="opacity-75"
                    fill="currentColor"
                    d="M4 12a8 8 0 018-8v8H4z"
                  ></path>
                </svg>
                <p className="text-slate-900 text-lg font-semibold">Loading...</p>
              </div>
            </div>
          )}

          <form onSubmit={handleSubmit} className="space-y-6">
            {/* Title */}
            <div>
              <label className="block text-1xl font-medium mb-2">Title</label>
              <input
                type="text"
                name="title"
                value={problemData.title}
                onChange={handleChange}
                className={`w-full p-4  ui-surface border rounded-lg mb-4 shadow-sm focus:outline-none focus:ring-2 focus:ring-blue-500  ${
                  errors.title ? "border-red-500" : "border-slate-200"
                }`}
                placeholder="Enter problem title"
              />
            </div>

            {/* Similar fields for Description, Difficulty, Input/Output Format, Sample IO, Constraints, Tags, and Score */}
            {/* Description */}
            <div>
              <label className="block text-1xl font-medium mb-2">
                Description
              </label>
              <textarea
                name="description"
                value={problemData.description}
                onChange={handleChange}
                className={`w-full p-4  ui-surface border rounded-lg mb-4 shadow-sm focus:outline-none focus:ring-2 focus:ring-blue-500  ${
                  errors.description ? "border-red-500" : "border-slate-200"
                } `}
                placeholder="Describe the problem"
                rows="6"
              />
            </div>

            {/* Difficulty */}

            <div>
              <label className="block text-1xl font-medium mb-2">
                Difficulty
              </label>
              <select
                name="difficulty"
                value={problemData.difficulty}
                onChange={handleChange}
                className="w-full p-4  ui-surface border border-slate-200 rounded-lg mb-4 shadow-sm focus:outline-none focus:ring-2 focus:ring-blue-500 "
              >
                <option value={DIFFICULTY.EASY}>Easy</option>
                <option value={DIFFICULTY.MEDIUM}>Medium</option>
                <option value={DIFFICULTY.HARD}>Hard</option>
              </select>
            </div>

            {/* Input Format */}
            <div>
              <label className="block text-1xl font-medium mb-2">
                Input Format
              </label>
              <textarea
                type="text"
                name="inputFormat"
                value={problemData.inputFormat}
                onChange={handleChange}
                className={`w-full p-4  ui-surface border rounded-lg mb-4 shadow-sm focus:outline-none focus:ring-2 focus:ring-blue-500  ${
                  errors.inputFormat ? "border-red-500" : "border-slate-200"
                }`}
                placeholder="Specify the input format"
                rows={4}
              />
            </div>

            {/* Output Format */}
            <div>
              <label className="block text-1xl font-medium mb-2">
                Output Format
              </label>
              <textarea
                type="text"
                name="outputFormat"
                value={problemData.outputFormat}
                onChange={handleChange}
                className={`w-full p-4  ui-surface border rounded-lg mb-4 shadow-sm focus:outline-none focus:ring-2 focus:ring-blue-500  ${
                  errors.outputFormat ? "border-red-500" : "border-slate-200"
                }`}
                placeholder="Specify the output format"
                rows={4}
              />
            </div>

            {/* Sample IO */}
            <div>
              <label className="block text-1xl font-medium mb-2">
                Sample Input/Output
              </label>
              {problemData.sampleIO.map((sample, index) => (
                <div key={index} className="space-y-2 mb-4">
                  <textarea
                    type="text"
                    name="input"
                    value={sample.input}
                    onChange={(e) => handleSampleChange(index, e)}
                    placeholder="Sample Input"
                    className={`w-full p-4  ui-surface border rounded-lg mb-4 shadow-sm focus:outline-none focus:ring-2 focus:ring-blue-500  ${
                      errors.sampleIO ? "border-red-500" : "border-slate-200"
                    }`}
                    rows={3}
                  />
                  <textarea
                    type="text"
                    name="output"
                    value={sample.output}
                    onChange={(e) => handleSampleChange(index, e)}
                    placeholder="Sample Output"
                    className={`w-full p-4  ui-surface border rounded-lg mb-4 shadow-sm focus:outline-none focus:ring-2 focus:ring-blue-500  ${
                      errors.sampleIO ? "border-red-500" : "border-slate-200"
                    }`}
                    rows={3}
                  />

                  {/* Disable Remove button if only one sample exists */}
                  {problemData.sampleIO.length > 1 && (
                    <button
                      type="button"
                      onClick={() => removeSampleIO(index)}
                      className="bg-red-500 mt-5 text-slate-900 font-semibold py-2 px-4 rounded hover:bg-red-600 transition duration-300 ease-in-out"
                    >
                      Remove Sample
                    </button>
                  )}
                </div>
              ))}

              <button
                type="button"
                onClick={addSampleIO}
                className="text-blue-700 mt-2"
              >
                + Add More
              </button>
            </div>

            {/* Constraints */}
            <div>
              <label className="block text-1xl font-medium mb-2">
                Constraints
              </label>
              <textarea
                name="constraints"
                value={problemData.constraints}
                onChange={handleChange}
                className={`w-full p-4  ui-surface border rounded-lg mb-4 shadow-sm focus:outline-none focus:ring-2 focus:ring-blue-500  ${
                  errors.constraints ? "border-red-500" : "border-slate-200"
                }`}
                placeholder="Specify the problem constraints"
                rows={4}
              />
            </div>

            {/* Tags */}
            <div>
              <label className="block text-1xl font-medium mb-2">Tags</label>
              <input
                type="text"
                name="tags"
                value={problemData.tags}
                onChange={handleChange}
                className={`w-full p-4  ui-surface border rounded-lg mb-4 shadow-sm focus:outline-none focus:ring-2 focus:ring-blue-500  ${
                  errors.tags ? "border-red-500" : "border-slate-200"
                }
                `}
                placeholder="Comma-separated tags (e.g., arrays, sorting)"
              />
            </div>

            <div>
              <label className="block text-1xl font-medium mb-2">
                Total Marks
              </label>
              <input
                type="number"
                name="totalMarks"
                value={problemData.totalMarks}
                className="w-full p-4 ui-surface border border-slate-200 rounded-lg mb-4 shadow-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
                placeholder="Total Marks for all test cases"
                min={0}
                readOnly
              />
            </div>

            <div>
              {renderTestCases()}
              <button
                type="button"
                onClick={addTestCase}
                className="text-blue-700 mt-2 mb-2"
              >
                + Add More Test Case
              </button>

              <div className="ui-subtle border border-slate-200 rounded-md p-4 my-4">
                <h4 className="text-lg sm:text-base font-semibold text-slate-700 mb-2">
                  Important Note:
                </h4>
                <p className="text-slate-700 sm:text-sm leading-relaxed text-justify">
                  As an admin, when you create a problem, please ensure that the
                  input and output examples are accurate. These examples are
                  crucial for testing the submitted code to determine its
                  correctness.
                </p>
              </div>
            </div>

            <div className="text-center">
              <button
                type="submit"
                className="px-6 py-3 bg-blue-500 text-slate-900 rounded-lg hover:bg-blue-600"
              >
                {isEditing ? "Update Problem" : "Create Problem"}
              </button>
            </div>
          </form>
        </div>
      </div>

      {/* Confirmation Modal */}
      <div
        className={`${
          isModalOpenInternal ? "block" : "hidden"
        } fixed top-0 left-0 w-full h-full ui-page bg-opacity-50 flex items-center justify-center z-50`}
      >
        <div className="bg-white p-8 rounded-lg ui-card-shadow text-slate-700 text-center">
          <p className="text-2xl font-bold mb-4">Confirmation</p>
          <p>{modalMessage || "Are you sure you want to proceed?"}</p>
          <div className="flex justify-center gap-4 mt-6">
            <button
              className="px-6 py-2 bg-red-500 text-slate-900 rounded-lg hover:bg-red-600"
              onClick={() => setIsModalOpenInternal(false)}
            >
              Cancel
            </button>
            <button
              className="px-6 py-2 bg-green-500 text-slate-900 rounded-lg hover:bg-green-600"
              onClick={confirmSubmit}
            >
              Confirm
            </button>
          </div>
        </div>
      </div>
    </>
  );
};

export default ProblemForm;

import React, { useEffect, useRef, useState } from "react";
import { useParams, useNavigate } from "react-router-dom";
import axiosInstance from "../../utils/axiosInstance";
import "../../CSS/ProblemShow.css";
import Submission from "./Submission";
import Solution from "./Solution";
import Statement from "./Statement";
import CodeEditor from "../CodeEditor/CodeEditor";
import toast from "react-hot-toast";
import { useLocation } from "react-router-dom";

const ProblemShow = () => {
  const { id } = useParams();
  const location = useLocation();
  const { state } = location;
  const { startTime, endTime } = state || {};
  const navigate = useNavigate();
  const [problem, setProblem] = useState(null);
  const [language, setLanguage] = useState("java");
  const [code, setCode] = useState("");
  const [activeTab, setActiveTab] = useState("statement");
  const [latestSubmission, setLatestSubmission] = useState(null); // Store latest submission

  

  const handleSubmission = (submission) => {
    setLatestSubmission(submission); // Update with the new submission
    setActiveTab("submissions");
  };

  const codeTemplates = {
    java:
      "public class Main {\n  public static void main(String[] args) {\n    // Your code here\n  }\n}",
    python: 'if __name__ == "__main__":\n    # Your code here\n    pass',
    cpp:
      "#include <iostream>\nint main() {\n  // Your code here\n  return 0;\n}",
  };

  const resizableRef = useRef(null);

  useEffect(() => {
    const fetchProblem = async () => {
      try {
        const response = await axiosInstance.get(`/problems/${id}`);
        setProblem(response.data);
        // console.log(response.data)
      } catch (error) {
        toast.error("Failed to load problem data");
        // console.error("Failed to load problem data", error);
      }
    };

    fetchProblem();
  }, [id]);

  useEffect(() => {
    setCode(codeTemplates[language]);
  }, [language]);

  const handleResize = (event) => {
    const resizable = resizableRef.current;
    const containerWidth = resizable.parentElement.getBoundingClientRect()
      .width;
    const newWidth = ((event.clientX / containerWidth) * 100).toFixed(2);
    if (newWidth >= 35 && newWidth <= 75) {
      resizable.style.flexBasis = `${newWidth}%`;
    }
  };

  if (!problem) {
    return (
      <div className="flex justify-center items-center ui-page-height ui-page">
        <div className="loader border-t-4 border-blue-500 rounded-full w-12 h-12 animate-spin"></div>
        <span className="ml-4 text-slate-900 text-lg">
          Loading problem details...
        </span>
      </div>
    );
  }

  return (
    <div className="problem-container">
      <div
        ref={resizableRef}
        className="resizable ui-page p-4 flex flex-col"
      >
        <div className="sticky top-0 z-10 pb-4">
          <button
            onClick={() => navigate(-1)}
            aria-label="Back to problems"
            className="mb-3 ui-surface hover:ui-subtle text-slate-900 px-4 py-2 rounded-full flex items-center shadow-md hover:ui-card-shadow transition-all duration-200 ease-in-out"
          >
            <svg
              className="MuiSvgIcon-root _icon_1pe2i_343"
              style={{ width: "15px" }}
              focusable="false"
              viewBox="0 0 24 24"
              aria-hidden="true"
              fill="currentColor"
            >
              <path d="M20 11H7.83l5.59-5.59L12 4l-8 8 8 8 1.41-1.41L7.83 13H20v-2z"></path>
            </svg>
          </button>

          <div className="flex justify-between items-center mb-4">
            <h1 className="text-2xl font-semibold text-slate-900 tracking-tight">
              {problem.title}
            </h1>
          </div>

          <div className="border-b border-slate-200 mb-4">
            <button
              onClick={() => setActiveTab("statement")}
              className={`py-2 px-4 ${
                activeTab === "statement"
                  ? "border-b-2 border-blue-500 text-blue-700"
                  : "text-slate-600 hover:text-slate-900"
              } transition-all duration-200`}
            >
              Statement
            </button>
            <button
              onClick={() => setActiveTab("submissions")}
              className={`py-2 px-4 ${
                activeTab === "submissions"
                  ? "border-b-2 border-blue-500 text-blue-700"
                  : "text-slate-600 hover:text-slate-900"
              } transition-all duration-200`}
            >
              Submissions
            </button>
            <button
              onClick={() => setActiveTab("solution")}
              className={`py-2 px-4 ${
                activeTab === "solution"
                  ? "border-b-2 border-blue-500 text-blue-700"
                  : "text-slate-600 hover:text-slate-900"
              } transition-all duration-200`}
            >
              Solution
            </button>
          </div>
        </div>

        <div className="flex-1 overflow-y-auto custom-scrollbar">
          {activeTab === "statement" && <Statement problem={problem} />}
          {activeTab === "submissions" && (
            <Submission
              problemId={problem._id}
              latestSubmission={latestSubmission} // Pass latest submission
            />
          )}
          {activeTab === "solution" && <Solution />}
        </div>
      </div>

      {/* Divider */}
      <div
        className="divider"
        onMouseDown={() => {
          window.addEventListener("mousemove", handleResize);
          window.addEventListener("mouseup", () => {
            window.removeEventListener("mousemove", handleResize);
          });
        }}
      ></div>

      {/* Right Column: Code Editor */}
      <CodeEditor
        language={language}
        setLanguage={setLanguage}
        code={code}
        setCode={setCode}
        problem={problem}
        onSubmission={handleSubmission}
      />
    </div>
  );
};

export default ProblemShow;

import React from "react";

const Solution = () => {
  return (
    <div>
      <h3 className="font-bold text-slate-900">Solution</h3>
      <p className="text-slate-600">
        Here, you can view the solution or editorial for this problem once
        available.
      </p>
    </div>
  );
};

export default Solution;

import React, { useState } from "react";

const StudentTable = ({
  users,
  selectedStudents,
  handleSelectAll,
  handleSelectStudent,
  filters,
  updateFilter,
  loading,
  currentPage,
  itemsPerPage,
  handlePageChange,
  totalPages,
}) => {
  const [sortConfig, setSortConfig] = useState({
    key: "id",
    direction: "asc",
  });

  console.log(users);

  // Apply filters
  const filteredUsers = users.filter((user) => {
    const branchMatch =
      filters.branch === "ALL" || user.branch === filters.branch;
    const semesterMatch =
      filters.semester === "ALL" ||
      user.semester.toString().toUpperCase() === filters.semester.toUpperCase();
    const batchMatch =
      filters.batch === "ALL" ||
      user.batch.toUpperCase() === filters.batch.toUpperCase();

    return branchMatch && semesterMatch && batchMatch;
  });

  // Sorting logic
  const sortedUsers = [...filteredUsers].sort((a, b) => {
    const keyA = a[sortConfig.key]?.toString().toLowerCase() || "";
    const keyB = b[sortConfig.key]?.toString().toLowerCase() || "";

    // Custom sorting for semester types like A1, B1, etc.
    if (sortConfig.key === "semester") {
      const parseSemester = (val) => {
        const match = val.match(/^([A-D])(\d)$/);
        if (match) {
          const [, letter, num] = match;
          return [letter.charCodeAt(0), parseInt(num, 10)];
        }
        return [0, parseInt(val, 10)];
      };
      const [charA, numA] = parseSemester(keyA);
      const [charB, numB] = parseSemester(keyB);

      if (charA !== charB)
        return sortConfig.direction === "asc" ? charA - charB : charB - charA;
      return sortConfig.direction === "asc" ? numA - numB : numB - numA;
    }

    // Default string sorting
    if (keyA < keyB) return sortConfig.direction === "asc" ? -1 : 1;
    if (keyA > keyB) return sortConfig.direction === "asc" ? 1 : -1;
    return 0;
  });

  // Pagination logic
  const paginatedUsers = sortedUsers.slice(
    (currentPage - 1) * itemsPerPage,
    currentPage * itemsPerPage
  );

  const handleSort = (key) => {
    setSortConfig((prev) => {
      const isSameKey = prev.key === key;
      const newDirection = isSameKey
        ? prev.direction === "asc"
          ? "desc"
          : "asc"
        : "asc"; // Corrected this line
      return { key, direction: newDirection };
    });
  };

  return (
    <div className="overflow-x-auto p-4">
      {/* Filters */}
      <div className="mb-6 flex flex-col gap-4 sm:flex-row sm:justify-between items-center pl-4">
        <div className="flex flex-wrap gap-4 justify-center sm:justify-start">
          <select
            value={filters.branch}
            onChange={(e) => updateFilter("branch", e.target.value)}
            className="ui-surface text-slate-900 px-4 py-2 rounded focus:outline-none focus:ring-2 focus:ring-blue-500"
          >
            <option value="ALL">All Branches</option>
            <option value="cspit-it">CSPIT-IT</option>
            <option value="cspit-cse">CSPIT-CSE</option>
            <option value="cspit-ce">CSPIT-CE</option>
          </select>
          <select
            value={filters.semester}
            onChange={(e) => updateFilter("semester", e.target.value)}
            className="ui-surface text-slate-900 px-4 py-2 rounded focus:outline-none focus:ring-2 focus:ring-blue-500"
          >
            <option value="ALL">All Semesters</option>
            {[...Array(8)].map((_, i) => (
              <option key={`semester-${i + 1}`} value={i + 1}>
                Semester {i + 1}
              </option>
            ))}
          </select>
          <select
            value={filters.batch}
            onChange={(e) => updateFilter("batch", e.target.value)}
            className="ui-surface text-slate-900 px-4 py-2 rounded focus:outline-none focus:ring-2 focus:ring-blue-500"
          >
            <option value="ALL">All Batches</option>
            {["a", "b", "c", "d"].map((letter) =>
              [1, 2].map((num) => (
                <option key={`${letter}${num}`} value={`${letter}${num}`}>
                  {`${letter}${num}`}
                </option>
              ))
            )}
          </select>
        </div>
      </div>

      <div className="mb-4 text-slate-600 pl-4">
        <span className="font-bold">{filteredUsers.length}</span>{" "}
        {filteredUsers.length === 1 ? "student" : "students"} found.
      </div>

      {/* Students Table */}
      <div className="p-4">
        <div className="overflow-hidden rounded-lg border border-slate-200 ui-page ui-card-shadow">
          <table className="w-full border-collapse text-left text-slate-600">
            <thead>
              <tr className="border-b border-slate-200 ui-page">
                <th className="py-4 px-4 text-center">
                  <button
                    onClick={handleSelectAll}
                    className="rounded-lg bg-blue-600 px-3 py-2 text-sm font-medium text-slate-900 transition-all hover:bg-blue-700 hover:ui-card-shadow hover:shadow-blue-500/20 focus:ring-2 focus:ring-blue-500 focus:ring-offset-2 focus:ring-offset-gray-900"
                  >
                    {selectedStudents.length === filteredUsers.length
                      ? "Deselect All"
                      : "Select All"}
                  </button>
                </th>
                <th
                  className="group cursor-pointer py-4 px-4 text-center text-sm font-medium uppercase tracking-wider text-slate-600 transition-colors hover:text-slate-900"
                  onClick={() => handleSort("id")}
                >
                  <div className="flex items-center justify-center space-x-1">
                    <span>ID</span>
                    {sortConfig.key === "id" && (
                      <span className="text-blue-700">
                        {sortConfig.direction === "asc" ? " ↑" : " ↓"}
                      </span>
                    )}
                  </div>
                </th>
                <th
                  className="group cursor-pointer py-4 px-4 text-center text-sm font-medium uppercase tracking-wider text-slate-600 transition-colors hover:text-slate-900"
                  onClick={() => handleSort("username")}
                >
                  <div className="flex items-center justify-center space-x-1">
                    <span>Username</span>
                    {sortConfig.key === "username" && (
                      <span className="text-blue-700">
                        {sortConfig.direction === "asc" ? " ↑" : " ↓"}
                      </span>
                    )}
                  </div>
                </th>
                <th className="py-4 px-4 text-center text-sm font-medium uppercase tracking-wider text-slate-600">
                  Branch
                </th>
                <th
                  className="group cursor-pointer py-4 px-4 text-center text-sm font-medium uppercase tracking-wider text-slate-600 transition-colors hover:text-slate-900"
                  onClick={() => handleSort("semester")}
                >
                  <div className="flex items-center justify-center space-x-1">
                    <span>Semester</span>
                    {sortConfig.key === "semester" && (
                      <span className="text-blue-700">
                        {sortConfig.direction === "asc" ? " ↑" : " ↓"}
                      </span>
                    )}
                  </div>
                </th>
                <th className="py-4 px-4 text-center text-sm font-medium uppercase tracking-wider text-slate-600">
                  Batch
                </th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-200">
              {loading ? (
                <tr>
                  <td colSpan="6" className="py-8 text-center">
                    <div className="flex flex-col items-center justify-center">
                      <div className="h-16 w-16 animate-spin rounded-full border-4 border-slate-200 border-t-blue-500"></div>
                      <p className="mt-4 text-lg font-medium text-blue-700">
                        Loading, please wait...
                      </p>
                    </div>
                  </td>
                </tr>
              ) : paginatedUsers.length > 0 ? (
                paginatedUsers.map((student, index) => (
                  <tr
                    key={student._id}
                    className={`transition-colors ${
                      index % 2 === 0 ? "ui-page" : "ui-page"
                    } hover:ui-page`}
                  >
                    <td className="py-4 px-4 text-center">
                      <input
                        type="checkbox"
                        checked={selectedStudents.includes(student._id)}
                        onChange={() => handleSelectStudent(student._id)}
                        className="h-4 w-4 rounded border-slate-200 ui-surface text-blue-700 focus:ring-2 focus:ring-blue-500 focus:ring-offset-2 focus:ring-offset-gray-900"
                      />
                    </td>
                    <td className="whitespace-nowrap py-4 px-4 text-center font-medium text-slate-900">
                      {student.id?.toUpperCase()}
                    </td>
                    <td className="py-4 px-4 text-center text-slate-900">
                      {student.username}
                    </td>
                    <td className="py-4 px-4 text-center">
                      <span className="inline-flex rounded-full ui-surface px-3 py-1 text-sm font-medium text-slate-900">
