import React, { useState, useEffect, useReducer } from "react";
import toast from "react-hot-toast";
import ProfileLeft from "./ProfileLeft";
import ProfileRight from "./ProfileRight";
import SubmissionPage from "../SubmissionPage";
import { useSelector, useDispatch } from "react-redux";
import axiosInstance from "../../utils/axiosInstance";
import { fetchSubmissions } from "../../redux/slices/submissionSlice";
import {
  startNavigation,
  endNavigation,
} from "../../redux/slices/historySlice";
import { useLocation } from "react-router-dom";
import { isPageCached } from "../../utils/transitionManager";
import { motion, AnimatePresence } from "framer-motion";

const initialState = {
  username: "",
  gender: "",
  location: "",
  birthday: "",
  github: "",
  linkedIn: "",
  skills: "",
  education: "",
  name: "",
  bio: "",
  email: "",
};

const reducer = (state, action) => {
  switch (action.type) {
    case "SET_FORM_DATA":
      return { ...state, ...action.payload };
    case "RESET_FORM":
      return initialState;
    default:
      return state;
  }
};

const Profile = () => {
  const [isEditing, setIsEditing] = useState(false);
  const [formData, dispatch] = useReducer(reducer, initialState);
  const user = useSelector((state) => state.app.user);
  const imageUrl = useSelector((state) => state.app.imageUrl);
  const reduxDispatch = useDispatch();
  const submissions = useSelector((state) => state.submissions.submissions);
  const submissionsLoading = useSelector((state) => state.submissions.loading);
  const location = useLocation();
  const isCached = isPageCached(location.pathname);
  const [rightColumnKey, setRightColumnKey] = useState("submissions");

  useEffect(() => {
    // Only signal navigation start if we're not already cached
    if (!isCached) {
      reduxDispatch(startNavigation());
    }

    return () => {};
  }, []);

  useEffect(() => {
    if (user) {
      // No need to signal navigation start again
      // Just update form data from existing Redux state
      dispatch({
        type: "SET_FORM_DATA",
        payload: {
          username: user.username || "",
          name: user.profile?.name || "",
          gender: user.profile?.gender || "",
          bio: user.profile?.bio || "",
          location: user.profile?.location || "",
          birthday: user.profile?.birthday
            ? user.profile.birthday.slice(0, 10)
            : "",
          github: user.profile?.github || "",
          skills: user.profile?.skills || "",
          education: user.profile?.education || "",
          linkedIn: user.profile?.linkedIn || "",
          email: user.email || "",
        },
      });

      // Only end navigation if we started it
      if (!isCached) {
        reduxDispatch(endNavigation());
      }
    }
  }, [user, reduxDispatch, isCached]);

  // Only fetch submissions if we don't have them already
  useEffect(() => {
    // Don't make API call if:
    // 1. We don't have a user yet
    // 2. We already have submissions data
    // 3. We're currently loading submissions
    // 4. The page is cached (recently visited)
    if (user && submissions.length === 0 && !submissionsLoading && !isCached) {
      reduxDispatch(fetchSubmissions({ page: 1, limit: 7 }));
    }
  }, [reduxDispatch, user, submissions.length, submissionsLoading, isCached]);

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    dispatch({ type: "SET_FORM_DATA", payload: { [name]: value } });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!formData.username || !formData.email) {
      toast.error("Username and email are required.");
      return;
    }

    try {
      const response = await axiosInstance.put("user/update", { ...formData });

      if (response.data.success) {
        // First update UI state to appear responsive
        toast.success("Profile updated successfully.");

        // Then smoothly transition out of edit mode
        setRightColumnKey("submissions");
        setTimeout(() => {
          setIsEditing(false);
        }, 300);
      } else {
        toast.error(response.data.message || "Profile update failed.");
      }
    } catch (error) {
      toast.error(
        error.response?.data?.message || "An error occurred. Please try again."
      );
      console.error(error);
    }
  };

  const toggleEdit = () => {
    setRightColumnKey(isEditing ? "submissions" : "edit");
    setTimeout(() => {
      setIsEditing(!isEditing);
    }, 50);
  };

  if (!user) {
    return (
      <div className="text-center text-slate-600 ui-page-height flex items-center justify-center">
        <p>User data could not be loaded. Please refresh the page.</p>
      </div>
    );
  }

  return (
    <div className="relative ui-page-height ui-page text-slate-900">
      <section className="ui-page-top">
        <div className="container mx-auto grid grid-cols-1 md:grid-cols-4 gap-6 p-4">
          <div className="md:col-span-1">
            <ProfileLeft
              formData={formData}
              toggleEdit={toggleEdit}
              isEditing={isEditing}
              imageUrl={imageUrl || null} // Placeholder image
            />
          </div>

          <div className="md:col-span-3">
            {isEditing ? (
              <ProfileRight
                formData={formData}
                handleInputChange={handleInputChange}
                handleSubmit={handleSubmit}
                user={user || {}} // Provide an empty object as fallback
              />
            ) : (
              <div>
                {submissionsLoading ? (
                  <div className="flex justify-center items-center p-10 h-64">
                    <div className="animate-pulse flex flex-col items-center">
                      <div className="h-12 w-12 border-t-2 border-b-2 border-blue-500 rounded-full animate-spin mb-4"></div>
                      <div className="text-blue-700">Loading submissions...</div>
                    </div>
                  </div>
                ) : (
                  <SubmissionPage />
                )}
              </div>
            )}
          </div>
        </div>
      </section>
    </div>
  );
};

export default Profile;

import React, { useState, useEffect, useRef } from "react";
import { User, Github, Linkedin, Edit, Upload, X } from "lucide-react";
import axiosInstance from "../../utils/axiosInstance";
import toast from "react-hot-toast";
import { useDispatch, useSelector } from "react-redux";
import { setImageUrl } from "../../redux/userSlice";

const ProfileLeft = ({ formData, toggleEdit, isEditing, imageUrl }) => {
  const [selectedFile, setSelectedFile] = useState(null);
  const [imagePreview, setImagePreview] = useState(null);
  const [profilePic, setProfilePic] = useState(imageUrl || null);
  const [loading, setLoading] = useState(false);
  const [contentReady, setContentReady] = useState(false);
  const globalLoading = useSelector((state) => state.app.isLoading);
  const fileInputRef = useRef(null);
  const dispatch = useDispatch();

  // Preload and render content with a small delay for smooth transition
  useEffect(() => {
    const timer = setTimeout(() => {
      setContentReady(true);
    }, 100);
    return () => clearTimeout(timer);
  }, []);

  useEffect(() => {
    if (imageUrl) {
      setProfilePic(imageUrl);
      // Preload image to avoid flickering on render
      const img = new Image();
      img.src = imageUrl;
    }
  }, [imageUrl]);

  useEffect(() => {
    if (selectedFile) {
      const previewUrl = URL.createObjectURL(selectedFile);
      setImagePreview(previewUrl);
      return () => {
        URL.revokeObjectURL(previewUrl);
      };
    } else {
      setImagePreview(null);
    }
  }, [selectedFile]);

  const githubURL = formData.github
    ? `https://github.com/${formData.github}`
    : null;
  const linkedInURL = formData.linkedIn || null;

  // Add new optimized methods
  const handleFileChange = (event) => {
    const file = event.target.files[0];
    if (file) {
      setSelectedFile(file);
    }
  };

  const handleUpdateProfilePic = async () => {
    if (!selectedFile) return;
    const uploadData = new FormData();
    uploadData.append("avatar", selectedFile);

    try {
      setLoading(true);
      // Create a temporary local preview immediately for better UX
      const localPreview = URL.createObjectURL(selectedFile);
      setProfilePic(localPreview);
      
      const response = await axiosInstance.post("/user/upload-avatar", uploadData, {
        headers: { "Content-Type": "multipart/form-data" },
      });
      
      if (response.status === 200) {
        toast.success(response.data.message);
        if (response.data.profilePicUrl) {
          // Replace local preview with server URL once available
          setProfilePic(response.data.profilePicUrl);
          dispatch(setImageUrl(response.data.profilePicUrl));
        } else {
          dispatch(setImageUrl(localPreview));
        }
        setSelectedFile(null);
      }
    } catch (error) {
      toast.error("Upload Error");
      console.error("Upload Error:", error);
      // Revert to previous image if there's an error
      setProfilePic(imageUrl);
    } finally {
      setLoading(false);
    }
  };

  const handleRemoveImage = async () => {
    try {
      setLoading(true);
      // Optimistically remove the image for better UX
      const oldImage = profilePic;
      setProfilePic(null);
      
      const response = await axiosInstance.delete("/user/profile/remove-profile-pic");
      if (response.status === 200) {
        toast.success("Profile picture removed successfully");
        if (oldImage && oldImage.startsWith("blob:")) {
          URL.revokeObjectURL(oldImage);
        }
        setSelectedFile(null);
        dispatch(setImageUrl(null));
      } else {
        // Restore the image if there was an error
        setProfilePic(oldImage);
      }
    } catch (error) {
      toast.error("Remove Error");
      console.error("Remove Error:", error);
      // Restore the image on error
      setProfilePic(imageUrl);
    } finally {
      setLoading(false);
    }
  };

  const combinedLoading = loading || globalLoading;

  return (
    <div 
      className={`sticky top-20 ui-gradient   text-slate-900 rounded-lg ui-card-shadow p-8 border border-slate-200 transition-opacity duration-500 ease-in-out ${
        contentReady ? "opacity-100" : "opacity-0"
      }`}
    >
      <div className="flex flex-col items-center">
        <div className="relative mb-6">
          {combinedLoading ? (
            <div className="w-40 h-40 rounded-full ui-surface flex items-center justify-center">
              <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-blue-500"></div>
            </div>
          ) : (
            <div className="relative group">
              <div className="w-40 h-40 rounded-full overflow-hidden ring-4 ring-blue-500 ui-card-shadow transition-all duration-300 hover:ring-blue-400">
                {selectedFile ? (
                  <img
                    src={imagePreview}
                    alt="Selected"
                    className="w-full h-full object-cover transition-opacity duration-300"
                  />
                ) : profilePic ? (
                  <img
                    src={profilePic}
                    alt="Profile"
                    className="w-full h-full object-cover transition-opacity duration-300"
                    onError={(e) => {
                      // Handle image load errors
                      e.target.onerror = null;
                      e.target.src = "/default-img.png"; // Set to a default placeholder image
                      e.target.classList.add("ui-surface"); // Add a fallback background color
                    }}
                  />
